def human(n):
    if n is None:
        return "-"
    try:
        n = float(n)
    except (TypeError, ValueError):
        return "-"
    for u in ("B", "KB", "MB", "GB", "TB"):
        if n < 1024 or u == "TB":
            return ("%.0f %s" if u == "B" else "%.2f %s") % (n, u)
        n /= 1024.0


def _fmt_dur(sec):
    """秒 → 「1 小时 02 分 03 秒」/「12.3 秒」这种人读的时长。"""
    try:
        s = float(sec)
    except (TypeError, ValueError):
        return "-"
    if s < 1:
        return "%.2f 秒" % s
    if s < 60:
        return "%.1f 秒" % s
    m, s = divmod(int(s), 60)
    if m < 60:
        return "%d 分 %02d 秒" % (m, s)
    h, m = divmod(m, 60)
    return "%d 小时 %02d 分 %02d 秒" % (h, m, s)


def fmt_time(ts):
    if not ts:
        return ""
    return time.strftime("%Y-%m-%d %H:%M", time.localtime(ts))


def hostname():
    try:
        return socket.gethostname()
    except Exception:
        return "unknown"


def new_token(n=6):
    """生成 n 位纯数字访问令牌。

    用 secrets 而不是 random：random 是可预测的伪随机，令牌如果被猜出来，
    加密传输就只剩"防君子"了。纯数字 6 位是刻意的取舍——方便手输。
    """
    return "".join(secrets.choice("0123456789") for _ in range(n))


def cert_fingerprint(cert_path):
    """给证书算个短指纹，方便两端核对是不是连对了机器。"""
    try:
        with open(cert_path, "rb") as f:
            der = ssl.PEM_cert_to_DER_cert(f.read().decode("ascii", "replace"))
        h = hashlib.sha256(der).hexdigest().upper()
        return ":".join(h[i:i + 2] for i in range(0, 16, 2))
    except Exception:
        return ""


def _ip_rank(ip):
    """排在前面的更可能是"真实局域网地址"（虚拟机/APIPA 网卡排在后面）。"""
    if ip.startswith("192.168."):
        return 0
    if ip.startswith("10."):
        return 1
    if ip.startswith("172."):
        try:
            if 16 <= int(ip.split(".")[1]) <= 31:
                return 2
        except (ValueError, IndexError):
            pass
        return 4
    if ip.startswith("169.254."):
        return 6
    return 3


def local_ips():
    ips = set()
    try:
        for info in socket.getaddrinfo(socket.gethostname(), None, socket.AF_INET):
            ips.add(info[4][0])
    except Exception:
        pass
    try:
        s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        s.connect(("8.8.8.8", 80))
        ips.add(s.getsockname()[0])
        s.close()
    except Exception:
        pass
    return sorted((i for i in ips if not i.startswith("127.")), key=lambda i: (_ip_rank(i), i))


def _win_logical_drives():
    """用 GetLogicalDrives 拿盘符位图 —— **只读内核里的一个位掩码，零磁盘 I/O**。

    这是 v3.8.1 修「掉线网络盘把界面卡死」的关键：`os.path.exists("Z:\\")`
    在映射盘掉线时要走 SMB 超时（实测不可达 UNC 2703ms，最坏 20 秒+），
    而它过去是**在主线程**里被逐个调用的。
    """
    try:
        import ctypes
        mask = int(ctypes.windll.kernel32.GetLogicalDrives())
    except Exception:
        return []
    return ["%s:\\" % chr(ord("A") + i) for i in range(26) if mask & (1 << i)]


def _drive_kind(p):
    """盘符类型（2 可移动 / 3 本地 / 4 网络 / 5 光驱 / 6 内存盘）。0 = 未知。"""
    try:
        import ctypes
        return int(ctypes.windll.kernel32.GetDriveTypeW(ctypes.c_wchar_p(p)))
    except Exception:
        return 0


def _drive_display(p):
    """给盘符取 Win11 资源管理器那个「数据(F:)」式的显示名。

    与面包屑（`_crumb_segments` → `_volume_label`）保持**同一套**口径 ——
    过去只有面包屑是「系统(C:)」，而「此电脑」列表与盘符下拉框还是裸的
    `C:\\`，同一块界面上两种写法，看着像两个东西。

    ⚠ 网络盘**绝不**去问卷标：`GetVolumeInformationW` 对掉线的映射盘同样会
    走 SMB 超时，那正是我们要躲开的阻塞。类型判定用 GetDriveTypeW（纯内存
    查表，`DRIVE_REMOTE` 立刻返回）。
    """
    letter = (p or "")[:2]
    if len(letter) < 2 or letter[1] != ":":
        return p or ""
    kind = _drive_kind(p)
    if kind != 4:                       # 网络盘不问卷标（会阻塞）
        lbl = _volume_label(p)
        if lbl:
            return "%s (%s)" % (lbl, letter)
    name = {2: "可移动磁盘", 3: "本地磁盘", 4: "网络位置",
            5: "DVD 驱动器", 6: "内存盘"}.get(kind, "磁盘")
    return "%s (%s)" % (name, letter)


# 盘符列表缓存。`os.path.exists` 的阻塞是"结构性问题"，光靠缓存治不了根，
# 但缓存把"每帧都去问一次磁盘"变成"5 秒问一次"，配合下面的不阻塞枚举，
# 主线程就彻底不与慢设备打交道了。
_ROOTS_CACHE = {"t": 0.0, "v": None}
_ROOTS_TTL = 5.0


def list_roots(force=False):
    """返回可浏览的根: Windows 是各盘符, 其他系统是 /。

    v3.8.1 两项改动：
      ① **不再阻塞主线程** —— 改用 GetLogicalDrives()（位掩码，零 I/O），
         而不是对 26 个字母逐个 `os.path.exists`。掉线的网络映射盘过去会让
         「此电脑」层和盘符下拉框整个卡住（实测 2703ms，SMB 最坏 20 秒+）。
      ② 每项多一个 `disp` 字段（「系统(C:)」式的友好名），供界面显示；
         `name` / `path` 维持原样，老调用点与测试不受影响。

    ⚠ 空光驱 / 空读卡器现在也会出现在列表里（GetLogicalDrives 报"有设备"，
    与资源管理器一致）。用户已确认这类空盘不用特殊处理；真的点进去时，
    列目录发生在工作线程里，不会再冻界面。
    """
    now = time.time()
    if (not force) and _ROOTS_CACHE["v"] is not None \
            and now - _ROOTS_CACHE["t"] < _ROOTS_TTL:
        return _ROOTS_CACHE["v"]
    if os.name == "nt":
        letters = _win_logical_drives()
        if not letters:
            # 极少数环境拿不到位图（受限沙箱）：退回老办法，但只是兜底。
            letters = ["%s:\\" % c for c in string.ascii_uppercase
                       if os.path.exists("%s:\\" % c)]
        out = [{"name": p, "path": p, "disp": _drive_display(p)} for p in letters]
        if not out:
            out = [{"name": "C:\\", "path": "C:\\", "disp": _drive_display("C:\\")}]
    else:
        out = [{"name": "/", "path": "/", "disp": "/"}]
    _ROOTS_CACHE["t"] = now
    _ROOTS_CACHE["v"] = out
    return out


def root_disp(r):
    """取一个根的显示名（老数据没有 disp 时退回 name）。"""
    return (r or {}).get("disp") or (r or {}).get("name") or ""


def norm_path(p):
    return os.path.abspath(os.path.expandvars(os.path.expanduser(p or "")))


def inside_any(path, roots):
    """path 是否落在 roots 里。**roots 为空 = 什么都不许**（v3.8.1 语义收紧）。

    ⚠ 旧实现 `if not roots: return True` —— 空列表被当成"不限制"。
    发送端把共享范围清空时，用户以为"不共享了"，实际是"共享整机"，
    方向正好相反。现在空 = 拒绝；"全部磁盘"由 `SenderApp.share_all`
    显式表达（它会把 roots 填成全部盘符，不会留空）。
    """
    if not roots:
        return False
    rp = os.path.realpath(path)
    for r in roots:
        rr = os.path.realpath(r)
        if rp == rr or rp.startswith(rr.rstrip("\\/") + os.sep) or (rr.endswith(os.sep) and rp.startswith(rr)):
            return True
    return False


def share_scope_text(roots, share_all=True):
    """把共享范围渲染成一行短文案（服务设置那一行用）。"""
    if share_all:
        return "全部磁盘（默认）"
    if not roots:
        return "（未共享任何目录）"
    if len(roots) <= 2:
        return "；".join(roots)
    return "%s 等 %d 个目录" % (roots[0], len(roots))


def load_conf():
    try:
        with open(CONF, "r", encoding="utf-8") as f:
            return json.load(f)
    except Exception:
        return {}


def save_conf(d):
    try:
        with open(CONF, "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    except Exception:
        pass


def md5_file(path, chunk=CHUNK):
    h = hashlib.md5()
    with open(path, "rb") as f:
        while True:
            b = f.read(chunk)
            if not b:
                break
            h.update(b)
    return h.hexdigest()


# ==========================================================================
# 续传元数据（v3.8.1）
# --------------------------------------------------------------------------
# 为什么必须有它：断点续传只按"文件大小"判断能不能接着传，是有静默损坏风险的。
# 远端那个文件如果被换成了**更大的、内容完全不同的**文件，本地残件仍然是
# "另一个文件的合法前缀" —— 拼起来长度对得上、内容却是坏的。旧实现只挡了
# `offset > size` 这一种情况，正好漏掉最危险的那种。
# 做法：第一次开始写残件时，把一个 {size, mtime} 元数据写到 `<part>.meta`；
# 续传前先比一次，对不上就丢弃残件从头来。
# ==========================================================================

def _part_meta_path(part_path):
    return part_path + ".meta"


def write_part_meta(part_path, size, mtime):
    try:
        with open(_part_meta_path(part_path), "w", encoding="utf-8") as f:
            json.dump({"size": int(size or 0), "mtime": float(mtime or 0)}, f)
    except Exception:
        pass


def _read_part_meta(part_path):
    try:
        with open(_part_meta_path(part_path), "r", encoding="utf-8") as f:
            d = json.load(f)
        return d if isinstance(d, dict) else None
    except Exception:
        return None


def check_part_meta(part_path, size, mtime):
    """残件还配得上当前源文件吗？返回 True 才允许接着传。

    没有元数据（老版本留下的残件）→ 谨慎起见判为**不可续传**，
    宁可重下一遍，也不冒拼出脏文件的风险。
    """
    meta = _read_part_meta(part_path)
    if not meta:
        return False
    try:
        if int(meta.get("size") or -1) != int(size or 0):
            return False
        mt = float(meta.get("mtime") or 0)
        if mtime and mt and abs(mt - float(mtime)) > 1.0:
            return False
    except (TypeError, ValueError):
        return False
    return True


def drop_part(part_path):
    """删掉残件与它的元数据。"""
    for p in (part_path, _part_meta_path(part_path)):
        try:
            os.remove(p)
        except OSError:
            pass


# ==========================================================================
# 缩略图（v3.8.1）—— 用 Windows Shell 的 IShellItemImageFactory
# --------------------------------------------------------------------------
# 为什么不用 Pillow：打包解释器是 3.8.10 x86，实测**没有 PIL**，而引入它会让
# exe 明显变大。Windows 自带的 Shell 缩略图有几个好处：
#   · 零依赖，Win7 起就有；
#   · 图片、视频封面、Office 文档、PDF 全都能出图，与资源管理器所见一致；
#   · 直接拿到 HBITMAP，读成像素后可以用项目里**已有**的 `_png()` 编码成 PNG
#     （客户端 Tk 8.6 原生支持 PNG，所以客户端一个图像库都不用装）。
# ==========================================================================

def _hbitmap_to_pixels(hbm, w, h):
    """HBITMAP → (w, h, bytes) 的 BGRA 像素（已上下翻正）。失败返回 None。"""
    import ctypes
    from ctypes import wintypes as _wt
    gdi = ctypes.windll.gdi32
    user = ctypes.windll.user32

    class BITMAPINFOHEADER(ctypes.Structure):
        _fields_ = [("biSize", _wt.DWORD), ("biWidth", _wt.LONG),
                    ("biHeight", _wt.LONG), ("biPlanes", _wt.WORD),
                    ("biBitCount", _wt.WORD), ("biCompression", _wt.DWORD),
                    ("biSizeImage", _wt.DWORD), ("biXPelsPerMeter", _wt.LONG),
                    ("biYPelsPerMeter", _wt.LONG), ("biClrUsed", _wt.DWORD),
                    ("biClrImportant", _wt.DWORD)]

    class BITMAPINFO(ctypes.Structure):
        _fields_ = [("bmiHeader", BITMAPINFOHEADER), ("bmiColors", _wt.DWORD * 3)]

    bi = BITMAPINFO()
    bi.bmiHeader.biSize = ctypes.sizeof(BITMAPINFOHEADER)
    bi.bmiHeader.biWidth = w
    bi.bmiHeader.biHeight = -h            # 负 = 自上而下，省一次翻转
    bi.bmiHeader.biPlanes = 1
    bi.bmiHeader.biBitCount = 32
    bi.bmiHeader.biCompression = 0        # BI_RGB
    buf = ctypes.create_string_buffer(w * h * 4)
    hdc = user.GetDC(0)
    try:
        got = gdi.GetDIBits(hdc, hbm, 0, h, buf, ctypes.byref(bi), 0)
    finally:
        user.ReleaseDC(0, hdc)
    if not got:
        return None
    return buf.raw


def _bgra_rows(raw, w, h):
    """BGRA 平铺字节 → `_png()` 要的 [[(r,g,b,a), …], …]。

    一律给 alpha=255：Shell 缩略图是**不透明**位图，很多驱动出来的 alpha
    通道全是 0，直接用会得到一张全透明的 PNG（Tk 显示为空白）。
    """
    rows = []
    stride = w * 4
    for y in range(h):
        base = y * stride
        row = []
        for x in range(w):
            i = base + x * 4
            row.append((raw[i + 2], raw[i + 1], raw[i], 255))
        rows.append(row)
    return rows


def _trash_path(path):
    """把文件/文件夹送进**回收站**（Windows）；成功 True，失败或非 Windows 返回 False。

    为什么不能直接 os.remove：本机栏是"用户自己的电脑"，删掉就找不回来
    是很容易造成真实损失的（远端删除有明确的双重确认，本机这一侧同样
    要留退路）。回收站是 Windows 用户对"删除"的默认预期。
    调用方在失败时会自动降级成真删，不会因为 API 不可用而卡住功能。
    """
    if os.name != "nt":
        return False
    try:
        import ctypes
        from ctypes import wintypes as _wt

        class SHFILEOPSTRUCTW(ctypes.Structure):
            _fields_ = [("hwnd", _wt.HWND),
                        ("wFunc", _wt.UINT),
                        ("pFrom", ctypes.c_void_p),
                        ("pTo", ctypes.c_void_p),
                        ("fFlags", ctypes.c_ushort),
                        ("fAnyOperationsAborted", _wt.BOOL),
                        ("hNameMappings", ctypes.c_void_p),
                        ("lpszProgressTitle", ctypes.c_void_p)]

        FO_DELETE = 3
        FOF_SILENT = 0x0004
        FOF_NOCONFIRMATION = 0x0010
        FOF_ALLOWUNDO = 0x0040          # ← 有它才是"回收站"，没有就是彻底删除
        FOF_NOERRORUI = 0x0400
        # SHFileOperationW 要求 pFrom 是**双 NUL 结尾**的多字符串；
        # create_unicode_buffer(len+1) 自带收尾 NUL，再手工补一个就够。
        buf = ctypes.create_unicode_buffer(os.path.abspath(path) + "\x00")
        op = SHFILEOPSTRUCTW()
        op.hwnd = None
        op.wFunc = FO_DELETE
        op.pFrom = ctypes.cast(buf, ctypes.c_void_p)
        op.pTo = None
        op.fFlags = (FOF_ALLOWUNDO | FOF_NOCONFIRMATION
                     | FOF_SILENT | FOF_NOERRORUI)
        r = ctypes.windll.shell32.SHFileOperationW(ctypes.byref(op))
        return int(r) == 0 and not op.fAnyOperationsAborted
    except Exception:
        return False


_GDIP = {"state": 0, "token": None}      # 0=未试 -1=不可用 1=可用


def _gdiplus_start():
    """初始化 GDI+（每进程只做一次）。Win7 起 gdiplus.dll 是系统自带组件。"""
    if _GDIP["state"]:
        return _GDIP["state"] > 0
    if os.name != "nt":
        _GDIP["state"] = -1
        return False
    try:
        import ctypes
        from ctypes import wintypes as _wt

        class STARTUPINPUT(ctypes.Structure):
            _fields_ = [("GdiplusVersion", _wt.UINT),
                        ("DebugCallback", ctypes.c_void_p),
                        ("SuppressBackgroundThread", ctypes.c_void_p),
                        ("SuppressExternalCodecs", ctypes.c_void_p)]

        si = STARTUPINPUT()
        si.GdiplusVersion = 1
        tok = ctypes.c_void_p()
        hr = ctypes.windll.gdiplus.GdiplusStartup(
            ctypes.byref(tok), ctypes.byref(si), None)
        if hr == 0:
            _GDIP["token"] = tok
            _GDIP["state"] = 1
        else:
            _GDIP["state"] = -1
    except Exception:
        _GDIP["state"] = -1
    return _GDIP["state"] > 0


def shell_thumbnail_png(path, w=160, h=160):
    """要一张 PNG 缩略图；两条路都拿不到才返回 None（调用方退回类型图标）。

    v3.8.2：先走 Shell（能出视频封面 / Office / PDF 的图），失败再退 GDI+
    （能出 JPEG/PNG/BMP/GIF/TIFF）。**两条都要有** —— 实测 Shell 在部分
    机器上对所有文件都返回 E_NOINTERFACE，只留 Shell 就等于没有缩略图。
    """
    data = _shell_thumbnail_png(path, w, h)
    if data:
        return data
    return gdiplus_thumbnail_png(path, w, h)


def gdiplus_thumbnail_png(path, w=160, h=160):
    """用 GDI+ 解码图片并缩到 w×h，编码成 PNG；拿不到返回 None。

    v3.8.2 新增 —— 这是「大图标模式看不到图片预览」的正面修复。
    为什么必须有这条兜底：Shell 的 `IShellItemImageFactory` 在本机对
    **任何文件**都返回 `E_NOINTERFACE(0x80004002)`（已实测），于是
    `_shell_thumbnail_png` 恒为 None，大图标视图永远只剩类型图标。
    GDI+ 是 Windows 自带（XP 起就有，Win7 必然有），能解 JPEG/PNG/BMP/
    GIF/TIFF/WMF/EMF，不引入任何外部依赖 —— 打包体积也不变。
    """
    if os.name != "nt" or not _gdiplus_start():
        return None
    try:
        import ctypes
        # 结构体在这里就地定义：`ctypes` 是本文件按需导入的（不少地方是在
        # 函数里 import），放到模块级会在导入 lanshare_gui 时就 NameError。
        class _GpRect(ctypes.Structure):
            _fields_ = [("X", ctypes.c_int), ("Y", ctypes.c_int),
                        ("Width", ctypes.c_int), ("Height", ctypes.c_int)]

        class _GpBitmapData(ctypes.Structure):
            _fields_ = [("width", ctypes.c_uint), ("height", ctypes.c_uint),
                        ("stride", ctypes.c_int), ("PixelFormat", ctypes.c_int),
                        ("Scan0", ctypes.c_void_p), ("Reserved", ctypes.c_void_p)]

        gdip = ctypes.windll.gdiplus
    except Exception:
        return None
    img = ctypes.c_void_p()
    try:
        hr = gdip.GdipCreateBitmapFromFile(ctypes.c_wchar_p(os.path.abspath(path)),
                                           ctypes.byref(img))
    except Exception:
        return None
    if hr != 0 or not img:
        return None
    try:
        thumb = ctypes.c_void_p()
        hr = gdip.GdipGetImageThumbnail(img, int(w), int(h),
                                        ctypes.byref(thumb), None, None)
        if hr != 0 or not thumb:
            return None
        try:
            tw, th = ctypes.c_int(), ctypes.c_int()
            gdip.GdipGetImageWidth(thumb, ctypes.byref(tw))
            gdip.GdipGetImageHeight(thumb, ctypes.byref(th))
            tw, th = int(tw.value), int(th.value)
            if tw <= 0 or th <= 0 or tw > 4096 or th > 4096:
                return None
            rc = _GpRect(0, 0, tw, th)
            bd = _GpBitmapData()
            # ImageLockModeRead = 1，PixelFormat32bppARGB = 0x0026200A
            hr = gdip.GdipBitmapLockBits(thumb, ctypes.byref(rc), 1, 0x0026200A,
                                         ctypes.byref(bd))
            if hr != 0 or not bd.Scan0:
                return None
            try:
                stride = int(bd.stride)
                if stride < tw * 4:
                    return None
                raw = ctypes.string_at(bd.Scan0, stride * th)
            finally:
                gdip.GdipBitmapUnlockBits(thumb, ctypes.byref(bd))
            # BGRA → RGBA。alpha 全 0 时说明这个解码器没给 alpha（JPEG 常见），
            # 一律补 255，否则整张图会变成全透明（Tk 里看着就是空白）。
            rows = []
            any_alpha = False
            for y in range(th):
                base = y * stride
                row = []
                for x in range(tw):
                    i = base + x * 4
                    b, g, r, a = raw[i], raw[i + 1], raw[i + 2], raw[i + 3]
                    if a:
                        any_alpha = True
                    row.append((r, g, b, a))
                rows.append(row)
            if not any_alpha:
                rows = [[(r, g, b, 255) for (r, g, b, _a) in row] for row in rows]
            return _png(tw, th, rows)
        finally:
            try:
                gdip.GdipDisposeImage(thumb)
            except Exception:
                pass
    finally:
        try:
            gdip.GdipDisposeImage(img)
        except Exception:
            pass


def _shell_thumbnail_png(path, w=160, h=160):
    """走 Windows Shell 的 IShellItemImageFactory（图片/视频/Office/PDF 都行）。

    ⚠ 这条路径在部分机器上**完全不可用**：实测某台 Win11 上
    `SHCreateItemFromParsingName` 对任何文件都返回 `0x80004002`
    （E_NOINTERFACE），于是恒为 None。所以调用方必须准备好兜底 ——
    见 `shell_thumbnail_png`。
    """
    if os.name != "nt":
        return None
    try:
        import ctypes
        from ctypes import wintypes as _wt
        ole = ctypes.windll.ole32
        shell = ctypes.windll.shell32
        try:
            ole.CoInitializeEx(None, 0x2)     # APARTMENTTHREADED
        except Exception:
            pass

        class GUID(ctypes.Structure):
            _fields_ = [("d1", _wt.DWORD), ("d2", _wt.WORD), ("d3", _wt.WORD),
                        ("d4", ctypes.c_ubyte * 8)]

        iid = GUID(0xBCC18B79, 0xBA16, 0x442C,
                   (ctypes.c_ubyte * 8)(0x80, 0xC4, 0x8A, 0x59, 0xC3, 0x0C,
                                        0x46, 0xFB))
        shell.SHCreateItemFromParsingName.argtypes = [
            _wt.LPCWSTR, ctypes.c_void_p, ctypes.POINTER(GUID),
            ctypes.POINTER(ctypes.c_void_p)]
        shell.SHCreateItemFromParsingName.restype = ctypes.c_long
        item = ctypes.c_void_p()
        hr = shell.SHCreateItemFromParsingName(
            ctypes.c_wchar_p(os.path.abspath(path)), None,
            ctypes.byref(iid), ctypes.byref(item))
        if hr != 0 or not item:
            return None
        try:
            vt = ctypes.cast(
                item, ctypes.POINTER(ctypes.POINTER(ctypes.c_void_p))).contents
            # vtable: 0..2 IUnknown, 3 = GetImage
            idx = 3
            fn = ctypes.WINFUNCTYPE(ctypes.c_long, ctypes.c_void_p,
                                    ctypes.c_int, ctypes.c_int, ctypes.c_int,
                                    ctypes.POINTER(ctypes.c_void_p))(vt[idx])
            SIZE = 0x1                          # SIIGBF_RESIZETOFIT
            hbm = ctypes.c_void_p()
            hr = fn(item, w, h, SIZE, ctypes.byref(hbm))
            if hr != 0 or not hbm:
                return None
            try:
                px = _hbitmap_to_pixels(hbm, w, h)
            finally:
                ctypes.windll.gdi32.DeleteObject(hbm)
            if not px:
                return None
            return _png(w, h, _bgra_rows(px, w, h))
        finally:
            try:
                rel = ctypes.cast(
                    item, ctypes.POINTER(ctypes.POINTER(ctypes.c_void_p))).contents
                ctypes.WINFUNCTYPE(ctypes.c_ulong, ctypes.c_void_p)(rel[2])(item)
            except Exception:
                pass
    except Exception:
        return None


# ==========================================================================
# 自签证书（纯 Python 实现：最小 DER 编码 + ECDSA P-256 + X.509）
#
# 为什么要自己写：TLS 必须要有证书，而 Python 标准库不提供证书生成，
# 依赖 cryptography / openssl 又违背"零依赖、双击即用"的前提。
# 这里用 ~200 行把需要的那一小块 ASN.1 和 P-256 椭圆曲线实现出来，
# 首次运行生成一对全新的密钥和证书（每台机器各不相同），缓存后复用。
# ==========================================================================

_P256_P = 0xFFFFFFFF00000001000000000000000000000000FFFFFFFFFFFFFFFFFFFFFFFF
_P256_A = _P256_P - 3
_P256_B = 0x5AC635D8AA3A93E7B3EBBD55769886BC651D06B0CC53B0F63BCE3C3E27D2604B
_P256_N = 0xFFFFFFFF00000000FFFFFFFFFFFFFFFFBCE6FAADA7179E84F3B9CAC2FC632551
_P256_GX = 0x6B17D1F2E12C4247F8BCE6E563A440F277037D812DEB33A0F4A13945D898C296
_P256_GY = 0x4FE342E2FE1A7F9B8EE7EB4A7C0F9E162BCE33576B315ECECBB6406837BF51F5


def _der_len(n):
    if n < 0x80:
        return bytes((n,))
    b = b""
    while n:
        b = bytes((n & 0xFF,)) + b
        n >>= 8
    return bytes((0x80 | len(b),)) + b


def _tlv(tag, payload):
    return bytes((tag,)) + _der_len(len(payload)) + payload


def _der_int(v):
    if v == 0:
        return _tlv(0x02, b"\x00")
    if v < 0:
        raise ValueError("只支持正整数")
    b = v.to_bytes((v.bit_length() + 7) // 8, "big")
    if b[0] & 0x80:
        b = b"\x00" + b
    return _tlv(0x02, b)


def _der_seq(*items):
    return _tlv(0x30, b"".join(items))


def _der_set(*items):
    return _tlv(0x31, b"".join(items))


def _der_octet(b):
    return _tlv(0x04, b)


def _der_bitstr(b, unused=0):
    return _tlv(0x03, bytes((unused,)) + b)


def _der_bool(v):
    return _tlv(0x01, b"\xff" if v else b"\x00")


def _der_oid(dotted):
    parts = [int(x) for x in dotted.split(".")]
    out = bytes((40 * parts[0] + parts[1],))
    for p in parts[2:]:
        chunk = [p & 0x7F]
        p >>= 7
        while p:
            chunk.append((p & 0x7F) | 0x80)
            p >>= 7
        out += bytes(reversed(chunk))
    return _tlv(0x06, out)


def _der_utf8(s):
    return _tlv(0x0C, s.encode("utf-8"))


def _der_utctime(dt):
    """RFC 5280 要求 2049 年（含）之前用 UTCTime 编码，这里两端都在范围内。"""
    return _tlv(0x17, dt.strftime("%y%m%d%H%M%SZ").encode("ascii"))


def _ctx(n, payload):
    return _tlv(0xA0 | n, payload)


def _modinv(x, m):
    return pow(x % m, m - 2, m)


class _Curve(object):
    """P-256（secp256r1）上的点运算。用仿射坐标 + 费马小定理求逆，够快也够短。"""

    def __init__(self):
        self.p, self.a, self.b = _P256_P, _P256_A, _P256_B
        self.g = (_P256_GX, _P256_GY)

    def add(self, P, Q):
        if P is None:
            return Q
        if Q is None:
            return P
        x1, y1 = P
        x2, y2 = Q
        if x1 == x2:
            if (y1 + y2) % self.p == 0:
                return None                      # 互为逆元 → 无穷远点
            lam = (3 * x1 * x1 + self.a) * _modinv(2 * y1, self.p) % self.p
        else:
            lam = (y2 - y1) * _modinv(x2 - x1, self.p) % self.p
        x3 = (lam * lam - x1 - x2) % self.p
        y3 = (lam * (x1 - x3) - y1) % self.p
        return (x3, y3)

    def mul(self, k, P):
        R = None
        while k:
            if k & 1:
                R = self.add(R, P)
            P = self.add(P, P)
            k >>= 1
        return R


_CURVE = _Curve()


def _ecdsa_sign(d, msg):
    """ECDSA-with-SHA256 签名，返回 (r, s)。"""
    z = int.from_bytes(hashlib.sha256(msg).digest(), "big")
    while True:
        k = secrets.randbelow(_P256_N - 1) + 1
        pt = _CURVE.mul(k, _CURVE.g)
        r = pt[0] % _P256_N
        if r == 0:
            continue
        s = _modinv(k, _P256_N) * (z + r * d) % _P256_N
        if s == 0:
            continue
        return r, s


def _ec_point_bytes(pub):
    return b"\x04" + pub[0].to_bytes(32, "big") + pub[1].to_bytes(32, "big")


def _algid_ec():
    return _der_seq(_der_oid("1.2.840.10045.2.1"), _der_oid("1.2.840.10045.3.1.7"))


def _sigalg_ec():
    return _der_seq(_der_oid("1.2.840.10045.4.3.2"))      # ecdsa-with-SHA256


def _x509_name(cn):
    return _der_seq(_der_set(_der_seq(_der_oid("2.5.4.3"), _der_utf8(cn))))


def _x509_spki(pub):
    return _der_seq(_algid_ec(), _der_bitstr(_ec_point_bytes(pub)))


def _x509_extensions(dns_names, ips):
    exts = []
    # keyUsage (2.5.29.15): digitalSignature + keyEncipherment + keyCertSign
    exts.append(_der_seq(_der_oid("2.5.29.15"), _der_bool(True),
                         _der_octet(_der_bitstr(b"\xA4", 2))))
    # subjectAltName (2.5.29.17)
    san = []
    for n in dns_names:
        san.append(_tlv(0x82, n.encode("ascii", "replace")))
    for ip in ips:
        san.append(_tlv(0x87, socket.inet_aton(ip)))
    if san:
        exts.append(_der_seq(_der_oid("2.5.29.17"), _der_octet(_der_seq(*san))))
    # basicConstraints (2.5.29.19): CA=TRUE
    exts.append(_der_seq(_der_oid("2.5.29.19"), _der_bool(True),
                         _der_octet(_der_seq(_der_bool(True)))))
    # extKeyUsage (2.5.29.37): serverAuth
    exts.append(_der_seq(_der_oid("2.5.29.37"),
                         _der_octet(_der_seq(_der_oid("1.3.6.1.5.5.7.3.1")))))
    return _der_seq(*exts)


def make_self_signed(cn, dns_names=None, ips=None):
    """生成自签证书，返回 (cert_pem, key_pem)。"""
    dns_names = dns_names or ["localhost"]
    ips = ips if ips else ["127.0.0.1"]
    d = secrets.randbelow(_P256_N - 1) + 1
    pub = _CURVE.mul(d, _CURVE.g)

    now = datetime.datetime.now(datetime.timezone.utc).replace(tzinfo=None)
    not_before = now - datetime.timedelta(days=1)
    # UTCTime 只到 2049，这里取一个足够长的固定上限，避免跨年份格式切换
    not_after = datetime.datetime(2049, 12, 31, 23, 59, 59)
    serial = secrets.randbits(63) | 1

    tbs = _der_seq(
        _ctx(0, _der_int(2)),                       # version v3
        _der_int(serial),
        _sigalg_ec(),                               # signature
        _x509_name(cn),                             # issuer
        _der_seq(_der_utctime(not_before), _der_utctime(not_after)),   # validity
        _x509_name(cn),                             # subject
        _x509_spki(pub),
        _ctx(3, _x509_extensions(dns_names, ips)),
    )
    r, s = _ecdsa_sign(d, tbs)
    cert = _der_seq(tbs, _sigalg_ec(), _der_bitstr(_der_seq(_der_int(r), _der_int(s))))

    ec_priv = _der_seq(
        _der_int(1),
        _der_octet(d.to_bytes(32, "big")),
        _ctx(0, _der_oid("1.2.840.10045.3.1.7")),
        _ctx(1, _der_bitstr(_ec_point_bytes(pub))),
    )
    key = _der_seq(_der_int(0), _algid_ec(), _der_octet(ec_priv))
    return _pem("CERTIFICATE", cert), _pem("PRIVATE KEY", key)


def _pem(label, der):
    body = base64.encodebytes(der).decode("ascii")
    return "-----BEGIN %s-----\n%s-----END %s-----\n" % (label, body, label)


def ensure_cert(cert_path, key_path, cn=None, force=False):
    """没有证书就生成一份（每台机器 / 每次重装各不相同），返回 (cert, key)。

    生成后立刻用 ssl 加载一次做自检——如果证书有问题，这里就会暴露，
    而不是等到客户端连不上才发现。
    """
    if not force and os.path.isfile(cert_path) and os.path.isfile(key_path):
        return cert_path, key_path
    cn = cn or ("LanPass@%s" % hostname())
    dns = ["localhost", "localhost.localdomain"]
    ips = ["127.0.0.1"]
    for ip in local_ips():
        if ip not in ips:
            ips.append(ip)
    cert_pem, key_pem = make_self_signed(cn, dns, ips)
    d = os.path.dirname(cert_path)
    if d:
        os.makedirs(d, exist_ok=True)
    with open(cert_path, "w", encoding="ascii") as f:
        f.write(cert_pem)
    with open(key_path, "w", encoding="ascii") as f:
        f.write(key_pem)
    try:
        os.chmod(key_path, 0o600)
    except OSError:
        pass
    ctx = ssl.SSLContext(ssl.PROTOCOL_TLS_SERVER)
    ctx.load_cert_chain(cert_path, key_path)         # 自检：加载不了会抛异常
    return cert_path, key_path


def make_client_ssl_context():
    """客户端上下文：自签证书无法被公共 CA 校验，因此不校验证书链与主机名。

    安全性由 6 位访问令牌 + 仅限局域网可达来保证；本工具的目标是
    "不让数据在局域网里明文裸奔"，而不是防御中间人。
    """
    ctx = ssl.SSLContext(ssl.PROTOCOL_TLS_CLIENT)
    ctx.check_hostname = False
    ctx.verify_mode = ssl.CERT_NONE
    try:
        ctx.set_ciphers("DEFAULT@SECLEVEL=1")        # 兼容极老的 OpenSSL
    except Exception:
        pass
    return ctx


# ==========================================================================
# mDNS 自动发现（224.0.0.251:5353）
#
# 发送端把自己的服务信息以 mDNS 记录发布出去，接收端点「扫描」时发一条
# PTR 查询，就能拿到对方的主机名 / IP / 端口，不用再手抄 IP。
# 查询里带上 QU（unicast-response）位，让对方把答复单播回我们的临时端口，
# 这样接收端不必加入组播组也能收到答复，Windows 上稳定得多。
# 另外同一个查询还会往 255.255.255.255 广播一份：有些交换机会拦组播，
# 但广播一般能过——成本只有一行代码，却能救回不少"扫描不到"的情况。
# ==========================================================================

_DNS_A, _DNS_PTR, _DNS_TXT, _DNS_SRV, _DNS_ANY = 1, 12, 16, 33, 255
_DNS_IN = 1


def _dns_encode_name(name):
    out = b""
    for lab in name.rstrip(".").split("."):
        if not lab:
            continue
        b = lab.encode("utf-8")[:63]
        out += bytes((len(b),)) + b
    return out + b"\x00"


def _dns_decode_name(data, off, depth=0):
    """解析域名，支持压缩指针。返回 (name, 下一个偏移)。"""
    labels = []
    nxt = off
    jumped = False
    while depth < 24:
        if off >= len(data):
            break
        l = data[off]
        if l == 0:
            off += 1
            if not jumped:
                nxt = off
            break
        if (l & 0xC0) == 0xC0:
            if off + 1 >= len(data):
                break
            ptr = ((l & 0x3F) << 8) | data[off + 1]
            if not jumped:
                nxt = off + 2
            off = ptr
            jumped = True
            depth += 1
            continue
        off += 1
        labels.append(data[off:off + l].decode("utf-8", "replace"))
        off += l
        if not jumped:
            nxt = off
    return ".".join(x for x in labels if x), nxt


def _dns_rr(name, rtype, rdata, ttl=120):
    return (_dns_encode_name(name)
            + struct.pack(">HHIH", rtype, _DNS_IN, ttl, len(rdata)) + rdata)


def _norm_name(s):
    """统一成小写、不带结尾点的形式再比较。

    坑：DNS 域名编码时结尾的根标签是个 0 字节，解码回来自然就没有结尾的
    "."。直接拿 "_lanshare._tcp.local." 去比会永远不相等，服务名匹配全落空。
    """
    return (s or "").strip().rstrip(".").lower()


_SERVICE_KEY = _norm_name(MDNS_SERVICE)


def _dns_query(name, rtype, unicast=True):
    """构造一次查询。unicast=True 时置 QU 位（对方单播回应）。"""
    q = _dns_encode_name(name) + struct.pack(">HH", rtype, _DNS_IN | (0x8000 if unicast else 0))
    return struct.pack(">HHHHHH", 0, 0, 1, 0, 0, 0) + q


def _parse_dns_records(data, log=None):
    """返回 [(name, type, rdata_bytes)]，尽量不抛异常。"""
    out = []
    if len(data) < 12:
        return out
    _id, _flags, qd, an, ns, ar = struct.unpack(">HHHHHH", data[:12])
    off = 12
    for _ in range(qd):                       # 跳过问题段
        _n, off = _dns_decode_name(data, off)
        off += 4
    for _ in range(an + ns + ar):
        if off + 10 > len(data):
            break
        name, off = _dns_decode_name(data, off)
        if off + 10 > len(data):
            break
        rtype, _rclass, _ttl, rdlen = struct.unpack(">HHIH", data[off:off + 10])
        off += 10
        rdata = data[off:off + rdlen]
        off += rdlen
        out.append((name, rtype, rdata))
    return out


def _txt_from_rdata(rdata):
    d = {}
    i = 0
    while i < len(rdata):
        n = rdata[i]
        i += 1
        s = rdata[i:i + n].decode("utf-8", "replace")
        i += n
        if "=" in s:
            k, _, v = s.partition("=")
            d[k] = v
        elif s:
            d[s] = ""
    return d


def service_instance(port=None):
    """发送端对外显示的服务实例名，例如 HaoStation-8790。"""
    return "%s-%d" % (hostname(), port or DEFAULT_PORT)


class MdnsResponder(object):
    """发送端侧：把自己发布成 _lanshare._tcp.local. 服务，并回答查询。"""

    def __init__(self, port, proto="https", version=VERSION, log=None,
                 ext=""):
        self.port = int(port)
        self.proto = proto
        self.version = version
        self.ext = ext          # v3.7: 跨网段可达地址 "ip:port"（UPnP 映射）
        self.log = log or (lambda m: None)
        self.inst = service_instance(port)
        self.instance_fqdn = "%s.%s" % (self.inst, MDNS_SERVICE)
        self.host_fqdn = "%s.local." % hostname()
        self.ips = []
        self.sock = None
        self.stop_event = threading.Event()
        self.thread = None
        self._announced = 0
        self.error = ""

    # ---- 记录 ----
    def _ptr_rr(self):
        return _dns_rr(MDNS_SERVICE, _DNS_PTR,
                       _dns_encode_name(self.instance_fqdn))

    def _srv_rr(self):
        rdata = struct.pack(">HHH", 0, 0, self.port) + _dns_encode_name(self.host_fqdn)
        return _dns_rr(self.instance_fqdn, _DNS_SRV, rdata)

    def _txt_rr(self):
        fields = [b"v=" + self.version.encode(),
                  b"host=" + hostname().encode("utf-8", "replace"),
                  b"proto=" + self.proto.encode(),
                  b"os=" + platform.system().encode()]
        if self.ext:
            fields.append(b"ext=" + self.ext.encode("utf-8", "replace"))
        rdata = b""
        for f in fields:
            f = f[:255]
            rdata += bytes((len(f),)) + f
        return _dns_rr(self.instance_fqdn, _DNS_TXT, rdata)

    def _a_rrs(self):
        out = []
        for ip in (self.ips or local_ips()[:1]):
            try:
                out.append(_dns_rr(self.host_fqdn, _DNS_A, socket.inet_aton(ip)))
            except OSError:
                continue
        return out

    def _announce_packet(self, answers):
        body = b"".join(answers)
        head = struct.pack(">HHHHHH", 0, 0x8400, 0, len(answers), 0, 0)
        return head + body

    # ---- 收发 ----
    def start(self):
        if self.sock is not None:
            return True
        try:
            s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
            s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
            try:
                s.bind(("", MDNS_PORT))
            except OSError as e:
                self.error = "mDNS 端口 %d 被占用: %s" % (MDNS_PORT, e)
                s.close()
                return False
            self.ips = local_ips() or []
            joined = 0
            for ip in (["0.0.0.0"] + self.ips):
                try:
                    s.setsockopt(socket.IPPROTO_IP, socket.IP_ADD_MEMBERSHIP,
                                 socket.inet_aton(MDNS_GROUP) + socket.inet_aton(ip))
                    joined += 1
                except OSError:
                    continue
            try:
                s.setsockopt(socket.IPPROTO_IP, socket.IP_MULTICAST_TTL, 255)
                s.setsockopt(socket.IPPROTO_IP, socket.IP_MULTICAST_LOOP, 1)
            except OSError:
                pass
            s.settimeout(0.5)
            self.sock = s
            if not joined:
                self.error = "加入组播组失败（仍会用广播应答）"
            self.thread = threading.Thread(target=self._loop, daemon=True)
            self.thread.start()
            self.announce()
            self.log("mDNS 已发布: %s  端口 %d（%s）" % (self.inst, self.port, self.proto))
            return True
        except Exception as e:
            self.error = "%r" % (e,)
            return False

    def announce(self):
        """主动通告一次，让已经在等的接收端立刻看到我们。"""
        if self.sock is None:
            return
        ans = [self._ptr_rr(), self._srv_rr(), self._txt_rr()] + self._a_rrs()
        pkt = self._announce_packet(ans)
        try:
            self.sock.sendto(pkt, (MDNS_GROUP, MDNS_PORT))
        except OSError:
            pass
        self._announced = time.time()

    def _loop(self):
        while not self.stop_event.is_set():
            try:
                data, addr = self.sock.recvfrom(4096)
            except socket.timeout:
                continue
            except OSError:
                break
            try:
                self._handle(data, addr)
            except Exception as e:            # 单个坏包不能让发现服务挂掉
                _safe_err("mDNS 处理失败: %r\n" % (e,))
        try:
            self.sock.close()
        except OSError:
            pass

    def _handle(self, data, addr):
        if len(data) < 12:
            return
        flags = struct.unpack(">H", data[2:4])[0]
        if flags & 0x8000:                    # 是响应，不是查询
            return
        off = 12
        want = False
        while off < len(data):
            name, off2 = _dns_decode_name(data, off)
            if off2 + 4 > len(data):
                break
            qtype, qclass = struct.unpack(">HH", data[off2:off2 + 4])
            unicast = bool(qclass & 0x8000)
            off = off2 + 4
            lname = _norm_name(name)
            if qtype in (_DNS_PTR, _DNS_ANY) and lname == _SERVICE_KEY:
                want = True
            elif qtype in (_DNS_SRV, _DNS_TXT, _DNS_ANY) \
                    and lname == _norm_name(self.instance_fqdn):
                want = True
            if not name:
                break
        if not want:
            return
        ans = [self._ptr_rr(), self._srv_rr(), self._txt_rr()] + self._a_rrs()
        pkt = self._announce_packet(ans)
        # QU 位表示"请单播回我"，那就回给它的源地址；否则照 mDNS 规矩组播。
        target = addr if (unicast and addr and addr[1]) else (MDNS_GROUP, MDNS_PORT)
        try:
            self.sock.sendto(pkt, target)
        except OSError:
            pass

    def stop(self):
        self.stop_event.set()
        if self.thread is not None:
            self.thread.join(timeout=1.5)
            self.thread = None
        if self.sock is not None:
            try:
                self.sock.close()
            except OSError:
                pass
            self.sock = None


def mdns_scan(timeout=2.5, log=None):
    """接收端侧：扫描同网段的发送端，返回列表。

    每项: {name, host, ip, port, proto, version, os}
    """
    log = log or (lambda m: None)
    found = {}
    s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    try:
        s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        try:
            s.setsockopt(socket.SOL_SOCKET, socket.SO_BROADCAST, 1)
        except OSError:
            pass
        s.bind(("", 0))
    except OSError as e:
        s.close()
        raise RuntimeError("无法建立发现套接字: %s" % e)

    pkt = _dns_query(MDNS_SERVICE, _DNS_PTR, unicast=True)
    targets = [(MDNS_GROUP, MDNS_PORT)]
    try:
        targets.append(("255.255.255.255", MDNS_PORT))
    except Exception:
        pass

    end = time.time() + max(0.4, timeout)
    sent = 0
    s.settimeout(0.25)
    while time.time() < end:
        if sent < 2:
            for t in targets:
                try:
                    s.sendto(pkt, t)
                except OSError:
                    pass
            sent += 1
        try:
            data, addr = s.recvfrom(8192)
        except socket.timeout:
            continue
        except OSError:
            break
        try:
            _collect(data, addr[0], found)
        except Exception as e:
            log("解析发现响应失败: %r" % (e,))
    s.close()

    out = []
    for inst, rec in found.items():
        if not rec.get("port") or not rec.get("ip"):
            continue                              # 信息不全的条目宁可不要
        out.append({
            "name": rec.get("name") or inst.split(".")[0],
            "host": rec.get("host") or (rec.get("fqdn") or "").split(".")[0] or inst.split(".")[0],
            "ip": rec["ip"],
            "port": rec["port"],
            "proto": rec.get("proto", "https"),
            "version": rec.get("version", ""),
            "os": rec.get("os", ""),
            "ext": rec.get("ext", ""),
        })
    out.sort(key=lambda r: r["name"].lower())
    return out


def _collect(data, src_ip, found):
    for name, rtype, rdata in _parse_dns_records(data):
        lname = _norm_name(name)
        is_service = lname.endswith(_SERVICE_KEY)
        is_local_a = lname.endswith(".local") or lname.endswith(".local.arpa")
        if not (is_service or (rtype == _DNS_A and is_local_a)):
            continue
        if rtype == _DNS_PTR:
            inst, _ = _dns_decode_name(rdata, 0)
            if not inst:
                continue
            rec = found.setdefault(inst, {})
            rec.setdefault("name", inst.split(".")[0])
            rec.setdefault("ip", src_ip)
        elif rtype == _DNS_SRV:
            if len(rdata) >= 6:
                port = struct.unpack(">H", rdata[4:6])[0]
                target, _ = _dns_decode_name(rdata, 6)
                rec = found.setdefault(name, {})
                rec["port"] = port
                rec["fqdn"] = _norm_name(target)
                rec.setdefault("name", name.split(".")[0])
                rec.setdefault("ip", src_ip)
        elif rtype == _DNS_TXT:
            rec = found.setdefault(name, {})
            t = _txt_from_rdata(rdata)
            rec["proto"] = t.get("proto", rec.get("proto", "https"))
            rec["version"] = t.get("v", "")
            rec["os"] = t.get("os", "")
            rec["ext"] = t.get("ext", rec.get("ext", ""))
            if t.get("host"):
                rec["host"] = t["host"]
        elif rtype == _DNS_A and len(rdata) == 4:
            ip = socket.inet_ntoa(rdata)
            for rec in found.values():          # 把 A 记录贴回对应的服务
                if rec.get("fqdn") == lname:
                    rec["ip"] = ip
    return found


# ==========================================================================
# 全局 HTTP 客户端：局域网直连工具**绝不能走系统代理**。
# 机器上若设置了 http_proxy / 系统代理 / 代理软件的 TUN 模式，
# 默认的 urlopen 会把局域网请求转给代理 —— 代理不认识内网地址就 502，
# 严重的甚至把文件流量送出公网。所以这里建一个"永远直连"的 opener。
# ==========================================================================
DIRECT_OPENER = urllib.request.build_opener(urllib.request.ProxyHandler({}))

# ==========================================================================
# 在线更新检查（v3.9.2）
# --------------------------------------------------------------------------
# 目标：用户上传新 Release 后，程序能**主动告知有新版本**，而不是让人自己
# 去比对版本号。只做"检查 + 通知"，**下载一律交给浏览器**（点按钮打开网页）。
# 为什么不做自动下载替换：
#   ① 正在运行的 exe 被 Windows 锁着，要替换必须先退出程序再重启，
#      一次更新要用户点三次确认，体验反而更差；
#   ② 绿色免安装软件，exe 可能放在 U 盘 / 网盘 / 只读目录里，
#      原地覆盖会失败；
#   ③ 自动下载 exe 最容易被杀毒软件直接拦下，用户的信任成本最高。
# 交给浏览器还有个附带好处：浏览器里能顺手看校验值、看更新说明。
#
# ⚠⚠ 安全红线（踩过就别改）：**绝不能复用 make_client_ssl_context()**。
# 那个是给局域网自签证书用的，verify_mode=CERT_NONE + check_hostname=False，
# 拿来访问公网等于完全不验签、可被中间人替换。这里另起一个走系统默认
# 校验的 opener —— HTTPS 证书链该验就验，这和"局域网内不验证自签证书"
# 是两件不同的事。
#
# ⚠ 也不能复用 DIRECT_OPENER：它是为了让**局域网**请求绕过系统代理而存在的；
# 而更新检查恰恰相反 —— 很多公司网络/国内家庭宽带要靠系统代理才能出网，
# 强行直连反而会被墙掉或超时。两个 opener 用途相反，各管各的。
# ==========================================================================

UPDATE_URL = ("https://api.github.com/repos/%s/%s/releases/latest"
              % (GITHUB_OWNER, GITHUB_REPO))
UPDATE_TIMEOUT = 8          # 秒。超时短一点，宁可这次查不到下次再说
UPDATE_DELAY = 12# 秒。启动后等这么久，避开开机抢网 / 磁盘忙的那阵
UPDATE_COOLDOWN = 86400     # 24 小时内不重复提示同一个版本

# 走系统默认证书校验（不装 ProxyHandler / 不装自定义 SSLHandler）
_UPDATE_OPENER = urllib.request.build_opener()


def _ver_tuple(s):
    """'3.9.1' / 'v3.9.1' -> (3, 9, 1)。不是数字的段一律当 0。

    为什么不用 distutils.LooseVersion：那个在 3.12 已从标准库移除，
    本项目要跑 3.8~3.13，不能依赖它。版本号格式是固定的 主.次.修订
    （见 VERSION 处的递增规则），所以手写这个足够。
    """
    s = str(s or "").strip().lstrip("vV")
    out = []
    for seg in s.split("."):
        d = ""
        for ch in seg:
            if ch.isdigit():
                d += ch
            else:
                break
        out.append(int(d) if d else 0)
    while len(out) < 3:
        out.append(0)
    return tuple(out[:3])


def _update_notes(d, limit=420):
    """把 Release 的 Markdown 更新说明压成适合弹窗的一段纯文本。

    Release 说明是给网页看的，带 # 标题、- 列表、| 表格、代码块。直接塞进
    messagebox 会一屏乱码还撑爆窗口。这里只留正文行、去掉标记、压空白。

    ⚠ 约定：发布 Release 时把「本次改了什么」写在**第一个 H1 之后**，
    用 `## 本版要点` 小节标起来。弹窗**只取这个小节**，否则用户看到的是
    「核心能力 / 适合什么场景 / 系统要求」这类万年不变的说明，
    完全看不出这次更新了什么 —— 那是噪音，不是通知。
    """
    lines = (d or "").splitlines()

    # 第一段：找「本版要点」小节的起止行号。
    # ⚠ 要点正文在小节标题**下面**（start 是标题行的下一行），
    # 取"标题之前"等于全丢掉 —— 这个方向搞反过一次。
    BEGIN = ("本版要点", "本次要点", "本版更新", "更新内容", "本次更新",
             "更新说明", "本版改进", "改了什么")
    start = end = -1
    for i, raw in enumerate(lines):
        s = raw.strip()
        if not s.startswith("#"):
            continue
        title = s.lstrip("#").strip()
        if start < 0:
            if any(title.startswith(k) for k in BEGIN):
                start = i + 1
        else:
            end = i          # 撞上下一个标题就收工
            break
    if start > 0:
        body = lines[start:end if end > start else len(lines)]
    else:
        body = lines         # 没有要点小节 → 退回取整个正文的前若干行

    out = []
    in_code = False
    for raw in body:
        line = raw.strip()
        # 代码块要**成对**判断：只判起始 ``` 的话，块里的内容会漏进弹窗
        if line.startswith("```"):
            in_code = not in_code
            continue
        if in_code or not line:
            continue
        if line.startswith(("#", ">", "|", "---", "===")):
            continue
        line = line.lstrip("-*+ ").strip()
        # 行内标记统一去掉：加粗、反引号、链接只留文字
        line = line.replace("**", "").replace("__", "").replace("`", "")
        if "](" in line:
            line = line.split("](")[0] + line.rsplit(")", 1)[-1]
        line = line.replace("*", "").strip()
        if not line or line.startswith("---"):
            continue
        out.append("· " + line)
        if sum(len(x) for x in out) > limit:
            break
    return "\n".join(out)


def fetch_latest_release(manual=False):
    """问 GitHub 要最新的正式版。

    返回 dict：``{"ver": "3.9.1", "url": ..., "notes": "..."}``；
    没有更新或任何环节失败都返回 ``None``。

    ⚠ **失败一律静默返回 None**（manual=True 时由调用方决定要不要给提示）。
    原因：本工具的主功能是局域网传文件，绝大多数用户是内网环境、
    GitHub 可能根本不可达，绝不能因为查不到版本就弹窗打扰甚至影响启动。
    """
    req = urllib.request.Request(
        UPDATE_URL,
        headers={
            # GitHub API 对没有 User-Agent 的请求会直接 403
            "User-Agent": "%s/%s" % (APP_NAME, VERSION),
            "Accept": "application/vnd.github+json",
        })
    try:
        with _UPDATE_OPENER.open(req, timeout=UPDATE_TIMEOUT) as r:
            d = json.loads(r.read().decode("utf-8", "replace"))
    except Exception:
        # 网络不通 / 被墙 / 证书不认 / 限流 / 返回格式变了 —— 一律不当回事
        return None

    # 草稿和预发布不算更新
    if d.get("draft") or d.get("prerelease"):
        return None
    tag = str(d.get("tag_name") or "").strip()
    if not tag:
        return None
    newest = tag.lstrip("vV")
    if _ver_tuple(newest) <= _ver_tuple(VERSION):
        return None

    return {
        "ver": newest,
        "url": d.get("html_url") or "",
        "notes": _update_notes(d.get("body")),
        "size": next((a.get("size") for a in (d.get("assets") or [])
                      if str(a.get("name", "")).lower().endswith(".exe")), 0),
    }


def _update_state(manual=False):
    """统一的状态判断与状态落盘。返回要弹窗的内容（不需要弹时返回 None）。

    记在配置里的三个键：
      update_last_check   上次**成功**查到的时间戳（毫秒）
      update_seen_ver     用户点过"以后再说"的那个版本号
    存"上次成功"而不是"上次尝试"：查不到就别拖到 24 小时后再查，
    否则断网三天的人每次启动都要等那一次超时。
    """
    conf = load_conf()
    now = int(time.time())
    if not manual:
        last = conf.get("update_last_check", 0)
        # 同一天不重复问；manual 传入时永远放行
        if last and (now - last) < UPDATE_COOLDOWN:
            return None

    info = fetch_latest_release(manual=manual)
    if info is None:
        if manual:
            return {"state": "unknown"}
        # 静默失败：**不写** update_last_check，让下次启动还能重试
        return None

    if info["ver"] == conf.get("update_seen_ver"):
        return None            # 这个版本用户已经知道了

    conf["update_last_check"] = now
    save_conf(conf)
    return {"state": "new", "info": info}


def mark_update_seen(ver):
    """用户点"以后再说"：记下版本号，同一个版本不再烦他。"""
    conf = load_conf()
    conf["update_seen_ver"] = ver
    conf["update_last_check"] = int(time.time())
    save_conf(conf)


def _update_page_url():
    """项目主页（打不开时的兜底：用户可以自己去那儿看版本）。"""
    return "https://github.com/%s/%s/releases" % (GITHUB_OWNER, GITHUB_REPO)


def update_check_async(win, delay=UPDATE_DELAY):
    """启动后延迟一会儿在后台静默查一次更新，查到就通知。

    ⚠ **必须后台线程**：这是启动路径上的调用，主线程正忙着建界面，
    同步查会卡住窗口 8 秒。
    ⚠ 回调一律经窗口自己的跨线程入口回主线程 —— 后台线程碰 Tk 会挂死。
    ⚠⚠ 两个主窗口的入口名字不一样：发送端是 `ui_q`（+ `_drain` 消费），
    接收端是 `post()`。这里两种都认，别写死。
    """
    def _work():
        res = _update_state(manual=False)
        if not res or res.get("state") != "new":
            return                                  # 无更新 / 失败 → 全静默
        info = res["info"]

        def _ui():
            try:
                if getattr(win, "_closing", False):
                    return
                _UpdateDialog(win, info).show()
            except Exception:
                pass
        try:
            post = getattr(win, "post", None)
            if callable(post):
                post(_ui)                          # 接收端
            else:                                   # 发送端：老式队列
                win.ui_q.put(_ui)
        except Exception:
            pass

    def _go():
        try:
            threading.Thread(target=_work, daemon=True).start()
        except Exception:
            pass
    try:
        win.root.after(int(delay * 1000), _go)
    except Exception:
        pass


class _UpdateDialog(object):
    """「发现新版本」的模态提示窗。

    为什么自己搭窗而不用 messagebox：想在「已是最新」时**不打扰**，
    而 messagebox 只有一种形态。自搭窗能把「以后再说」做成默认动作，
    并且【关于】页开着时把提示挂到它上面。
    """

    def __init__(self, owner, info):
        self.owner = owner
        self.info = info
        self.top = None

    def show(self):
        if tk is None:
            return
        ver = self.info.get("ver", "")
        # ⚠ 父窗句柄：主窗口叫 .root，【关于】窗口叫 .top，两个都得认。
        #   只认 .root 的话，从【关于】页触发时 parent=None，弹窗就成了
        #   没有 transient 关系的独立窗口，容易掉到主窗口后面去。
        parent = None
        try:
            parent = self.owner.root
        except Exception:
            try:
                parent = self.owner.top
            except Exception:
                parent = None
        t = tk.Toplevel(parent)
        self.top = t
        t.title("发现新版本")
        try:
            t.transient(parent)
            t.resizable(False, False)
        except Exception:
            pass

        box = tk.Frame(t, bg=C_CARD)
        box.pack(fill=tk.BOTH, expand=True, padx=px(18), pady=px(16))

        tk.Label(box, text="发现新版本  %s" % ver,
                 bg=C_CARD, fg=C_TXT, anchor="w",
                 font=("Microsoft YaHei UI", 12, "bold")).pack(
                     fill=tk.X, pady=(0, px(2)))
        tk.Label(box, text="当前版本 %s　·　%s" % (APP_VER, self._size_txt()),
                 bg=C_CARD, fg=C_TXT3, anchor="w",
                 font=FONT_S).pack(fill=tk.X, pady=(0, px(8)))

        notes = self.info.get("notes") or ""
        if notes:
            # 限制行数：说明再长也不该把窗撑到屏幕外
            body = "\n".join(notes.splitlines()[:10])
            # anchor/justify 用字符串字面量（无头自检的 Tk 是桩，
            # tkinter 模块上没有 tk.NW 这个常量，写 tk.NW 会让 selftest 崩）
            tk.Label(box, text=body, bg=C_CARD, fg=C_TXT2, anchor="nw",
                     justify="left", font=FONT_S).pack(fill=tk.BOTH, expand=True)

        btns = tk.Frame(box, bg=C_CARD)
        btns.pack(fill=tk.X, pady=(px(12), 0))
        ttk.Button(btns, text="以后再说", style="About.TButton",
                   command=self._later).pack(side=tk.LEFT)
        ttk.Button(btns, text="去下载", style="Accent.TButton",
                   command=self._go).pack(side=tk.RIGHT)

        t.bind("<Escape>", lambda e: self._later())
        try:
            t.protocol("WM_DELETE_WINDOW", self._later)
            t.grab_set()
        except Exception:
            pass
        try:
            t.bell()
        except Exception:
            pass

    def _size_txt(self):
        n = self.info.get("size") or 0
        return ("安装包 %.1f MB" % (n / 1048576.0)) if n else ""

    def _later(self):
        try:
            mark_update_seen(self.info.get("ver", ""))
        except Exception:
            pass
        try:
            if self.top is not None:
                self.top.destroy()
        except Exception:
            pass

    def _go(self):
        self._later()
        url = self.info.get("url") or _update_page_url()
        try:
            os.startfile(url)
        except Exception:
            try:
                import webbrowser
                webbrowser.open(url)
            except Exception as e:  # noqa
                _safe_err("打开浏览器失败: %r\n" % (e,))


# ==========================================================================
# UPnP 端口映射（v3.7 隔 NAT 优化 A）
# --------------------------------------------------------------------------
# 场景：发送端挂在二级路由下面（如光猫 -> 路由A -> 路由B -> 发送端），
# 接收端与发送端不同网段时直连超时。
# 思路：发送端启动服务后，用 UPnP 在【自己前面的那台路由器】上自动登记
# 一条端口映射（外部端口 -> 本机:服务端口），并把"外层可达地址"
# （路由器 WAN 口 IP + 外部端口）写进 mDNS 广播的 ext= 字段。
# 接收端直连失败时改连 ext 地址 —— 出站/映射路径都能通。
# 全程只在局域网内的路由器上登记，不经过互联网。
# ==========================================================================

UPNP_ST_DEVICES = (
    "urn:schemas-upnp-org:service:WANIPConnection:1",
    "urn:schemas-upnp-org:service:WANIPConnection:2",
    "urn:schemas-upnp-org:service:WANPPPConnection:1",
    "urn:schemas-upnp-org:device:InternetGatewayDevice:1",
    "upnp:rootdevice",
)
UPNP_MCAST_GROUP = "239.255.255.250"
UPNP_MCAST_PORT = 1900


def _upnp_private_ip():
    """拿本机主私网 IPv4（给映射的 NewInternalClient 用）。"""
    for ip in local_ips():
        if ip.startswith(("10.", "192.168.", "172.")):
            return ip
    return (local_ips() or [""])[0]


def _reachable_local_ip(peer):
    """本机发给 peer 时实际会用掉的源 IPv4（对方能"回访"到的地址）。

    UDP connect 只查本机路由表、不发包，所以对不可达地址也立即返回。
    这是反向接入出码的钥匙：接入码里的 IP 必须是"对方连得进来的本机
    地址"，而不是随便一张网卡的 IP —— 多网卡 / VPN 虚拟网卡下两者
    经常不是同一个。

    防 TUN/代理劫持：TUN 模式会把默认路由吸进虚拟网卡，getsockname
    可能返回虚拟地址。结果只有在 local_ips()（真实网卡列表）里才算数，
    否则返回空串，由调用方回退到 _upnp_private_ip()。
    """
    try:
        s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        try:
            s.connect((peer, 9))
            ip = s.getsockname()[0]
        finally:
            s.close()
        if ip and ip in local_ips():
            return ip
    except Exception:
        pass
    return ""


def upnp_discover(timeout=3.0, log=None):
    """SSDP M-SEARCH 找网关，返回 [(device_xml_url,)] 去重列表。"""
    log = log or (lambda m: None)
    msg = []
    for st in UPNP_ST_DEVICES:
        msg.append(
            "M-SEARCH * HTTP/1.1\r\n"
            "HOST: %s:%d\r\n"
            'MAN: "ssdp:discover"\r\n'
            "MX: 1\r\n"
            "ST: %s\r\n\r\n" % (UPNP_MCAST_GROUP, UPNP_MCAST_PORT, st))
    pkt = "".join(msg).encode("utf-8")

    s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    s.settimeout(timeout)
    found = []
    try:
        s.sendto(pkt, (UPNP_MCAST_GROUP, UPNP_MCAST_PORT))
        end = time.time() + timeout
        while time.time() < end:
            try:
                data, _addr = s.recvfrom(4096)
            except socket.timeout:
                break
            head = data.decode("utf-8", "replace")
            first = head.splitlines()[0] if head else ""
            if "200 OK" not in first:
                continue
            for line in head.splitlines():
                if line.lower().startswith("location:"):
                    loc = line.split(":", 1)[1].strip()
                    if loc and loc not in found:
                        found.append(loc)
    except OSError as e:
        log("UPnP 发现出错: %s" % e)
    finally:
        s.close()
    return found


def _upnp_fetch(url, timeout=4):
    try:
        with DIRECT_OPENER.open(url, timeout=timeout) as r:
            return r.read().decode("utf-8", "replace")
    except Exception:
        return ""


def _upnp_find_services(device_xml_url):
    """从设备描述 XML 里抓 WANIP/WANPPP 服务的 (serviceType, controlURL)。"""
    xml = _upnp_fetch(device_xml_url)
    if not xml:
        return []
    base = device_xml_url.rsplit("/", 1)[0] + "/"
    out = []
    # UPnP 设备 XML 足够规整，正则提取 service 块比 ElementTree 皮实
    # （有的路由器 XML 不带命名空间声明，ET 会解析失败）。
    for m in re.finditer(r"<service>(.*?)</service>", xml, re.S):
        blk = m.group(1)

        def _tag(name, _blk=blk):
            mm = re.search(r"<%s>(.*?)</%s>" % (name, name), _blk, re.S)
            return mm.group(1).strip() if mm else ""

        stype = _tag("serviceType")
        ctrl = _tag("controlURL")
        if stype and ctrl and ("WANIPConnection" in stype
                               or "WANPPPConnection" in stype):
            if not ctrl.lower().startswith("http"):
                ctrl = base + ctrl.lstrip("/")
            out.append((stype, ctrl))
    # InternetGatewayDevice 的 XML 里服务分 device 层，上面整体扫过了
    return out


def _upnp_soap(ctrl_url, service_type, action, body_args=""):
    """发一次 SOAP 请求。返回 (status_code, response_text)。"""
    body = (
        '<?xml version="1.0"?>'
        '<s:Envelope xmlns:s="http://schemas.xmlsoap.org/soap/envelope/"'
        ' s:encodingStyle="http://schemas.xmlsoap.org/soap/encoding/">'
        "<s:Body>"
        '<u:%s xmlns:u="%s">%s</u:%s>'
        "</s:Body></s:Envelope>" % (action, service_type, body_args, action))
    req = urllib.request.Request(
        ctrl_url, data=body.encode("utf-8"), method="POST")
    req.add_header("Content-Type", 'text/xml; charset="utf-8"')
    req.add_header("SOAPACTION", '"%s#%s"' % (service_type, action))
    try:
        with DIRECT_OPENER.open(req, timeout=6) as r:
            return r.status, r.read().decode("utf-8", "replace")
    except urllib.error.HTTPError as e:
        try:
            return e.code, e.read().decode("utf-8", "replace")
        except Exception:
            return e.code, ""
    except Exception as e:
        return 0, str(e)


def upnp_add_mapping(internal_ip, internal_port, external_port,
                     description="LanPass", log=None):
    """在网关上登记 TCP 端口映射。成功返回 True。"""
    ok_all = False
    for dev_url in upnp_discover():
        for stype, ctrl in _upnp_find_services(dev_url):
            body = (
                "<NewRemoteHost></NewRemoteHost>"
                "<NewExternalPort>%d</NewExternalPort>"
                "<NewProtocol>TCP</NewProtocol>"
                "<NewInternalPort>%d</NewInternalPort>"
                "<NewInternalClient>%s</NewInternalClient>"
                "<NewLeaseDuration>0</NewLeaseDuration>"
                "<NewPortMappingDescription>%s</NewPortMappingDescription>"
                "<NewEnabled>1</NewEnabled>"
                % (external_port, internal_port, internal_ip, description))
            code, _txt = _upnp_soap(ctrl, stype, "AddPortMapping", body)
            if code == 200:
                ok_all = True
    return ok_all


def upnp_external_ip(log=None):
    """拿网关 WAN 口 IP（外层网段里能被对方连到的地址）。失败返回 ""。"""
    for dev_url in upnp_discover():
        for stype, ctrl in _upnp_find_services(dev_url):
            code, txt = _upnp_soap(ctrl, stype, "GetExternalIPAddress")
            if code == 200:
                m = re.search(r"<NewExternalIPAddress>\s*([0-9.]+)\s*<",
                              txt)
                if m and m.group(1) not in ("0.0.0.0", ""):
                    return m.group(1)
    return ""


def upnp_delete_mapping(internal_port, external_port, log=None):
    """删掉登记的映射（停止服务时清理，失败静默）。"""
    for dev_url in upnp_discover():
        for stype, ctrl in _upnp_find_services(dev_url):
            body = ("<NewRemoteHost></NewRemoteHost>"
                    "<NewExternalPort>%d</NewExternalPort>"
                    "<NewProtocol>TCP</NewProtocol>" % (external_port,))
            _upnp_soap(ctrl, stype, "DeletePortMapping", body)


# ==========================================================================
# 反向接入隧道（v3.7 隔 NAT 优化 B）
# --------------------------------------------------------------------------
# 原理：NAT 只拦"从外面主动发起"的连接，不拦"从里面主动发起"的。
# 两端隔 NAT 且 UPnP 不可用时，让能出去的一方当发起方：
#   等待方（外层机器）开监听端口，显示"接入码" ip:端口#随机码；
#   发起方（内层机器）填码，主动连过去建立隧道。
# 隧道建立后，等待方把本机 HTTP 客户端的请求经隧道送达发起方的本机服务，
# 协议 / 令牌 / TLS 全部原样 —— 等待方视角里就像直接连上了对方的服务端口。
#
# 本软件固定用法（文件在发送端）：
#   接收端连接失败时自动进入等待并把接入码写进日志；
#   发送端把接入码填进「反向接入」框点【接入】；
#   接收端再点一次【连接】 —— 从此走隧道，上传下载与直连完全一致。
# ==========================================================================

# ⚠⚠ 协议常量里的 LANTRANSFER **不要**跟着产品改名一起改成 LANPASS！
#   这是线上协议的字面量，两端必须一致才能互相识别。
#   v3.9.0 产品改名后**故意保留旧字面量** —— 用户手册承诺"新旧两个版本可以
#   互传"，改了它 3.9.0 就再也连不上 3.8.x，承诺就废了。
#   （grep 旧名会命中这里，属预期；判定标准是"改了会不会断连"。）
REV_MAGIC = "LANTRANSFER-REVERSE/1"
# v3.7.8：握手行追加第 3 个字段 —— 发起方**服务端口说的是什么协议**
# （https/http）。为什么必须传：
#   影子端口是"原样转发到对端服务端口"的透明桥，本机 HTTP 客户端必须
#   跟对端说同一种话。而接收端的 remote.scheme 是**上一次直连尝试**留下
#   的残值 —— 直连时 connect() 会 be 为兼容老版本把 https 降级成 http，
#   降级一旦发生，这个 http 就被带进了隧道，于是本机拿明文去撞对端的
#   TLS 端口，对方收到非 TLS 字节立刻断链，本机得到
#   「EOF occurred in violation of protocol (_ssl.c:1131)」——
#   用户现场报的就是这句（v3.7.7 回归）。
#   把协议从握手带过来，就不用猜、也不用"换一种再撞一次"。
# v3.7.7 性能修复：原来的 REV_READY_PRE=2 太小、且没有补货机制 ——
# 每条 HTTP 请求都要换一条 TCP 流，池子一空就得"发 NEED → 对端开 TCP →
# 放队列 → 取到"，等于每个请求白吃 2 个 RTT。用户感受就是"过反向代理特别慢"。
# 现在：预备 8 条 + 后台常驻补货线程把池子维持在 4 条以上，请求基本即到即用。
REV_READY_PRE = 8            # 握手成功后一次性预开的数据流条数
REV_POOL_MIN = 4             # 后台补货线程维持的最小空闲流数
REV_POOL_MAX = 12            # 预开上限，避免空转浪费（对端每条都是一条真 TCP）
REV_QUEUE_MAX = 24           # 等待方侧积压数据流上限（超出即拒收）
# v3.7.11：一条数据流从"连上本机服务"到"真的收到 ClientHello"之间可能要等
# 很久（隧道预开流就是这样：先连好，等接收端把它配对给某个本地连接，第一个
# 字节才到）。所以服务端的 TLS 握手超时要给足 —— 它只是占着**自己的工作
# 线程**，不再卡接受循环（见 ThreadingHTTPServerReuse.get_request）。
# 真正的空闲太久（NAT 掐断等）由等待方配对前的体检兜住（_flow_usable）。
TLS_HANDSHAKE_TIMEOUT = 180

# v3.8.0 路径优化（用户报「经反向代理只有几百 KB/s，直连十几 MB/s」）：
# 先说结论 —— 实测**隧道本身不是瓶颈**（40ms RTT 的受控链路上，
# 直连 45.5 MB/s、经隧道 43.3 MB/s，只慢 5%；本机回环上隧道 362 MB/s）。
# 真正限制吞吐的是**单条 TCP 流**在真实链路上的行为：丢包会让拥塞窗口
# 塌缩、往返时延会限制"在途字节数 = 窗口 / RTT"。所以提速的方向是
# 「把一条流撑满 + 必要时用多条流叠加」，对应下面三组参数。
#
# ① 数据泵流水线深度：搬运时"读"和"写"必须能同时在跑。
#    旧实现是 recv → sendall → recv 串行，写端一阻塞（对端窗口满），
#    读端就停止抽干，本地接收窗口随之关闭 → 整条管道被自己的搬运代码扼住。
#    实测这层在回环上看不出来（只有 4 个内存拷贝），但在真实链路上，
#    它决定了"窗口"能不能被持续填满。
PUMP_QUEUE = 8               # 泵内允许的在途块数（8 × 256KB = 2MB 在途）
TUNNEL_SNDBUF = 1 << 20      # 隧道 WAN 侧发送缓冲 1MB
TUNNEL_RCVBUF = 1 << 20      # 隧道 WAN 侧接收缓冲 1MB（= 1MB 窗口）
# ② 上传体分块：旧实现把文件对象直接塞给 socket.sendall → TypeError，
#    每此上传都退回 urllib（新建两条连接 + 8KB 小块）。改成 1MB 分块。
UPLOAD_CHUNK = 1 << 20
# ③ 大文件多连接并行分段下载：单条流被链路压住时，N 条流的窗口可以叠加。
#    8MB 以下不分段（小文件建连开销占比大，分段反而更慢）。
STRIPE_MIN = 8 << 20
STRIPE_LANES = 4             # 默认并行路数
STRIPE_MAX_LANES = 8         # 上限（再多对发送端和链路都是负担）
# ④ v3.8.1：**全局**并发连接上限。
#    `workers`（同时传几个文件，最多 8）× `lanes`（每个大文件几路，最多 8）
#    理论峰值能到 64 条 TCP —— 在窄链路（家用上行、跨网段隧道）上这会互相
#    挤压：每条流分到的带宽更少、超时更容易触发、对端 accept 队列也吃紧。
#    实测 8 条以上在受控 40ms 链路上已无明显收益，反而抖动变大。
#    所以给所有"分段"连接加一个总闸门，超出就排队（不是丢弃）。
CONN_BUDGET = 8
# ⑤ v3.8.1：上传时"目标目录已存在哪些文件"的缓存有效期（秒）。
#    旧实现**每个文件**都发一次 /api/list 做冲突检查 —— 1 万个小文件就是
#    1 万次往返，经隧道（每条请求都要走影子端口）≈ 400 秒纯等待，而下载侧
#    是本地 os.path.exists、一次往返都不用。这就是"上传比下载慢一个数量级"
#    的根因。现在按目录缓存，自己传上去的文件就地更新缓存。
DIR_CACHE_TTL = 20.0

# ⑥ v3.8.2：上传的两个超时 —— 都是为了让"卡住"变成"报错"。
#
# 背景（用户反馈 #3）：「上传 3.8.1 客户端文件时，显示一直上传 且无法完成任务」。
# 根因是**两端互等**：
#   · 客户端声明了 Content-Length，但真正交出的字节数由 `f.read()` 决定；
#     源文件在上传途中被改写/截断时，实际发出去的会**少于**声明值；
#   · 服务端 `self.rfile.read()` 是**阻塞且无超时**的（连接建好时 sock 没设
#     timeout），它会一直等那批永远不来的字节；
#   · 客户端发完就在等响应 —— 于是两边谁都不动，要等客户端那个 7200 秒的
#     整体超时才报错。用户看到的正是"一直上传、永远完不成"。
#
# 三道防线（缺一不可）：
#   ① 客户端 `_Progress.read` 严格按声明长度交付，凑不满就**主动断开**（见
#      `_Progress` 的说明）—— 这是根治，让服务端立刻知道"体不完整"；
#   ② 服务端收 body 时给连接设一个**空闲超时**（UPLOAD_IDLE_TIMEOUT）——
#      就算对端是旧版本、就算网络黑洞，服务端也不会把线程永远挂在那里；
#   ③ 客户端整条请求的 socket 超时从 7200 秒收到 UPLOAD_SOCK_TIMEOUT ——
#      单次 send/recv 阻塞超过它即判失败。注意这是**每次**阻塞操作的超时，
#      不是整个文件的总时限（上传时每 8KB 就有一次 send，跑满带宽的链路
#      绝不会碰到它）；真碰到就说明链路确实死了。
UPLOAD_IDLE_TIMEOUT = 120.0     # 服务端：收 body 时多久没数据就判"上传中断"
UPLOAD_SOCK_TIMEOUT = 300.0     # 客户端：单次 send/recv 的最长阻塞时间

# v3.7.3 自动反向接入信令（UDP）：
#   接收端连接失败后把接入码广播/单播给对方，发送端自动接入隧道 ——
#   两边各点一次【连接】/【启动服务】即可，不再需要微信传码。
# 通道选 UDP 单播 + 广播：跨网段时组播基本出不去，而扫描查询能到对方
# （同一台机器能被"扫到"就证明 UDP 通道存在），单播走同样的路。
# 安全性：信令只含接入码，最终数据仍由服务令牌保护；局域网工具可接受。
REV_SIG_PORT = 53535
# ⚠ 同 REV_MAGIC：协议字面量，改名会破坏"新旧版本可互传"，故意保留 LANTRANSFER。
REV_SIG_MAGIC = "LANTRANSFER-REV/1"
REV_SIG_INTERVAL = 2.0       # 信令广播间隔（秒）
REV_SIG_TTL = 600            # 信令广播最长持续时间（秒），防止无限广播
# v3.7.9：同一来源的重复建链请求，最短间隔（秒）。
# ⚠ 这里**只**用来防"信令包风暴"，绝不能拿来当"试过一次就不再试"的闸门 ——
# 早期实现记的是"收到信令的时间"，于是**一次失败的接入会把之后 30 秒的信号
# 全部丢掉**：发送端建链失败（防火墙拦了 / 端口没就绪 / 抖动），接收端还在
# 每 2 秒重播，但发送端一律忽略 → 接收端等 15 秒看不到任何回应，
# 界面上就是「反向自动接入 timeout」，而且两边日志都不说明原因。
# 现在改成：只有在**确实还活着**的隧道存在时才忽略重复请求；
# 失败则立刻允许下一次信号重试（间隔只留 REV_SIG_DEBOUNCE 秒抗抖动）。
REV_SIG_DEBOUNCE = 2.5

# ==========================================================================
# v3.7.7 跨网段发现（UDP 单播探测，走 REV_SIG_PORT 同一端口）
# --------------------------------------------------------------------------
# 为什么需要它：mDNS（224.0.0.251:5353）与受限广播（255.255.255.255）都是
# **链路本地**的 —— 路由器默认不转发，所以跨网段时扫描必然一边通一边不通。
# 用户实测：.1.4（接收端）扫得到 .31.228；反过来 .31.228 扫不到 .1.4，
# 因为 .31.228 的探测包根本出不了它自己那台二级路由。
#
# 破法：既然「反方向」的 TCP/UDP 单播是通的（用户现场已经验证：.31.228
# 能给 .1.4 发信令、.1.4 的回复也能回去），那就把**发现**也搬到单播上。
# 接收端扫描时，除了 mDNS 组播/广播，再往"上次见过的地址"和手工填入的
# 地址发一条 PROBE 单播；发送端收到 PROBE 就用 PROBE_OK 单播回自己的
# 服务信息。与 mDNS 并行，谁先回用谁，互不干扰。
#
# 安全性：探测/应答只暴露"本机提供文件服务 + 端口 + 版本"，与 mDNS 广播
# 的信息完全等价（本来就在局域网里广播），不含令牌、不含任何路径。
# ⚠ 同 REV_MAGIC：协议字面量，改名会破坏"新旧版本可互传"，故意保留 LANTRANSFER。
DISCO_MAGIC = "LANTRANSFER-DISCO/1"
DISCO_PORT = REV_SIG_PORT    # 与信令共用端口，省得多开一个监听
DISCO_TIMEOUT = 0.9          # 单播探测等待时长（比 mDNS 短，因为是定向的）


def disco_probe_packet():
    """探测包：MAGIC|PROBE|主机名|版本\\n"""
    return ("%s|PROBE|%s|%s\n" % (DISCO_MAGIC, hostname(), VERSION)).encode("utf-8")


def disco_reply_packet(port, proto="https", version=VERSION, host=""):
    """应答包：MAGIC|HERE|主机名|版本|端口|协议|外层地址\\n"""
    return ("%s|HERE|%s|%s|%d|%s|%s\n"
            % (DISCO_MAGIC, host or hostname(), version, int(port), proto,
               getattr(_DISCO_EXT, "value", ""))).encode("utf-8")


def disco_parse(data):
    """解析探测/应答包。返回 (kind, dict) 或 (None, None)。"""
    try:
        parts = data.decode("utf-8", "replace").strip().split("|")
        if len(parts) < 2 or parts[0] != DISCO_MAGIC:
            return None, None
        kind = parts[1]
        if kind == "PROBE":
            return "PROBE", {"host": parts[2] if len(parts) > 2 else "",
                             "ver": parts[3] if len(parts) > 3 else ""}
        if kind == "HERE" and len(parts) >= 6:
            return "HERE", {"host": parts[2], "ver": parts[3],
                            "port": int(parts[4]), "proto": parts[5],
                            "ext": parts[6] if len(parts) > 6 else ""}
    except Exception:
        pass
    return None, None


class _DiscoExt(object):
    """当前生效的"外层可达地址"（UPnP 映射 ip:port），供应答包使用。

    单独放一个可变盒子，是为了让 disco_reply_packet 这个纯函数不用一路
    传参 —— 发送端启动/停止 UPnP 时只改这里。
    """
    def __init__(self):
        self.value = ""


_DISCO_EXT = _DiscoExt()


def disco_scan(peers, timeout=DISCO_TIMEOUT, log=None):
    """向指定地址集合发单播探测，收集应答（跨网段发现主通道）。

    peers: 可迭代的 "ip" 或 ("ip", port)。空集合直接返回 []。
    返回列表，元素格式与 mdns_scan 一致（name/host/ip/port/proto/version/os/ext）。
    """
    log = log or (lambda m: None)
    targets = []
    seen_t = set()
    for p in (peers or ()):
        ip = p if isinstance(p, str) else p[0]
        ip = (ip or "").strip()
        if not ip or ip in seen_t:
            continue
        # 只在私网/回环里探测 —— 收的是本工具广播过的地址，不做网段扫描
        if not (ip.startswith(("10.", "192.168.", "172.", "169.254.", "127."))):
            continue
        seen_t.add(ip)
        targets.append(ip)
    if not targets:
        return []

    found = {}
    s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    try:
        s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        s.bind(("", 0))
    except OSError as e:
        s.close()
        log("跨网段探测套接字建立失败: %s" % e)
        return []

    pkt = disco_probe_packet()
    s.settimeout(0.25)
    end = time.time() + max(0.3, timeout)
    sent = False
    try:
        while time.time() < end:
            if not sent:
                for ip in targets:
                    try:
                        s.sendto(pkt, (ip, DISCO_PORT))
                    except OSError:
                        pass
                sent = True
            try:
                data, addr = s.recvfrom(4096)
            except socket.timeout:
                continue
            except OSError:
                break
            kind, info = disco_parse(data)
            if kind != "HERE":
                continue
            ip = addr[0]
            found[ip] = {
                "name": "%s-%d" % (info.get("host") or ip, info.get("port") or 0),
                "host": info.get("host") or ip,
                "ip": ip,
                "port": info.get("port") or 0,
                "proto": info.get("proto") or "https",
                "version": info.get("ver") or "",
                "os": "",
                "ext": info.get("ext") or "",
                "via": "disco",          # 标记来源，便于日志区分
            }
    finally:
        s.close()
    out = [r for r in found.values() if r["port"]]
    out.sort(key=lambda r: r["name"].lower())
    if out:
        log("跨网段探测得到 %d 台: %s" % (len(out), "; ".join(
            "%s %s:%s" % (r["host"], r["ip"], r["port"]) for r in out)))
    return out


def rev_sig_packet(code, host=""):
    """构造信令包：MAGIC|接入码|主机名|版本\\n"""
    return ("%s|%s|%s|%s\n" % (REV_SIG_MAGIC, code, host or "", VERSION)).encode("utf-8")


def rev_sig_parse(data):
    """解析信令包，合法返回 dict，非法返回 None。"""
    try:
        parts = data.decode("utf-8", "replace").strip().split("|")
        if len(parts) == 4 and parts[0] == REV_SIG_MAGIC:
            code = parts[1].strip()
            ip_port = code.split("#")[0]
            if "#" in code and ":" in ip_port and ip_port.rsplit(":", 1)[1].isdigit():
                return {"code": code, "host": parts[2].strip(), "ver": parts[3].strip()}
    except Exception:
        pass
    return None


def _flow_usable(sock):
    """隧道数据流配对前的体检：这条流还活着吗。

    v3.7.11（现场「连上以后频繁失败」的关键一环）：预开的数据流躺在等待方
    队列里的时候，两端谁都可能把它关掉（发起方那边的空闲超时、NAT 把它掐了、
    对端进程重启…）。等待方的计数（_opened/_claimed）只能数条数，看不出
    一条流已经**死了**。于是下一个新连接被塞给这条尸体：
        _pump_pair 一读它就是 EOF → 立刻对影子连接 shutdown(SHUT_WR)
      → 客户端正在做 TLS 握手，收到 FIN →
        「连不上发送端 127.0.0.1:xxxxx（EOF occurred in violation of protocol）」
    可读（select 立刻返回）就意味着对端已发 FIN、或残留了脏数据 —— 两种都
    不能拿去配对，宁可丢掉重新要一条。
    """
    try:
        r, _w, _x = select.select([sock], [], [], 0)
    except (OSError, ValueError):
        return False
    return not r


def _pump_half(src, dst):
    """单向搬运直到对端关闭。半关闭写方向，让对方读到 EOF。

    v3.7.7：加 TCP_NODELAY —— 隧道里转发的都是短小请求/响应对，
    Nagle 算法会为了攒满 MSS 而把响应多压几十毫秒，串起来就是
    "点一下卡一下"。这个收发工具不需要合包，直接关掉。

    v3.7.11：**空闲超时绝不是"对端断开"**。socket.timeout 是 OSError 的子类，
    旧版一句 `except OSError: pass` 把它和真断开混为一谈，接着 finally 里
    shutdown(SHUT_WR) —— 于是"这条流没数据可搬"被误判成"这条流该关"。
    配合 _open_flow 里 create_connection(timeout=6) 留在 socket 上的 6 秒超时，
    结果就是**每条预开数据流闲置 6 秒整就自杀**，尸体堆在等待方队列里，
    下一个新连接必踩（现场实测：6.4~6.9 秒时 8 条流全部变尸体）。

    v3.8.0（路径优化，用户报「经反向代理只有几百 KB/s」）：
    **读和写必须在两个线程里同时进行**。旧实现是 recv → sendall → recv
    严格串行：`sendall` 一旦被对端窗口挡住，本函数就停止 `recv`，`src`
    的接收缓冲填满、通告窗口随之关小，上游被迫停发 —— 一条链路能跑多快
    变成了"本函数一次搬运能压住多少字节 / RTT"，而不是链路的真实能力。
    现在读端独立成线程、把块塞进有界队列（PUMP_QUEUE 块，默认
    8×256KB=2MB 在途），写端只管按序 sendall。**顺序不变**（单队列 FIFO），
    半关闭语义不变（读端 EOF → 队列排空 → shutdown(SHUT_WR)）。
    另外把收发缓冲从系统默认（Windows 约 64KB，跨网段时窗口偏小）
    抬到 TUNNEL_*（1MB），让"在途字节数 = 窗口 / RTT"这一项不再掐脖子。
    """
    stop = threading.Event()
    q = queue.Queue(maxsize=PUMP_QUEUE)

    def _reader():
        try:
            while not stop.is_set():
                try:
                    data = src.recv(262144)
                except socket.timeout:
                    continue          # 只是这段时间没数据，继续等，别关
                if not data:
                    break             # 对端关闭写方向
                while not stop.is_set():
                    try:
                        q.put(data, timeout=0.25)
                        break
                    except queue.Full:
                        continue      # 写端还没腾出位置，等一下再塞
        except OSError:
            pass
        finally:
            stop.set()                # 出错 / EOF：通知写端收尾

    try:
        try:
            src.setsockopt(socket.IPPROTO_TCP, socket.TCP_NODELAY, 1)
            dst.setsockopt(socket.IPPROTO_TCP, socket.TCP_NODELAY, 1)
            for s in (src, dst):
                try:
                    s.setsockopt(socket.SOL_SOCKET, socket.SO_RCVBUF,
                                 TUNNEL_RCVBUF)
                    s.setsockopt(socket.SOL_SOCKET, socket.SO_SNDBUF,
                                 TUNNEL_SNDBUF)
                except OSError:
                    pass
        except OSError:
            pass
        threading.Thread(target=_reader, daemon=True).start()
        while True:
            try:
                data = q.get(timeout=0.2)
            except queue.Empty:
                if stop.is_set():
                    break             # 读端已结束且队列已空 → 搬完了
                continue
            dst.sendall(data)
    except OSError:
        pass
    finally:
        stop.set()
        try:
            dst.shutdown(socket.SHUT_WR)
        except OSError:
            pass


def _pump_pair(a, b):
    """双向桥接两条 TCP。任一方向断开就把两条都关掉。"""
    t = threading.Thread(target=_pump_half, args=(b, a), daemon=True)
    t.start()
    try:
        _pump_half(a, b)
    finally:
        for s in (a, b):
            try:
                s.close()
            except OSError:
                pass


def _rev_close(s):
    """强制断开：先 shutdown 发 FIN，再 close。

    只调 close() 不够 —— 对端（或本机其它线程）如果还持有 makefile()
    的读对象，socket 的 _io_refs 不为 0，close() 不会真正关闭 FD，
    FIN 发不出去，对端的 recv 就永远等不到"掉线"。
    """
    if s is None:
        return
    try:
        s.shutdown(socket.SHUT_RDWR)
    except OSError:
        pass
    try:
        s.close()
    except OSError:
        pass


class ReverseTunnelWaiter(object):
    """等待方（通常是接收端，处于 NAT 外层）。

    开两个监听：
      * 接入端口（0.0.0.0:随机） —— 发起方连这里，第一条是控制连接，
        之后每条 TCP 就是一条数据流；
      * 影子端口（127.0.0.1:随机） —— 本机 HTTP 客户端连它等于连到
        对端服务；每个 accept 从数据流队列取一条来配对桥接。
    """

    def __init__(self, log=None, on_ready=None, on_lost=None):
        self.log = log or (lambda m: None)
        self.on_ready = on_ready or (lambda: None)
        self.on_lost = on_lost or (lambda: None)
        # v3.7.3: 8 位十六进制 → 4 位数字。接入码主要靠"对方发过来"，
        # 手输是兜底 —— 短一位是一位；真正的数据安全由服务令牌保证，
        # 这里只需挡住同网段里"恰好扫到端口"的误连（万分之一）。
        self.nonce = "%04d" % secrets.randbelow(10000)
        self.listen_sock = None
        self.shadow_sock = None
        self.ctrl = None
        self.ready = threading.Event()
        self.stop_event = threading.Event()
        self.flows = queue.Queue()
        self.pairs = []
        self.accept_ip = ""
        # v3.7.8：发起方服务端口的协议（https/http），握手里带过来。
        # 空串 = 旧版发起方没说 —— 调用方沿用"先试 https"的老逻辑。
        self.peer_proto = ""
        self._used_count = 0        # v3.7.7：已取走的数据流总数，回执给发起方

    # ---- 信息 ----
    def port(self):
        try:
            return self.listen_sock.getsockname()[1]
        except OSError:
            return 0

    def local_port(self):
        try:
            return self.shadow_sock.getsockname()[1]
        except OSError:
            return 0

    def code(self, ip=None):
        if ip is None:
            ip = _upnp_private_ip()
        return "%s:%d#%s" % (ip, self.port(), self.nonce)

    # ---- 生命周期 ----
    def start(self):
        self.listen_sock = socket.socket()
        self.listen_sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        self.listen_sock.bind(("0.0.0.0", 0))
        self.listen_sock.listen(8)
        self.shadow_sock = socket.socket()
        self.shadow_sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        self.shadow_sock.bind(("127.0.0.1", 0))
        self.shadow_sock.listen(8)
        for fn in (self._accept_access, self._accept_shadow):
            threading.Thread(target=fn, daemon=True).start()
        self.log("反向接入等待中，接入码 %s" % self.code())

    def stop(self):
        if self.stop_event.is_set():
            return
        self.stop_event.set()
        for s in (self.listen_sock, self.shadow_sock, self.ctrl):
            _rev_close(s)
        self.ctrl = None
        for a, b in self.pairs:
            for s in (a, b):
                _rev_close(s)
        self.pairs = []
        # v3.7.11：队列里还没配对的数据流也要关掉，否则每次断开都漏一批
        # fd（最多 REV_QUEUE_MAX 条），反复接入时会攒住不放。
        while True:
            try:
                _rev_close(self.flows.get_nowait())
            except queue.Empty:
                break
        self.ready.clear()

    # ---- 内部 ----
    def _accept_access(self):
        while not self.stop_event.is_set():
            try:
                conn, addr = self.listen_sock.accept()
            except OSError:
                break
            if not self.ready.is_set():
                self._handshake(conn, addr)
                continue
            if self.flows.qsize() >= REV_QUEUE_MAX:
                try:
                    conn.close()
                except OSError:
                    pass
                continue
            self.flows.put(conn)

    def _handshake(self, conn, addr):
        """第一条连接：校验接入码里的随机码，成功即成为控制连接。

        v3.7.8：行格式 `MAGIC <nonce> [proto]`。第 3 个字段是发起方
        服务端口的协议（https/http），用来纠正本机 remote.scheme ——
        影子端口是透明桥，必须跟对端说同一种话。旧版发起方没有这个
        字段，保持 None（调用方沿用原有猜测逻辑）。
        """
        try:
            conn.settimeout(6)
            line = conn.makefile("rb").readline(128)
            parts = line.decode("utf-8", "replace").strip().split()
            if len(parts) >= 2 and parts[0] == REV_MAGIC and parts[1] == self.nonce:
                if len(parts) >= 3 and parts[2].lower() in ("http", "https"):
                    self.peer_proto = parts[2].lower()
                conn.sendall(b"OK\n")
                conn.settimeout(None)
                self.ctrl = conn
                self.accept_ip = addr[0]
                self.ready.set()
                self.log("反向接入：发起方 %s 已连上，隧道就绪%s"
                         % (addr[0],
                            ("（对端服务协议 %s）" % self.peer_proto)
                            if self.peer_proto else ""))
                self.on_ready()
                threading.Thread(target=self._watch_ctrl, args=(conn,),
                                 daemon=True).start()
                return
        except OSError:
            pass
        try:
            conn.close()
        except OSError:
            pass

    def _watch_ctrl(self, conn):
        """盯着控制连接 —— 发起方掉线时复位等待状态。"""
        try:
            while not self.stop_event.is_set():
                if conn.recv(1) == b"":
                    break
        except OSError:
            pass
        if not self.stop_event.is_set() and self.ready.is_set():
            self.log("反向接入：发起方已断开")
            self.ready.clear()
            self.on_lost()

    def _accept_shadow(self):
        while not self.stop_event.is_set():
            try:
                conn, _ = self.shadow_sock.accept()
            except OSError:
                break
            flow = self._take_flow()
            if flow is None:
                # v3.7.11：这里以前静默关闭，用户只看到客户端报
                # 「连不上发送端 …」。隧道已经不可用时给一行明确的话，
                # 免得又去怀疑地址/令牌。
                self.log("隧道不可用（发起方已断开？），已拒绝一个本地连接")
                try:
                    conn.close()
                except OSError:
                    pass
                continue
            self.pairs.append((conn, flow))
            threading.Thread(target=_pump_pair, args=(conn, flow),
                             daemon=True).start()

    def _take_flow(self):
        """取一条**活着**的数据流来配对；没有就经控制连接向发起方要（NEED）。

        v3.7.7：每成功取走一条，就给发起方回一个 `USED n` —— 对方据此
        判断池子还剩多少、要不要补货。没有这个回执，对方只能靠"开出总数"
        猜，会出现"明明还有空闲流却一直补"或"池子空了才发现"两种错。

        v3.7.11（现场「连上以后频繁失败」的兜底修复，也是**唯一能兼容
        旧版发起方**的那一层）：取出来的流先体检，死了就丢掉再取。
        为什么必须有这一层：旧版发起方（≤3.7.10）的预开流会因空闲超时
        自杀（见 _open_flow / _pump_half 的说明），而等待方的计数看不出
        一条流已经死了。不加体检，客户端就会在 TLS 握手阶段收到 FIN。
        死流照样计入 `_used_count` 并回 USED —— 它确实已经"离开池子"了，
        这样发起方的补货线程才知道要补新的。NEED 只在不忙的时候发，
        避免"刚补来又被丢"的来回空转。
        """
        asked = False
        while not self.stop_event.is_set():
            try:
                flow = self.flows.get(timeout=0.2 if asked else 1.0)
            except queue.Empty:
                flow = None
            if flow is not None:
                if not _flow_usable(flow):
                    _rev_close(flow)
                    self._used_count += 1
                    self._notify_used()
                    if self.flows.qsize() < REV_POOL_MIN:
                        self._need_flow()
                    asked = True
                    continue
                self._used_count += 1
                self._notify_used()
                return flow
            if not self.ready.is_set():
                return None
            if self.flows.qsize() < REV_POOL_MIN:
                self._need_flow()
            asked = True
        return None

    def _notify_used(self):
        try:
            self.ctrl.sendall(b"USED %d\n" % self._used_count)
        except OSError:
            pass

    def _need_flow(self):
        try:
            self.ctrl.sendall(b"NEED\n")
        except OSError:
            pass


class ReverseTunnelOpener(object):
    """发起方（通常是发送端，处于 NAT 内层）。

    填接入码主动连出去：第一条 TCP 是控制连接（握手 + 收 NEED），
    之后每条 TCP 桥到本机服务端口，等价于把对端的请求接进来。
    """

    def __init__(self, code, service_port, log=None, on_lost=None, proto="https"):
        self.log = log or (lambda m: None)
        self.on_lost = on_lost or (lambda: None)
        ip_port, _, self.nonce = code.strip().partition("#")
        self.ip, self.port = ip_port.rsplit(":", 1)
        self.ip = self.ip.strip("[]")
        self.port = int(self.port)
        self.service_port = int(service_port)
        # v3.7.8：本机服务端口说的是哪种协议，握手时告诉对方 ——
        # 对方据此决定用 https 还是 http 说影子端口，不再靠猜。
        self.proto = "http" if str(proto).lower() == "http" else "https"
        self.ctrl = None
        self.stop_event = threading.Event()
        self.peer = ""
        # v3.7.7：在途（已开但未被对方用掉）的流计数，供补货线程判断。
        # `_opened` 只由本机线程加（补货线程 + NEED 响应线程），用锁保护；
        # `_claimed` 只由 _ctrl_recv 单线程写（对方回 USED n），不用锁。
        self._pool_lock = threading.Lock()
        self._opened = 0            # 累计开出
        self._claimed = 0           # 对方已用掉
        self._replenish_thread = None

    def alive(self):
        return not self.stop_event.is_set() and self.ctrl is not None

    def start(self):
        ctrl = socket.create_connection((self.ip, self.port), timeout=6)
        ctrl.settimeout(6)
        ctrl.sendall(("%s %s %s\n" % (REV_MAGIC, self.nonce, self.proto)).encode("utf-8"))
        resp = ctrl.makefile("rb").readline(16)
        if resp.strip() != b"OK":
            ctrl.close()
            raise RuntimeError("对方没有接受接入码")
        ctrl.settimeout(None)
        self.ctrl = ctrl
        self.peer = "%s:%d" % (self.ip, self.port)
        self.log("反向接入：已连上接收端 %s，隧道就绪" % self.peer)
        threading.Thread(target=self._ctrl_recv, daemon=True).start()
        # 预备一批数据流，省得对方的第一个请求干等
        for _ in range(REV_READY_PRE):
            self._open_flow()
        # v3.7.7：常驻补货 —— 池子一空就提前补，避免每个请求都现要一条
        self._replenish_thread = threading.Thread(
            target=self._replenish_loop, daemon=True)
        self._replenish_thread.start()

    def _replenish_loop(self):
        """后台保持至少 REV_POOL_MIN 条空闲流，上限 REV_POOL_MAX。

        没有它的话：池子用完 → 下个 HTTP 请求要等"NEED 往返 + 建 TCP"，
        跨网段延迟 30ms 时每个请求白加 ~60ms，列表/下载感受就是"卡"。

        "空闲流"= 已开出 - 对方已确认用掉。对方每用掉一条会回一个
        `USED` 计数行（见 ReverseTunnelWaiter._take_flow），比在这里
        自己猜要准 —— TCP 建好不等于对方已经拿走了。
        """
        while not self.stop_event.is_set() and self.alive():
            with self._pool_lock:
                opened = self._opened
            idle = max(0, opened - self._claimed)
            need = 0
            if idle < REV_POOL_MIN:
                room = REV_POOL_MAX - idle
                need = min(REV_POOL_MIN - idle, max(0, room))
            if need > 0:
                for _ in range(need):
                    if self.stop_event.is_set():
                        break
                    self._open_flow()
            self.stop_event.wait(0.25)

    def stop(self):
        if self.stop_event.is_set():
            return
        self.stop_event.set()
        _rev_close(self.ctrl)
        self.ctrl = None

    def _ctrl_recv(self):
        try:
            f = self.ctrl.makefile("rb")
            while not self.stop_event.is_set():
                line = f.readline(32)
                if not line:
                    break
                msg = line.strip()
                if msg == b"NEED":
                    self._open_flow()
                elif msg.startswith(b"USED"):
                    # v3.7.7：对方用掉了一条流 → 更新计数，补货线程据此补货。
                    # 格式 "USED n"（累计值，比逐条 +1 更能容忍丢行）。
                    try:
                        self._claimed = int(msg.split()[1])
                    except (IndexError, ValueError):
                        self._claimed += 1
        except OSError:
            pass
        finally:
            lost = not self.stop_event.is_set()
            self.stop()
            if lost:
                self.log("反向接入：与接收端的隧道已断开")
                self.on_lost()

    def _open_flow(self):
        """开一条数据流：接对方一条 + 接本机服务一条，然后桥接。"""
        if self.stop_event.is_set():
            return
        try:
            a = socket.create_connection((self.ip, self.port), timeout=6)
        except OSError as e:
            self.log("反向接入：开数据流失败 %s" % e)
            return
        try:
            b = socket.create_connection(("127.0.0.1", self.service_port),
                                         timeout=6)
        except OSError:
            try:
                a.close()
            except OSError:
                pass
            return
        # v3.7.7：隧道里跑的是短请求/响应，两端都关掉 Nagle，
        # 否则每个响应会被多压几十毫秒。
        # ★ v3.7.11（根因修复，别退化）：**必须把 6 秒的连接超时清掉**。
        # create_connection(timeout=6) 建完连接后，这个超时是**留在 socket 上**
        # 的。而 _pump_half 用 recv 搬运，闲置 6 秒就抛 socket.timeout；
        # socket.timeout 是 OSError 的子类，会被当成"对端断开"，
        # 接着 finally 里 shutdown(SHUT_WR) —— 于是**每条预开的数据流
        # 闲置 6 秒整就自杀**。尸体留在等待方队列里（计数看不出来），
        # 下一个新连接被塞给它，客户端 TLS 握手阶段就收到 FIN：
        #   「连不上发送端 127.0.0.1:xxxxx（EOF occurred in violation of
        #     protocol (_ssl.c:1131)）」
        # 这正是现场「连上以后频繁失败」的真凶（用影子端口 = 走隧道）。
        for s in (a, b):
            try:
                s.settimeout(None)          # 阻塞等，别让空闲超时误杀
                s.setsockopt(socket.IPPROTO_TCP, socket.TCP_NODELAY, 1)
            except OSError:
                pass
        with self._pool_lock:
            self._opened += 1
        threading.Thread(target=_pump_pair, args=(a, b), daemon=True).start()


# ==========================================================================
# 发送端: HTTPS 服务
# ==========================================================================

class SenderApp(object):
    """发送端服务端逻辑（与界面无关，可单独测试）。

    v3.8.1 共享范围语义（用户需求：默认全盘 + 可编辑列表 + 点击选中才共享）：
      · `roots is None`  → **默认共享全部磁盘**（share_all=True）。
      · `roots == []`    → **什么都不共享**（用户主动取消勾选的结果）。
      · 其他             → 只共享列出的目录（最小粒度 = 文件夹）。
    旧实现的 `roots or []  → 空则退回全部磁盘` 把上面第二种情形吞掉了，
    于是"清空共享"= "共享整机"，方向正好相反。
    """

    def __init__(self, roots=None, token="", allow_write=False, allow_delete=False,
                 log=None):
        self.share_all = roots is None
        if self.share_all:
            self.roots = [r["path"] for r in list_roots()]
        else:
            self.roots = [norm_path(r) for r in roots if str(r).strip()]
        self.token = token or ""
        self.allow_write = allow_write
        self.allow_delete = allow_delete
        self.log = log or (lambda msg: None)
        self.clients = 0

    # ---------- 信息 ----------
    def api_info(self):
        return {
            "app": APP, "version": VERSION,
            "hostname": hostname(), "platform": platform.platform(),
            "roots": list_roots(), "sep": os.sep,
            "allow_write": self.allow_write, "allow_delete": self.allow_delete,
            "shared": self.roots, "share_all": self.share_all,
            "tls": bool(getattr(self, "tls", False)),
        }

    def _guard(self, path, need=None):
        p = norm_path(path)
        if not self.share_all:
            if not self.roots:
                raise PermissionError("发送端未共享任何目录")
            if not inside_any(p, self.roots):
                raise PermissionError("超出共享范围: %s" % p)
        if need == "write" and not self.allow_write:
            raise PermissionError("发送端未开启写入权限")
        if need == "delete" and not self.allow_delete:
            raise PermissionError("发送端未开启删除权限")
        return p

    # ---------- 列表 ----------
    def api_list(self, path):
        if not (path or "").strip():
            roots = list_roots()
            entries = [{"name": root_disp(r), "path": r["path"], "dir": True,
                        "size": 0, "mtime": 0,
                        "icon": drive_icon_name(r["path"])} for r in roots]
            return {"path": "", "parent": None, "roots": roots, "entries": entries}

        p = self._guard(path)
        if not os.path.isdir(p):
            raise ValueError("不是目录: %s" % p)
        # 与 LocalPane.list_dir_entries 同款优化：scandir + 每条只 stat 一次。
        # 旧实现 stat 完再 isdir，等于把系统调用翻倍 —— 远端大目录（几万项）
        # 的列表请求会明显变慢，接收端感受就是"点进去要等很久"。
        entries = []
        try:
            with os.scandir(p) as it:
                for de in it:
                    try:
                        isdir = de.is_dir()
                    except OSError:
                        continue
                    try:
                        st = de.stat()
                    except OSError:
                        continue
                    entries.append({
                        "name": de.name, "path": de.path, "dir": isdir,
                        "size": 0 if isdir else st.st_size, "mtime": st.st_mtime,
                    })
        except PermissionError:
            raise PermissionError("无权限读取: %s" % p)
        entries.sort(key=lambda e: (not e["dir"], e["name"].lower()))
        # v3.8.1：[47] 审计发现的"同一坑两份代码" —— 这里过去仍用老写法
        # （dirname + exists + realpath 三重判断），与 LocalPane 已经修好的
        # `parent_of()` 是两套实现。虽然逐例比对结果一致，但盘符根那个
        # Windows 陷阱（dirname("C:") == "C:"）在这个老写法里是靠
        # realpath 巧合兜住的，换台机器/换个路径就可能漏。统一成 parent_of。
        return {"path": p, "parent": parent_of(p), "roots": list_roots(),
                "entries": entries}

    def api_walk(self, path, limit=WALK_LIMIT):
        """递归统计目录内容。

        返回 {"files": [...], "dirs": [...], "truncated": bool}。

        v3.8.1 新增 `dirs`：**空目录也要能传过去**。旧实现只收 filenames，
        源目录树里的空目录在目标端凭空消失 —— 做镜像/备份时目录结构对不上。
        现在把相对根目录的每一层都列出来，客户端按需重建。
        v3.8.1 新增 `truncated` **的消费**：服务端早就在返回这个字段了，
        但客户端从头到尾没人读它 —— 超过 20 万个文件时静默少传，
        用户完全不知道。现在客户端会明确报错。
        """
        p = self._guard(path)
        if os.path.isfile(p):
            st = os.stat(p)
            return {"files": [{"path": p, "size": st.st_size, "mtime": st.st_mtime}],
                    "dirs": [], "base": os.path.dirname(p), "truncated": False}
        files, dirs = [], []
        trunc = False
        for dirpath, dirnames, filenames in os.walk(p):
            if dirpath != p:
                dirs.append(dirpath)
            for fn in filenames:
                full = os.path.join(dirpath, fn)
                try:
                    st = os.stat(full)
                except OSError:
                    continue
                files.append({"path": full, "size": st.st_size, "mtime": st.st_mtime})
                if len(files) >= limit:
                    return {"files": files, "dirs": dirs, "base": p, "truncated": True}
        return {"files": files, "dirs": dirs, "base": p, "truncated": trunc}

    def api_hash(self, path):
        p = self._guard(path)
        st = os.stat(p)
        return {"md5": md5_file(p), "size": st.st_size, "mtime": st.st_mtime}

    # ---------- 写操作 ----------
    def api_mkdir(self, path):
        p = self._guard(path, "write")
        os.makedirs(p, exist_ok=True)
        return {"ok": True, "path": p}

    def api_rename(self, path, new_name):
        p = self._guard(path, "write")
        new_name = os.path.basename((new_name or "").strip().rstrip("\\/"))
        if not new_name:
            raise ValueError("新名字不能为空")
        tgt = self._guard(os.path.join(os.path.dirname(p), new_name), "write")
        if os.path.exists(tgt):
            raise ValueError("目标已存在: %s" % tgt)
        os.rename(p, tgt)
        return {"ok": True, "path": tgt}

    def api_delete(self, path):
        """删除文件或**整个目录树**。

        v3.8.1：目录改为递归删除。旧实现只 `os.rmdir` —— 非空目录直接
        报"目录不是空的"，用户在接收端上根本删不掉一个文件夹。
        ⚠ 这是真删、不进回收站，所以界面上的开关配了二次确认。
        """
        import shutil as _sh
        p = self._guard(path, "delete")
        if os.path.islink(p):
            os.remove(p)
        elif os.path.isdir(p):
            _sh.rmtree(p, ignore_errors=False)
        elif os.path.exists(p):
            os.remove(p)
        else:
            raise ValueError("不存在: %s" % p)
        return {"ok": True}

    # ---------- 缩略图（v3.8.1） ----------
    def api_thumb(self, path, w=160, h=160):
        """返回一张 PNG 缩略图。拿不到就抛 OSError，客户端退回类型图标。"""
        p = self._guard(path)
        if not os.path.isfile(p):
            raise ValueError("不是文件: %s" % p)
        data = shell_thumbnail_png(p, int(w), int(h))
        if not data:
            raise OSError("系统缩略图不可用")
        return data

    # ---------- 上传续传探测（v3.8.1） ----------
    def upload_stat(self, path, name):
        """上传前问一次：目标文件已存在多大 / 上次残留的临时文件多大。

        返回 {"exist": bool, "size": int, "mtime": float, "part": int}
        客户端据此决定从第几字节续传，以及"是否已被别人改过"。
        """
        folder = self._guard(path, "write")
        name = os.path.basename((name or "").replace("\\", "/"))
        if not name:
            raise ValueError("文件名无效")
        target = os.path.join(folder, name)
        out = {"exist": False, "size": 0, "mtime": 0.0, "part": 0}
        if os.path.isfile(target):
            try:
                st = os.stat(target)
                out.update({"exist": True, "size": st.st_size, "mtime": st.st_mtime})
            except OSError:
                pass
        tmp = target + PART
        if os.path.isfile(tmp):
            try:
                out["part"] = os.path.getsize(tmp)
            except OSError:
                out["part"] = 0
        meta = _read_part_meta(tmp)
        if meta:
            out["part_size"] = meta.get("size")
            out["part_mtime"] = meta.get("mtime")
        return out


class _Handler(http.server.BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"
    server_version = "LanShare/" + VERSION

    def log_message(self, fmt, *a):
        return

    # ---- 输出 ----
    def send_json(self, obj, code=200):
        body = json.dumps(obj, ensure_ascii=False).encode("utf-8")
        self.send_response(code)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.send_header("Cache-Control", "no-store")
        self.end_headers()
        if self.command != "HEAD":
            self.wfile.write(body)

    def read_json(self):
        if getattr(self, "_br", False):
            return getattr(self, "_bc", {})
        self._br = True
        try:
            n = int(self.headers.get("Content-Length") or 0)
        except ValueError:
            n = 0
        self._bc = {}
        if n > 0:
            try:
                self._bc = json.loads(self.rfile.read(n).decode("utf-8"))
            except Exception:
                self._bc = {}
        return self._bc

    def handle_one_request(self):
        # ★ v3.8.1 关键修复：**每个请求都必须清掉请求体缓存**。
        #
        # `read_json()` 把解析结果缓存在 `self._bc` 上，为的是"同一个请求里
        # 被读多次也只用读一次"。但这个缓存挂在**handler 实例**上，而
        # HTTP/1.1 keep-alive 下，一个实例会被 `handle_one_request` 反复调用、
        # 连续处理**多个**请求 —— 于是第二条 POST 会原样拿到第一条 POST 的报文。
        #
        # 症状：接收端连着发「新建目录 → 重命名 → 删除」时，只有第一条成功，
        # 后面全部报「新名字不能为空」「不存在: …」这类莫名其妙的错。
        # 这个 bug 其实一直在，只是过去这三个写接口**从来没有客户端调用过**
        # （全文件里 "api/delete" 只出现在路由那一行），所以从没暴露；
        # v3.8.1 把写接口接上界面之后立刻踩中。
        self._br = False
        self._bc = {}
        try:
            return http.server.BaseHTTPRequestHandler.handle_one_request(self)
        except (ConnectionAbortedError, ConnectionResetError, BrokenPipeError):
            self.close_connection = True

    # ---- 路由 ----
    def do_GET(self):
        self._route("GET")

    def do_HEAD(self):
        self._route("HEAD")

    def do_POST(self):
        self._route("POST")

    def _route(self, method):
        u = urllib.parse.urlparse(self.path)
        qs = urllib.parse.parse_qs(u.query)
        route = u.path.rstrip("/") or "/"
        app = self.server.app
        tok = app.token
        if tok and (qs.get("token", [""])[0] or self.headers.get("X-Token", "")) != tok:
            self.read_json()
            return self.send_json({"error": "unauthorized", "message": "访问令牌不对"}, 401)
        try:
            if route == "/api/info":
                return self.send_json(app.api_info())
            if route == "/api/list":
                return self.send_json(app.api_list(qs.get("path", [""])[0]))
            if route == "/api/walk":
                app.log("统计目录: %s" % qs.get("path", [""])[0])
                return self.send_json(app.api_walk(qs.get("path", [""])[0]))
            if route == "/api/hash":
                return self.send_json(app.api_hash(qs.get("path", [""])[0]))
            if route == "/api/thumb":
                # v3.8.1：缩略图是**二进制**（image/png），不走 send_json。
                return self._thumb(qs)
            if route == "/api/upload_stat":
                b = self.read_json()
                return self.send_json(app.upload_stat(b.get("path"), b.get("name")))
            if route == "/api/download":
                return self._download(qs, method)
            if route == "/api/mkdir" and method == "POST":
                b = self.read_json()
                app.log("新建目录: %s" % b.get("path"))
                return self.send_json(app.api_mkdir(b.get("path")))
            if route == "/api/rename" and method == "POST":
                b = self.read_json()
                return self.send_json(app.api_rename(b.get("path"), b.get("new_name")))
            if route == "/api/delete" and method == "POST":
                b = self.read_json()
                app.log("删除: %s" % b.get("path"))
                return self.send_json(app.api_delete(b.get("path")))
            if route == "/api/upload" and method == "POST":
                return self._upload(qs, app)
            return self.send_json({"error": "not_found", "message": "未知接口"}, 404)
        except PermissionError as e:
            self.read_json()
            return self.send_json({"error": "forbidden", "message": str(e)}, 403)
        except ValueError as e:
            self.read_json()
            return self.send_json({"error": "bad_request", "message": str(e)}, 400)
        except OSError as e:
            self.read_json()
            return self.send_json({"error": "os_error", "message": str(e)}, 500)
        except Exception as e:  # noqa
            self.read_json()
            return self.send_json({"error": "server_error", "message": repr(e)}, 500)

    # ---- 下载 ----
    def _download(self, qs, method):
        app = self.server.app
        rel = qs.get("path", [""])[0]
        try:
            target = app._guard(rel)
        except PermissionError as e:
            return self.send_json({"error": "forbidden", "message": str(e)}, 403)
        if not os.path.isfile(target):
            return self.send_json({"error": "not_found", "message": "文件不存在"}, 404)

        size = os.path.getsize(target)
        start, end, status = 0, size - 1, 200
        rng = self.headers.get("Range") or ""
        if rng.startswith("bytes="):
            a, _, b = rng[6:].split(",")[0].partition("-")
            try:
                if a == "":
                    start = max(0, size - int(b)) if b else 0
                else:
                    start = int(a)
                    if b:
                        end = min(int(b), size - 1)
                if start >= size:
                    self.send_response(416)
                    self.send_header("Content-Range", "bytes */%d" % size)
                    self.send_header("Content-Length", "0")
                    self.end_headers()
                    return
                status = 206
            except ValueError:
                start, end, status = 0, size - 1, 200
        length = max(0, end - start + 1)
        self.send_response(status)
        self.send_header("Content-Type", "application/octet-stream")
        self.send_header("Accept-Ranges", "bytes")
        self.send_header("Content-Length", str(length))
        if status == 206:
            self.send_header("Content-Range", "bytes %d-%d/%d" % (start, end, size))
        self.send_header("X-File-Size", str(size))
        self.send_header("X-File-Mtime", "%.0f" % os.path.getmtime(target))
        self.end_headers()
        if method == "HEAD":
            return
        remain = length
        try:
            with open(target, "rb") as f:
                f.seek(start)
                while remain > 0:
                    b = f.read(min(CHUNK, remain))
                    if not b:
                        break
                    self.wfile.write(b)
                    remain -= len(b)
        except (BrokenPipeError, ConnectionResetError, ConnectionAbortedError):
            self.close_connection = True
            app.log("接收端中断了下载: %s" % os.path.basename(target))

    # ---- 缩略图 ----
    def _thumb(self, qs):
        app = self.server.app
        try:
            data = app.api_thumb(qs.get("path", [""])[0],
                                 int(qs.get("w", ["160"])[0] or 160),
                                 int(qs.get("h", ["160"])[0] or 160))
        except PermissionError as e:
            return self.send_json({"error": "forbidden", "message": str(e)}, 403)
        except ValueError as e:
            return self.send_json({"error": "bad_request", "message": str(e)}, 400)
        except Exception as e:                                    # noqa
            return self.send_json({"error": "no_thumb", "message": str(e)}, 404)
        self.send_response(200)
        self.send_header("Content-Type", "image/png")
        self.send_header("Content-Length", str(len(data)))
        self.send_header("Cache-Control", "no-store")
        self.end_headers()
        if self.command != "HEAD":
            self.wfile.write(data)

    # ---- 上传 ----
    def _upload(self, qs, app):
        if not app.allow_write:
            self.read_json()
            return self.send_json({"error": "forbidden", "message": "发送端未开启写入权限"}, 403)
        try:
            folder = app._guard(qs.get("path", [""])[0], "write")
        except PermissionError as e:
            return self.send_json({"error": "forbidden", "message": str(e)}, 403)
        name = os.path.basename(qs.get("name", [""])[0].replace("\\", "/"))
        if not name:
            return self.send_json({"error": "bad_request", "message": "文件名无效"}, 400)
        os.makedirs(folder, exist_ok=True)
        target = os.path.join(folder, name)
        try:
            total = int(self.headers.get("Content-Length") or 0)
        except ValueError:
            total = 0
        # ---- v3.8.1 上传断点续传 ----
        # 客户端把"这个文件的完整长度"和"我要从第几字节开始"分别放在
        # X-File-Size / X-Offset 里（Content-Length 只是这一次要发的量）。
        # 旧版没有这两个头 → offset=0、fsize=total，行为与之前完全一致
        # （向下兼容：旧接收端对新发送端、新接收端对旧发送端都能跑）。
        try:
            fsize = int(self.headers.get("X-File-Size") or total or 0)
        except ValueError:
            fsize = total
        try:
            offset = int(self.headers.get("X-Offset") or 0)
        except ValueError:
            offset = 0
        try:
            src_mtime = float(self.headers.get("X-File-Mtime") or 0)
        except ValueError:
            src_mtime = 0.0
        tmp = target + PART
        # 元数据对不上（对方换了文件 / 是旧版本留下的残件）→ 丢弃重来
        if offset and not check_part_meta(tmp, fsize, src_mtime):
            drop_part(tmp)
            offset = 0
        if offset:
            try:
                real = os.path.getsize(tmp)
            except OSError:
                real = 0
            if real != offset:            # 残件长度与声明的起点不符 → 重来
                drop_part(tmp)
                offset = 0
        if not offset:
            # 从头传：把上一次的残件与旧元数据清掉，再写这次的元数据。
            drop_part(tmp)
            write_part_meta(tmp, fsize, src_mtime)
        app.log("接收上传: %s (%s%s)" % (
            name, human(fsize),
            "，从 %s 续传" % human(offset) if offset else ""))
        done = offset
        # v3.8.2：收 body 时给这条连接设一个**空闲超时**。
        #
        # 为什么必须有：`self.rfile.read()` 在连接没有 timeout 时会**无限阻塞**。
        # 对端只要声明的字节数没发满、又不断开连接（旧版客户端在源文件被
        # 截断时就是这样），这个线程就永远挂在 read 上 —— 服务端不报错、
        # 客户端在等响应，两边互等。用户看到的就是「一直上传 且无法完成任务」。
        # 设了超时以后，最长 UPLOAD_IDLE_TIMEOUT 秒没数据就判"上传中断"，
        # 明确回 500 并提示可以直接续传。
        prev_to = None
        try:
            prev_to = self.connection.gettimeout()
            self.connection.settimeout(UPLOAD_IDLE_TIMEOUT)
        except (OSError, AttributeError):
            prev_to = None
        try:
            with open(tmp, "ab" if offset else "wb") as f:
                remain = total
                while remain > 0:
                    b = self.rfile.read(min(CHUNK, remain))
                    if not b:
                        break
                    f.write(b)
                    done += len(b)
                    remain -= len(b)
        except socket.timeout:
            app.log("上传停滞超时（%.0f 秒没有数据）: %s（已收到 %s，可直接续传）"
                    % (UPLOAD_IDLE_TIMEOUT, name, human(done)))
            self.close_connection = True
            try:
                return self.send_json(
                    {"error": "stalled", "message": "上传停滞，已中止",
                     "done": done}, 500)
            except Exception:
                return
        except (BrokenPipeError, ConnectionResetError, ConnectionAbortedError):
            app.log("上传中断: %s（已收到 %s，可直接续传）" % (name, human(done)))
            try:
                return self.send_json({"error": "incomplete", "done": done}, 500)
            except Exception:
                return
        finally:
            # 后面还要用这条连接发响应、还可能 keep-alive 复用 —— 必须还原超时，
            # 否则下一次请求会莫名其妙地 120 秒就断。
            try:
                self.connection.settimeout(prev_to)
            except (OSError, AttributeError):
                pass
        if fsize and done != fsize:
            app.log("上传不完整: %s %d/%d" % (name, done, fsize))
            return self.send_json({"error": "incomplete", "message": "上传不完整",
                                   "done": done}, 500)
        os.replace(tmp, target)
        try:
            os.remove(_part_meta_path(tmp))
        except OSError:
            pass
        return self.send_json({"ok": True, "path": target, "size": done})

class ThreadingHTTPServerReuse(http.server.ThreadingHTTPServer):
    daemon_threads = True
    allow_reuse_address = (os.name != "nt")
    request_queue_size = 64
    ssl_context = None            # 非 None 时走 HTTPS

    def server_bind(self):
        if os.name == "nt":
            try:
                self.socket.setsockopt(socket.SOL_SOCKET, socket.SO_EXCLUSIVEADDRUSE, 1)
            except (AttributeError, OSError):
                pass
        http.server.ThreadingHTTPServer.server_bind(self)

    def get_request(self):
        """只 accept + 设 NODELAY；**TLS 握手留给工作线程**（v3.7.11）。

        为什么必需：get_request 是在 serve_forever 的**接受循环**里被调用的
        （socketserver._handle_request_noblock → get_request），在这里做 TLS
        握手等于"只要有一个客户端不发 ClientHello，整个服务的接受循环就停住"。
        而隧道场景里这种连接是**常态**：发起方预开的数据流先连上来，
        ClientHello 要等接收端把这条流配对给某个本地连接之后才到。
        旧版在这里 `sock.settimeout(20)` 干等，这 20 秒内**所有**新连接
        （包括已经配对、ClientHello 就躺在内核缓冲里的）都进不来 ——
        表现为"连上以后频繁失败 / 卡住"。挪进工作线程后，每条连接各自
        等自己的握手，接受循环永远不被拖住。
        """
        sock, addr = self.socket.accept()
        try:
            sock.setsockopt(socket.IPPROTO_TCP, socket.TCP_NODELAY, 1)
        except OSError:
            pass
        return sock, addr

    def process_request_thread(self, request, client_address):
        """工作线程：先做 TLS 握手（如有），再交给请求处理器。

        与 socketserver.ThreadingMixIn.process_request_thread 等价，
        只是多了一道握手 —— 见 get_request 的说明。
        """
        if self.ssl_context is not None:
            try:
                request.settimeout(TLS_HANDSHAKE_TIMEOUT)
                request = self.ssl_context.wrap_socket(request, server_side=True)
            except Exception:
                try:
                    request.close()
                except OSError:
                    pass
                return
            try:
                request.settimeout(None)
            except OSError:
                pass
        try:
            self.finish_request(request, client_address)
        except Exception:
            self.handle_error(request, client_address)
        finally:
            self.shutdown_request(request)

    def handle_error(self, request, client_address):
        exc = sys.exc_info()[1]
        if isinstance(exc, (ConnectionAbortedError, ConnectionResetError, BrokenPipeError,
                            ssl.SSLError, socket.timeout, OSError)):
            return
        http.server.ThreadingHTTPServer.handle_error(self, request, client_address)


def build_sender_server(port, roots=None, token="", allow_write=False,
                        allow_delete=False, log=None, bind="0.0.0.0",
                        tls=False, certfile=None, keyfile=None):
    app = SenderApp(roots=roots, token=token, allow_write=allow_write,
                    allow_delete=allow_delete, log=log)
    try:
        srv = ThreadingHTTPServerReuse((bind, port), _Handler)
    except OSError as e:
        raise RuntimeError("端口 %d 无法监听: %s\n可能已被占用, 换个端口试试。" % (port, e))
    if tls:
        try:
            ctx = ssl.SSLContext(ssl.PROTOCOL_TLS_SERVER)
            ctx.load_cert_chain(certfile, keyfile)
            ctx.minimum_version = ssl.TLSVersion.TLSv1_2
        except Exception as e:
            srv.server_close()
            raise RuntimeError("加载 TLS 证书失败: %r" % (e,))
        srv.ssl_context = ctx
    srv.app = app
    app.tls = bool(tls)
    return srv


# ==========================================================================
# 接收端: 远端客户端
# ==========================================================================

def _send_body(sock, body):
    """把 HTTP 请求体写到 socket 上（bytes 或**类文件对象**都支持）。

    v3.8.0（路径优化）：旧实现是 `sock.sendall(body)` —— 接收端上传时
    `body` 是一个带进度回调的伪文件对象，`sendall` 只吃 bytes-like，
    于是**每次上传都必然 TypeError**。后果顺着 `_open` 往下滚：
      关连接 → 重连一次 → 再失败 → 整体退回 urllib。
    白建两条连接（走隧道时每条还是一条独立数据流 + 一次 TLS 握手），
    而且 urllib 的 http.client 用的是 `blocksize = 8192`，文件体被切成
    8KB 小块发 —— 跨网段时这个粒度会让每个小块都要等窗口，吞吐明显吃亏。
    这里直接按 UPLOAD_CHUNK（1MB）读、1MB 发。
    """
    if hasattr(body, "read"):
        while True:
            b = body.read(UPLOAD_CHUNK)
            if not b:
                break
            sock.sendall(b)
        return
    sock.sendall(body)


class _PoolResponse(object):
    """在保活连接上读一个 HTTP 响应；读完把连接还回池子。

    对外接口刻意对齐 urlopen 的返回（`.status` / `.read()` / 上下文管理），
    这样 Remote.call / post / _download 三处调用点不用区分走的是
    "新建连接" 还是 "复用连接" —— 行为分叉是 bug 的温床。

    关键约束：响应必须**完整读完**再把连接放回池子。半读的连接复用会
    读到上一个响应的残余字节（表现为 JSON 解析炸、下载文件损坏）。

    v3.7.8 修复（重要）：还必须**确认对端没有要求关闭**才能回池。
    旧版无条件 `_pool_put`，于是出现这样的死循环：
      对端（或隧道，或中间设备）把空闲连接关掉 → 池子里留着死连接 →
      下次请求从池里取出 → 往死连接上写 → TLS 层报
      「EOF occurred in violation of protocol」→ 失败 → 又放回池子 …
    用户看到的「连不上发送端 127.0.0.1:51263（EOF …）」就是这个。
    修法有三道闸：
      ① 读 `will_close`（http.client 根据 `Connection: close` /
         无 Content-Length / HTTP/1.0 等推出的"对端要关"结论）；
      ② 显式检查响应头 `Connection: close`；
      ③ 读完后用 `select` 探一次可读 —— 可读即意味着对端已发
         FIN（EOF）或残留了脏数据，两种情况都**不能**再复用。
    """
    def __init__(self, sock, remote, timeout):
        import http.client as _hc
        self._sock = sock
        self._remote = remote
        # ★ v3.7.11：这两个**必须在 begin() 之前**初始化。
        # begin() 读响应行；对端半路断开时它会抛 SSLEOFError /
        # RemoteDisconnected，而 except 分支要调 self.close()，
        # close() 又要读 self._done —— 旧代码把 _done 放在最后赋值，
        # 于是 close() 抛 AttributeError，把真错整个覆盖掉，
        # 用户只能看到「'_PoolResponse' object has no attribute '_done'」，
        # 完全看不出是"对端把连接关了"。
        self._body = None
        self._done = False
        self._fp = sock.makefile("rb")
        self._resp = _hc.HTTPResponse(sock, method=None)
        try:
            self._resp.begin()
        except Exception:
            self.close()
            raise
        try:
            self.status = int(self._resp.status)
        except (TypeError, ValueError):
            self.status = None
        self.headers = self._resp.headers

    def _reusable(self, sock=None):
        """对端是否还愿意复用这条连接（决定能不能回池）。

        v3.7.8 坑：close() 会**先**把 self._sock 置 None 再调这里，
        若本方法内部读 self._sock 就会拿到 None、select 抛异常、
        被外层 except 吞成 False —— 表现是"池子永远是 0、提速全失效"。
        所以 socket 一律由调用方显式传入。
        """
        if sock is None:
            sock = self._sock
        if sock is None:
            return False
        # ① http.client 的判定（最权威：它见过全部响应头）
        if getattr(self._resp, "will_close", False):
            return False
        # ② 显式 Connection: close
        try:
            conn = (self.headers.get("Connection") or "").strip().lower()
        except Exception:
            conn = ""
        if conn == "close":
            return False
        # ③ 对端已经关了（FIN 到达）或留了脏字节 —— 两种情况都不能复用
        try:
            import select as _sel
            r, _w, _x = _sel.select([sock], [], [], 0)
            if r:
                return False
        except (OSError, ValueError, TypeError):
            return False
        return True

    def read(self, n=None):
        # 非 2xx 必须抛 HTTPError —— 调用方（call/post）就是靠这个分支
        # 把 401 令牌错误和其他错误分开处理的（401 不能被吞成普通异常）。
        if self.status is not None and self.status >= 400 and n is None:
            body = self._resp.read()
            self._done = True
            reason = getattr(self._resp, "reason", "") or ""
            err = urllib.error.HTTPError(
                "", self.status, reason, self.headers, _BytesIO(body))
            self.close()
            raise err
        data = self._resp.read() if n is None else self._resp.read(n)
        if n is None:
            self._done = True
        return data

    def getheader(self, name, default=None):
        return self.headers.get(name, default)

    def __enter__(self):
        return self

    def __exit__(self, *a):
        self.close()
        return False

    def close(self):
        """读完且对端仍愿复用 → 连接保活回池；否则直接关掉。"""
        sock = self._sock
        self._sock = None
        # getattr 兜底：__init__ 里 begin() 抛错时也会走到这（那时 _done
        # 可能还没赋值）—— 这里再抛一次就把真错顶掉了，见 __init__ 说明。
        keep = bool(getattr(self, "_done", False)) and sock is not None
        if keep:
            try:
                keep = self._reusable(sock)     # 必须显式传 socket（见 _reusable 说明）
            except Exception:
                keep = False
        try:
            self._resp.close()
        except Exception:
            pass
        try:
            self._fp.close()
        except Exception:
            pass
        if sock is None:
            return
        if keep:
            self._remote._pool_put(sock)
            return
        try:
            sock.close()
        except OSError:
            pass


class Remote(object):
    """接收端到发送端的客户端。

    scheme 默认 https；connect() 时若 HTTPS 失败会自动退回 http，
    这样新版接收端也能连旧版（v2.x 明文）发送端，不会互相锁死。
    """

    def __init__(self, host="", port=DEFAULT_PORT, token="", scheme="https"):
        self.host, self.port, self.token = host, port, token
        self.scheme = scheme or "https"
        self.info = None
        self.lock = threading.Lock()
        self._client_ctx = None
        self._opener = None
        # v3.7.7 连接保活池：浏览器式 keep-alive，把"每次点文件夹都重新
        # 三次握手 + TLS 握手"这笔固定开销摊掉。
        # 实测（本机回环、目录仅 5 项）：不复用 39 ms → 复用后个位数 ms；
        # 跨网段延迟 30ms 时差距更明显（那是每个请求白送 2 个 RTT）。
        self._pool = []                 # [(sock, scheme, host, port)]
        self._pool_lock = threading.Lock()
        self._pool_max = 4              # 最多留 4 条空闲连接
        # v3.7.10：最近一次建连失败的原因与环节（见 _pool_connect / _open）。
        #   _pool_last_err  原始异常对象（用来保住报错文案）
        #   _pool_last_kind "connect"=TCP 就没建起来 / "tls"=TCP 通了但不说 TLS
        #   _fail_kind      最近一次 _open 失败的环节，供 connect() 决定
        #                   要不要跳过"同地址换协议再试"
        self._pool_last_err = None
        self._pool_last_kind = None
        self._fail_kind = None
        # v3.7.8：是否经反向隧道（影子端口）连接。为 True 时不做
        # HTTPS→HTTP 跨协议回退（见 connect()）。
        self.via_reverse = False
        # v3.7.10：connect() 每换一组「地址 × 协议」就回调一次，供界面
        # 显示"直连尝试 2/4"。纯可选项 —— 不设也不影响 Remote 的行为，
        # 所以无界面的测试/命令行场景照旧可用。
        # 回调签名为 cb(done, total, host, port, scheme)，**在调用方
        # 自己的线程里执行**（对 GUI 来说就是后台线程）。
        self.on_attempt = None

    def client_ctx(self):
        if self._client_ctx is None:
            self._client_ctx = make_client_ssl_context()
        return self._client_ctx

    # ---- v3.7.7 连接池 ----
    def _pool_key(self):
        return (self.scheme, self.host, self.port)

    def _pool_take(self):
        """取一条复用连接（同 scheme/host/port），没有就返回 None。"""
        key = self._pool_key()
        with self._pool_lock:
            for i in range(len(self._pool) - 1, -1, -1):
                item = self._pool[i]
                if item[0] == key:
                    self._pool.pop(i)
                    return item[1]
        return None

    def _pool_put(self, sock):
        """把用过的连接放回池子（超上限就关掉）。"""
        if sock is None:
            return
        with self._pool_lock:
            if len(self._pool) >= self._pool_max:
                try:
                    sock.close()
                except OSError:
                    pass
                return
            self._pool.append((self._pool_key(), sock))

    def _pool_clear(self):
        """连接目标变了 / 断开时，把池子清空。"""
        with self._pool_lock:
            pool, self._pool = self._pool, []
        for _k, s in pool:
            try:
                s.close()
            except OSError:
                pass

    def _pool_connect(self, timeout):
        """新建一条到当前目标的连接（HTTP 裸 TCP / HTTPS 包一层 SSL）。

        失败返回 None，并把**原始异常**和**失败环节**记到
        `self._pool_last_err` / `self._pool_last_kind` —— 调用方据此判断
        "连都没连上"（kind="connect"，urllib 走同一条路只会撞同一堵墙，
        可以安全跳过，省掉一倍等待）还是"连上了但 TLS 说不到一块"
        （kind="tls"，值得换个协议再试）。

        ⚠ v3.7.10 之前这里返回 None 就完事，调用方只能一律退回 urllib；
        实测（Windows + 安全软件拦 SYN 不回 RST）对**被拒端口**的
        `create_connection` 要 ~2.05 秒才报错，urllib 再撞一次就是
        4.10 秒/组、两种协议叠起来 8 秒 —— 用户症状就是"长时间连接中"。
        """
        self._pool_last_err = None
        self._pool_last_kind = None
        try:
            sock = socket.create_connection((self.host, int(self.port)), timeout)
        except Exception as e:
            self._pool_last_err = e
            self._pool_last_kind = "connect"
            return None
        try:
            sock.setsockopt(socket.IPPROTO_TCP, socket.TCP_NODELAY, 1)
        except OSError:
            pass
        if self.scheme == "https":
            try:
                sock = self.client_ctx().wrap_socket(
                    sock, server_hostname=self.host)
            except Exception as e:
                self._pool_last_err = e
                # TCP 是通的，只是这块端口不说 TLS —— 换个协议（http）
                # 再试是**有意义**的，不能跳过。
                self._pool_last_kind = "tls"
                try:
                    sock.close()
                except OSError:
                    pass
                return None
        return sock

    def _send_on(self, sock, req, timeout):
        """在已有连接上发一个请求，返回类 file 对象（带 read/status）。

        返回的对象必须也暴露 `.status` / `.read()`，因为调用方
        （call/post/_download）就是按 urlopen 的返回用它的。
        """
        import http.client as _hc
        url = req.full_url
        parsed = urllib.parse.urlsplit(url)
        path = parsed.path or "/"
        if parsed.query:
            path += "?" + parsed.query
        method = req.get_method()
        body = req.data
        headers = {k: v for k, v in req.header_items()}
        if body is not None and "Content-Length" not in headers:
            headers["Content-Length"] = str(len(body))
        if "Host" not in headers and "host" not in {k.lower() for k in headers}:
            headers["Host"] = parsed.netloc
        sock.settimeout(timeout)
        # 直接用 socket 拼 HTTP/1.1 报文（比 http.client 少一层状态，
        # 且能精确控制 Connection: keep-alive）
        lines = ["%s %s HTTP/1.1" % (method, path)]
        for k, v in headers.items():
            lines.append("%s: %s" % (k, v))
        lines.append("Connection: keep-alive")
        req_bytes = ("\r\n".join(lines) + "\r\n\r\n").encode("latin-1")
        sock.sendall(req_bytes)
        if body is not None:
            _send_body(sock, body)
        return _PoolResponse(sock, self, timeout)

    def url(self, path, q=None):
        q = dict(q or {})
        if self.token:
            q["token"] = self.token
        qs = urllib.parse.urlencode(q)
        return "%s://%s:%d%s%s" % (self.scheme, self.host, self.port, path,
                                   ("?" + qs) if qs else "")

    def _open(self, req, timeout):
        # 局域网工具绝不能走系统代理（TUN/代理会把内网请求吞掉或 502）。
        # 注意：urlopen(context=...) 的 context 参数在 OpenerDirector.open()
        # 上并不存在 —— 自签证书的 SSL 上下文必须装进 HTTPSHandler，
        # 连同"禁用代理"一起构建 opener。HTTP/HTTPS 处理器都装上，
        # 这样同一个 opener 在 https→http 回退时也能继续用。
        #
        # v3.7.7：优先走 keep-alive 连接池 —— 这是"点对方文件夹感觉卡"
        # 的主因所在。urllib 每次调用都新建连接（TCP 三次握手 + TLS 握手），
        # 实测本机回环下光这一项就让"只有 5 项的根目录"也要 39ms；
        # 跨网段（RTT 30ms 级）时每点一次要白等 ~60ms。
        # 池里失败一律静默退回 urllib —— 错误语义与旧版完全一致。
        #
        # v3.7.8：复用失败时**顺手把池子清空**。不清的话可能出现
        # "池里那一条永远是死的"——每次都取到同一个坏连接、每次都失败，
        # 用户侧表现为反复报同一个错（见 _PoolResponse 的说明）。
        #
        # v3.7.10：区分"连都没连上"和"连上了但没说成"。
        # 前者（kind="connect"）绝不能再让 urllib 重试一遍 ——
        # urllib 走的是完全相同的 create_connection + 同一个 SSL 上下文，
        # 撞的是同一堵墙，纯属白等。实测部分 Windows（安全软件拦 SYN、
        # 不回 RST）对**被拒端口**要 ~2.05 秒才报错，白等一遍就是 4.10 秒/组，
        # https+http 叠起来 8 秒——用户症状正是"长时间显示连接中"。
        self._fail_kind = None
        last_err = None
        for attempt in (0, 1):
            sock = self._pool_take()
            reused = sock is not None
            if sock is None:
                sock = self._pool_connect(timeout)
            if sock is None:
                err = getattr(self, "_pool_last_err", None)
                kind = getattr(self, "_pool_last_kind", None)
                if err is not None and kind == "connect":
                    # 传输层建不起来 → 直接把原始异常抛出去。
                    # 用 URLError 包一层是为了**保住原有报错文案**：
                    # 上层 call()/post() 取 e.reason，拼出来跟以前一字不差。
                    # 同时标出 _fail_kind，让 connect() 知道"这个地址的
                    # 这两种协议都不用再试了"（TCP 端点都一样）。
                    self._fail_kind = kind
                    raise urllib.error.URLError(err)
                break
            try:
                return self._send_on(sock, req, timeout)
            except Exception as e:
                last_err = e
                # 复用失败（对端关了空闲连接 / 隧道半路断）→ 关掉再试一次
                try:
                    sock.close()
                except OSError:
                    pass
                if reused:
                    # 刚才那条来自池子，说明池里的可能都过期了，整体清掉
                    self._pool_clear()
                if attempt == 1:
                    break
        if self._opener is None:
            self._opener = urllib.request.build_opener(
                urllib.request.ProxyHandler({}),
                urllib.request.HTTPSHandler(context=self.client_ctx()))
        try:
            return self._opener.open(req, timeout=timeout)
        except Exception:
            # urllib 也失败：如果池化路径里有更具体的错，把它带出去，
            # 否则用户只会看到 urllib 那句泛泛的报错、丢掉了真因。
            if last_err is not None:
                self._pool_clear()
            raise

    def _err(self, e):
        msg = ""
        try:
            msg = json.loads(e.read().decode("utf-8")).get("message", "")
        except Exception:
            pass
        return RuntimeError("%s%s" % (e.code, (" · " + msg) if msg else ""))

    def call(self, path, q=None, timeout=20):
        """GET，返回 JSON。"""
        h = {"X-Token": self.token} if self.token else {}
        req = urllib.request.Request(self.url(path, q), headers=h)
        try:
            with self._open(req, timeout) as r:
                return json.loads(r.read().decode("utf-8"))
        except urllib.error.HTTPError as e:
            raise self._err(e)
        except (urllib.error.URLError, ssl.SSLError, OSError) as e:
            raise RuntimeError("连不上发送端 %s:%d（%s）"
                               % (self.host, self.port, getattr(e, "reason", e)))

    def post(self, path, payload, timeout=30):
        """POST JSON。"""
        h = {"Content-Type": "application/json"}
        if self.token:
            h["X-Token"] = self.token
        req = urllib.request.Request(self.url(path), data=json.dumps(payload).encode("utf-8"),
                                     headers=h)
        try:
            with self._open(req, timeout) as r:
                return json.loads(r.read().decode("utf-8"))
        except urllib.error.HTTPError as e:
            raise self._err(e)
        except (urllib.error.URLError, ssl.SSLError, OSError) as e:
            raise RuntimeError("连不上发送端 %s:%d（%s）"
                               % (self.host, self.port, getattr(e, "reason", e)))

    # ---- v3.8.1 写操作封装 ----
    # 这三个接口服务端**从 v3.6 起就注册好了**，但客户端一直没有封装、
    # 界面也没有入口 —— 全文件里 "api/delete" 只出现在路由那一行。
    # 结果就是发送端那个「允许接收端删除本机文件（危险，默认关）」是个
    # **空开关**：勾了不产生任何后果，用户要么白白紧张，要么以为已经放开
    # 却发现对面根本删不掉。现在补齐客户端侧。
    def mkdir(self, path, timeout=20):
        return self.post("/api/mkdir", {"path": path}, timeout=timeout)

    def rename(self, path, new_name, timeout=20):
        return self.post("/api/rename", {"path": path, "new_name": new_name},
                         timeout=timeout)

    def delete(self, path, timeout=60):
        return self.post("/api/delete", {"path": path}, timeout=timeout)

    def walk(self, path, timeout=1800):
        return self.call("/api/walk", {"path": path}, timeout=timeout)

    def upload_stat(self, folder, name, timeout=20):
        return self.post("/api/upload_stat", {"path": folder, "name": name},
                         timeout=timeout)

    def thumb(self, path, w=160, h=160, timeout=30):
        """取一张 PNG 缩略图（bytes）；对端没有缩略图能力时抛异常。

        ⚠ 别把请求头那个局部变量叫 `h` —— 它会把高度参数覆盖掉，
        于是查询串里的 h 变成 `%7B%27X-Token%27...%7D`（dict 的 str），
        服务端拿一个字典去转 int 必然 400。这里统一叫 heads。
        """
        heads = {"X-Token": self.token} if self.token else {}
        req = urllib.request.Request(
            self.url("/api/thumb", {"path": path, "w": w, "h": h}), headers=heads)
        try:
            with self._open(req, timeout) as r:
                return r.read()
        except urllib.error.HTTPError as e:
            raise self._err(e)
        except (urllib.error.URLError, ssl.SSLError, OSError) as e:
            raise RuntimeError("取缩略图失败（%s）" % getattr(e, "reason", e))

    def connect(self):
        """优先 HTTPS；只有在 HTTPS 完全连不上时才退回 HTTP（兼容旧版发送端）。

        注意：令牌错误(401)等情况属于"连上了但没通过校验"，绝不能回退，
        否则会把真正的原因掩盖掉。

        v3.7: 直连失败（超时类）且扫描结果带 ext= 跨网段地址（发送端在
        二级路由后、已由 UPnP 登记端口映射）时，自动改连 ext 地址再试。
        """
        # v3.7.8：反向隧道用的是本机影子端口，协议由对端服务决定，
        # 不能靠"换协议再撞一次"来试探（见下方 schemes 说明）。
        via_tunnel = bool(getattr(self, "via_reverse", False))
        targets = [(self.host, self.port)]
        if getattr(self, "ext_addr", ""):
            try:
                eip, eport = self.ext_addr.rsplit(":", 1)
                eip, eport = eip.strip("[]"), int(eport)
                if (eip, eport) != (self.host, self.port):
                    targets.append((eip, eport))
            except (ValueError, AttributeError):
                pass

        first = None
        # v3.7.8：跨协议回退的规则改了两处 ——
        #   · 直连：保持原能力（https 失败退 http），兼容只会明文的老版本；
        #   · 反向隧道：对端协议**已经从握手里知道**（do_connect 已把
        #     self.scheme 设成它），正常情况下第一枪就打对；只有对端是
        #     旧版发起方（没说协议）时还留着退一次的机会当保险。
        #     退一次没问题 —— 出问题的是"退完把降级值留成残留状态"，
        #     那由 do_connect 每次重置 self.scheme 兜住了。
        schemes = [self.scheme]
        if self.scheme == "https":
            schemes.append("http")
        elif not via_tunnel:
            schemes.append("https")
        # v3.7.10：把"总共要试几组、现在试到第几组"算出来。
        # 最坏 2 个地址（直连地址 + UPnP 外部地址）× 2 种协议 = 4 组，
        # 每组 6 秒超时 —— 也就是最坏 24 秒。这个数字必须让用户看得见，
        # 否则他会以为程序死了（见 v3.7.10 的连接过程内联进度）。
        total = len(targets) * len(schemes)
        done = 0
        for thost, tport in targets:
            for scheme in schemes:
                # v3.7.7：目标或协议一变，池子里的旧连接全部作废
                # （留着会往错的地址发请求 —— 池 key 虽然能区分，
                #   但主动清掉更省心，反正重连一次的成本只在首帧）。
                if (scheme, thost, tport) != (self.scheme, self.host, self.port):
                    self._pool_clear()
                self.scheme = scheme
                self.host, self.port = thost, tport
                done += 1
                # v3.7.10：报进度给界面。回调在**调用方线程**里执行
                # （GUI 那边是后台线程，由它自己 post 回主线程）。
                cb = getattr(self, "on_attempt", None)
                if cb is not None:
                    try:
                        cb(done, total, thost, tport, scheme)
                    except Exception:
                        pass
                try:
                    info = self.call("/api/info", timeout=6)
                except urllib.error.HTTPError:
                    raise
                except Exception as e:
                    # v3.7.3: 401 = TCP 已连上但令牌被拒 —— 网络是通的，
                    # 换协议/换地址再试也没有意义，立即抛出（原实现会
                    # 把 4 种组合全部试完再报错，白白多等二十多秒）。
                    if str(e).startswith("401"):
                        raise
                    if first is None:
                        first = e
                    # v3.7.10：TCP 压根没建起来时，**同地址换协议是白试** ——
                    # https 和 http 打的是同一个 IP:端口，一个被拒/超时，
                    # 另一个必然一样（协议是建立在 TCP 之上的，TCP 都没通
                    # 就谈不上协议）。实测本机被拒端口单次 2.05 秒，
                    # 不跳的话 https+http 白等 4.1 秒/地址，两个地址 8.2 秒。
                    # ⚠ 只跳"connect"这一类；"tls"（TCP 通了但对方不说 TLS）
                    #   恰恰说明该换 http 再试，绝不能跳。
                    # ext 地址是**另一个** IP:端口，跳过协议后继续试它 ——
                    # 所以这里是 break 而不是 return。
                    if getattr(self, "_fail_kind", None) == "connect":
                        break
                    continue
                if info.get("app") != APP:
                    raise RuntimeError("目标不是本软件的发送端")
                self.info = info
                if len(targets) > 1:
                    self.used_ext = True
                return info
        raise first if first else RuntimeError("连接失败")


# ==========================================================================
# 传输引擎（不依赖界面，可单独测试）
# ==========================================================================

class _NoRange(Exception):
    """对端不按 Range 返回（旧版发送端 / 不支持分段）→ 退回单流下载。"""
    pass


class _Busy(Exception):
    """分段名额暂时不够（别的文件占着）→ 这个文件退回单流，不算错误。"""
    pass


class _Aborted(BaseException):
    """需要**立刻放弃这次请求**：用户按了停止，或源文件在传输途中变了。

    为什么继承 `BaseException` 而不是 `Exception`（这是刻意的）：
    上传的请求体是个文件对象，异常是在 http.client **发送过程中**抛出来的，
    沿途有好几层 `except Exception` —— `Remote._open` 的重试、urllib 回退、
    worker 的兜底。继承 Exception 会被它们逐层吞掉，然后**把整个文件重发
    一遍甚至两遍**（最坏 3 次），白白多等几个 300 秒。继承 BaseException
    则这些层一律不拦，异常一次穿透到底。

    代价是必须显式接住它：见 `TransferEngine._worker` 里第一个 except 分支。
    没接住的话线程会带着 traceback 退出（虽然功能上"停了"，但日志很脏）。
    """
    pass


# Windows 文件属性：重解析点（junction / 符号链接 / 挂载点）
FILE_ATTRIBUTE_REPARSE_POINT = 0x400


def prune_reparse(dirpath, names):
    """就地剔除 junction / 符号链接子目录，返回被剔除的名字。

    v3.8.2 新增。为什么必须做：Windows 上 `os.walk` **会跟进 junction**，
    而系统里存在自指的 junction —— 最典型的是
    `C:\\ProgramData\\Application Data` → 指回 `C:\\ProgramData` 自己。
    于是 `os.walk` 无限递归：选中一个盘符根去上传，界面会永远停在
    "正在统计要传输的文件…"（用户反馈 #3 的现场之一）。
    `os.walk(followlinks=False)` 拦不住这种 —— junction 在 Python 里
    并不总被判定成符号链接（`os.path.islink` 对 junction 时真时假）。

    判据用 `st_file_attributes & FILE_ATTRIBUTE_REPARSE_POINT`：
    这是内核对"这个目录项不是普通目录"的权威标记，Win7 起就有。
    """
    dead = []
    for nm in list(names):
        p = os.path.join(dirpath, nm)
        try:
            st = os.lstat(p)
        except OSError:
            dead.append(nm)
            continue
        if getattr(st, "st_file_attributes", 0) & FILE_ATTRIBUTE_REPARSE_POINT:
            dead.append(nm)
        elif os.path.islink(p):
            dead.append(nm)
    for nm in dead:
        try:
            names.remove(nm)
        except ValueError:
            pass
    return dead


def file_busy_reason(path):
    """这个文件现在能不能被稳定地读？不能就返回一句**人话**原因，能则 None。

    v3.8.2 新增，对应反馈 #3 的后半句：「要么杜绝上传正在使用的文件…避免
    永远无法完成」。

    为什么不能只 `try: open(path)`：那只能发现"别人独占"，发现不了
    "别人正在往里写"（Windows 上照样能读到，只是一直在变长/变短）。所以：

      · **这里**查的是"独占占用" —— 用 `CreateFileW` 只声明
        `FILE_SHARE_READ` 试开一次：如果别的进程已经把它独占打开了，
        这次打开会以 ERROR_SHARING_VIOLATION(32) 失败，于是我们能在**开始
        传之前**把原因说清楚，而不是传到一半卡住。
      · "文件在传的过程中被改"由调用方在传完之后比对 size/mtime 兜住
        （见 `TransferEngine._up`）—— 那才是"读到一半变短"的真正来源。
    """
    if not path or not os.path.isfile(path):
        return "源文件不存在（可能已被移动或删除）"
    if os.name != "nt":
        try:
            with open(path, "rb"):
                pass
            return None
        except OSError as e:
            return "读不到源文件：%s" % e
    try:
        import ctypes
        k = ctypes.WinDLL("kernel32", use_last_error=True)
        k.CreateFileW.argtypes = [
            ctypes.c_wchar_p, ctypes.c_uint32, ctypes.c_uint32,
            ctypes.c_void_p, ctypes.c_uint32, ctypes.c_uint32, ctypes.c_void_p]
        k.CreateFileW.restype = ctypes.c_void_p
        GENERIC_READ = 0x80000000
        FILE_SHARE_READ = 0x00000001
        OPEN_EXISTING = 3
        FILE_ATTRIBUTE_NORMAL = 0x80
        ctypes.set_last_error(0)
        h = k.CreateFileW(path, GENERIC_READ, FILE_SHARE_READ, None,
                          OPEN_EXISTING, FILE_ATTRIBUTE_NORMAL, None)
        INVALID = ctypes.c_void_p(-1).value
        if not h or h == INVALID:
            err = ctypes.get_last_error()
            if err in (32, 33):        # SHARING_VIOLATION / LOCK_VIOLATION
                return ("文件正被其他程序占用（连只读都打不开）——\n"
                        "请先关闭正在使用它的程序，再重新上传。")
            if err == 5:               # ACCESS_DENIED
                return "没有读取该文件的权限（系统拒绝访问）"
            return "源文件打不开（系统错误 %d）" % err
        try:
            k.CloseHandle(ctypes.c_void_p(h))
        except Exception:
            pass
        return None
    except Exception:
        # 探测本身失败不该拦路 —— 让它继续走正常流程，真出问题由传输报错。
        return None


class Job(object):
    def __init__(self, direction, items, policy="skip", dirs=None):
        self.id = "j%d" % int(time.time() * 1000 % 10 ** 9)
        self.direction = direction          # 'down' | 'up'
        self.items = items
        self.policy = policy
        # v3.8.1：「下载空目录」勾选时，这里是要在目标端重建的目录列表
        # （绝对路径）。不勾选就是空列表 —— 与旧行为完全一致。
        self.dirs = list(dirs or [])
        self.state = "running"              # running / done / stopped
        self.lock = threading.Lock()
        self.stop = threading.Event()
        self.total_bytes = sum(int(i.get("size") or 0) for i in items)
        self.done_bytes = 0
        self.done_files = 0
        self.failed = 0
        self.skipped = 0
        self.skipped_bytes = 0
        self.started = time.time()
        self.speed = 0.0
        self.msg = ""

    def snapshot(self):
        with self.lock:
            el = max(0.001, time.time() - self.started)
            sp = (self.done_bytes / el) if self.state == "running" else self.speed
            left = max(0, self.total_bytes - self.done_bytes - self.skipped_bytes)
            return {
                "id": self.id, "direction": self.direction, "state": self.state,
                "total_bytes": self.total_bytes, "done_bytes": self.done_bytes,
                "skipped_bytes": self.skipped_bytes,
                "total_files": len(self.items), "done_files": self.done_files,
                "failed": self.failed, "skipped": self.skipped,
                "speed": sp, "eta": (left / sp) if sp > 1 else None,
                "elapsed": el, "msg": self.msg,
            }


class TransferEngine(object):
    """item 字段:
         down: {src: 远端绝对路径, target: 本机绝对路径, size, rel}
         up:   {src: 本机绝对路径, dir: 远端目标目录, name, target: 远端完整路径, size, rel}
    """

    def __init__(self, remote, workers=3, log=None):
        self.remote = remote
        self.workers = max(1, int(workers))
        # v3.8.0（路径优化）：单个大文件的并行分段路数。
        # 与 workers 是两件事：workers = 同时传几个**文件**，
        # lanes = 一个**大文件**自己用几条连接拉。
        self.lanes = STRIPE_LANES
        self.log = log or (lambda m: None)
        self.jobs = []
        self.lock = threading.Lock()
        # v3.8.1：分段连接的全局闸门（见 CONN_BUDGET 说明）
        self._lanes_used = 0
        self._lanes_lock = threading.Lock()
        # v3.8.1：上传冲突检查的目录缓存 {dir: (t, {name: entry})}
        self._dir_cache = {}
        self._dir_lock = threading.Lock()

    # ---------- v3.8.1 全局并发闸门 ----------
    def _lanes_free(self):
        with self._lanes_lock:
            return max(0, CONN_BUDGET - self._lanes_used)

    def _lane_acquire(self, n=1):
        """尝试占用 n 个分段名额；返回真正拿到几个（可能少于 n，也可能 0）。"""
        with self._lanes_lock:
            got = min(n, max(0, CONN_BUDGET - self._lanes_used))
            self._lanes_used += got
            return got

    def _lane_release(self, n=1):
        with self._lanes_lock:
            self._lanes_used = max(0, self._lanes_used - n)

    # ---------- v3.8.1 上传冲突检查缓存 ----------
    def _dir_entries(self, folder, refresh=False):
        """拿远端某个目录的 name→entry 表（带 TTL 缓存）。

        ⚠ 必须**就地更新**：自己刚传上去的文件要立刻写进缓存，否则同一批里
        两个同名文件会互相看不到（rename 策略会算出同一个新名字）。
        """
        now = time.time()
        with self._dir_lock:
            hit = self._dir_cache.get(folder)
            if hit and not refresh and now - hit[0] < DIR_CACHE_TTL:
                return hit[1]
        try:
            lst = self.remote.call("/api/list", {"path": folder})
            table = {e["name"]: e for e in lst.get("entries", [])}
        except Exception:
            table = {}
        with self._dir_lock:
            self._dir_cache[folder] = (now, table)
        return table

    def _dir_note(self, folder, name):
        """把自己新写入/改名的条目并进缓存。"""
        with self._dir_lock:
            hit = self._dir_cache.get(folder)
            if hit:
                hit[1][name] = {"name": name, "dir": False}

    def _dir_forget(self, folder, name):
        with self._dir_lock:
            hit = self._dir_cache.get(folder)
            if hit:
                hit[1].pop(name, None)

    def submit(self, items, direction, policy="skip", verify=False, dirs=None):
        job = Job(direction, items, policy, dirs=dirs)
        with self.lock:
            self.jobs.append(job)
        threading.Thread(target=self._run, args=(job, verify), daemon=True).start()
        return job

    def _prep_dirs(self, job):
        """v3.8.1：「下载/上传空目录」—— 先把目录树建出来，再传文件。

        为什么必须单独做：`api_walk` 只收 filenames，源目录树里的空目录在
        目标端会凭空消失，做镜像/备份时目录结构对不上。文件所在的目录由
        `os.makedirs(dirname)` 顺带建出来，所以这里只需要补"一个文件都没有"
        的那些目录。
        """
        if not job.dirs:
            return
        made = 0
        for d in job.dirs:
            try:
                if job.direction == "down":
                    os.makedirs(d, exist_ok=True)
                else:
                    self.remote.mkdir(d)
                made += 1
            except Exception as e:                                # noqa
                self.log("建目录失败 %s: %s" % (d, e))
        if made:
            self.log("已重建 %d 个目录（含空目录）" % made)

    def _run(self, job, verify):
        self._prep_dirs(job)
        q = queue.Queue()
        for i in job.items:
            q.put(i)
        ts = [threading.Thread(target=self._worker, args=(job, q, verify), daemon=True)
              for _ in range(self.workers)]
        for t in ts:
            t.start()
        for t in ts:
            t.join()
        with job.lock:
            job.state = "stopped" if job.stop.is_set() else "done"
            job.speed = job.done_bytes / max(0.001, time.time() - job.started)

    def _worker(self, job, q, verify):
        while not job.stop.is_set():
            try:
                it = q.get_nowait()
            except queue.Empty:
                return
            try:
                if job.direction == "down":
                    self._down(job, it, verify)
                else:
                    self._up(job, it, verify)
            except _Aborted as e:
                # v3.8.2：请求体中途放弃（停止 / 源文件变了）。
                # 必须显式接住 —— `_Aborted` 继承 BaseException 是为了穿透
                # 连接池和 urllib 的 `except Exception`，不让它白重发几遍。
                self._rollback(job, it)
                if job.stop.is_set():
                    with job.lock:
                        it["status"] = "stopped"
                else:
                    with job.lock:
                        it["status"] = "failed"
                        it["err"] = str(e) or "已中止"
                        job.failed += 1
                    self.log("中止 %s: %s" % (it.get("rel"), e))
                    continue
                return
            except Exception as e:  # noqa
                # 失败时把该文件已经统计过的字节退回去，避免进度虚高
                self._rollback(job, it)
                with job.lock:
                    it["status"] = "failed"
                    it["err"] = str(e)
                    job.failed += 1
                self.log("失败 %s: %s" % (it.get("rel"), e))

    # ---------- 进度记账 ----------
    def _account(self, job, it, value):
        """把当前 item 的进度推进到 value，并按【差值】累加到 job.done_bytes。

        增量记账而不是 "+= len(chunk)"，是为了让"断点续传"和"重试"两条路径
        都不会把同一段字节重复统计（这是最容易悄悄算错的地方）。
        """
        with job.lock:
            old = int(it.get("done") or 0)
            if value == old:
                return
            it["done"] = value
            job.done_bytes += value - old

    def _rollback(self, job, it):
        with job.lock:
            old = int(it.get("done") or 0)
            if old:
                job.done_bytes -= old
            it["done"] = 0

    # ---------- 下载 ----------
    def _down(self, job, it, verify):
        target = it["target"]
        os.makedirs(os.path.dirname(target) or ".", exist_ok=True)
        if not self._conflict(job, it, target, it.get("mtime")):
            return
        # 冲突策略可能改写了 target，之后一律以 it["target"] 为准
        target = it["target"]
        size = int(it.get("size") or 0)
        mtime = it.get("mtime")
        partial = target + PART
        try:
            offset = os.path.getsize(partial) if os.path.isfile(partial) else 0
        except OSError:
            offset = 0
        if offset:
            # v3.8.1 续传元数据校验（比"只比大小"严）：
            # 远端那个文件如果被换成了**更大的、内容完全不同的**文件，本地
            # 残件仍然是"另一个文件的合法前缀" —— 拼起来长度对得上、内容却是
            # 坏的，属于静默数据损坏。所以续传前必须确认残件是**同一个源**的。
            if not check_part_meta(partial, size, mtime):
                drop_part(partial)
                offset = 0
                self.log("续传校验未通过（远端文件已变），重新下载: %s"
                         % it.get("rel", ""))
            elif size and offset > size:
                drop_part(partial)       # part 比源还大 → 文件变了，重下
                offset = 0
        if not (size and offset == size):
            self._fetch(job, it, partial, offset, size)
        if job.stop.is_set() and it.get("status") == "running":
            with job.lock:
                it["status"] = "stopped"
            return
        os.replace(partial, target)
        try:
            os.remove(_part_meta_path(partial))
        except OSError:
            pass
        if it.get("mtime"):
            try:
                os.utime(target, (it["mtime"], it["mtime"]))
            except OSError:
                pass
        if verify:
            r = self.remote.call("/api/hash", {"path": it["src"]}, timeout=7200)
            if r.get("md5") != md5_file(target):
                self._rollback(job, it)
                with job.lock:
                    it["status"] = "failed"
                    it["err"] = "MD5 不一致"
                    job.failed += 1
                try:
                    os.remove(target)
                except OSError:
                    pass
                return
            it["md5"] = r.get("md5")
        with job.lock:
            it["status"] = "done"
            job.done_files += 1
        if size:
            self._account(job, it, size)      # 收尾对齐，防止末尾漏计

    def _lanes_for(self, job, it, offset, size):
        """这个文件该用几路并行。返回 1 = 走原来的单流路径。"""
        if offset:
            return 1                  # 续传一律单流：分段 + 续传语义会打架
        if getattr(self.remote, "no_range", False):
            return 1                  # 上一次已经证明对端不认 Range
        if not size or size < STRIPE_MIN:
            return 1                  # 小文件不值得为分段付建连开销
        try:
            n = int(getattr(self, "lanes", STRIPE_LANES))
        except Exception:
            return 1
        n = max(1, min(STRIPE_MAX_LANES, n))
        # v3.8.1：全局闸门 —— 别的文件已经占满分段名额时，这个文件退成单流，
        # 而不是把连接数堆到 workers×lanes（最坏 64 条）互相挤。
        free = self._lanes_free()
        if free < 2:
            return 1
        return min(n, free)

    def _fetch_lanes(self, job, it, partial, size, lanes):
        """多连接并行分段下载（v3.8.0 路径优化）。

        为什么有效：链路对**单条 TCP 流**的限制是"拥塞窗口 / 往返时延"，
        丢包一来窗口还会塌。N 条独立连接各有各的窗口与重传队列，等于把
        在途字节数叠了 N 倍 —— 这正是所有下载加速器的做法，也是
        「反向隧道只有几百 KB/s、直连十几 MB/s」时唯一还能榨出来的空间。

        实现要点：
        * 先把 partial **预分配**到整长，各路 open(partial,"r+b") 后
          seek 到自己的段首顺序写；段与段不重叠，各写各的，无需锁盘。
        * 任何一路出错就置 abort，其余各路立刻收手；然后**把 partial 截断到
          "仍然有效的最长前缀"**，这样断点续传依然是对的（下一次从
          offset=前缀 接着单流下），不会留下"中间有洞但长度为整长"的假完整文件。
        * 对端不按 Range 返回 → 抛 _NoRange，交给 _fetch 退回单流。
        """
        step = (size + lanes - 1) // lanes
        ranges = []
        for i in range(lanes):
            s = i * step
            e = min(size - 1, s + step - 1)
            if s > e:
                break
            ranges.append((s, e))
        if len(ranges) < 2:
            raise _NoRange()          # 兜底：切不出两段就别分段
        # v3.8.1：占全局名额。拿不到 2 路就老实退单流（不报错、不阻塞）。
        got = self._lane_acquire(len(ranges))
        if got < 2:
            self._lane_release(got)
            raise _Busy()
        if got < len(ranges):
            ranges = ranges[:got]
            lanes = got
        try:
            return self._fetch_lanes_inner(job, it, partial, size, ranges)
        finally:
            self._lane_release(len(ranges))

    def _fetch_lanes_inner(self, job, it, partial, size, ranges):
        with open(partial, "wb") as out:
            out.truncate(size)        # 预分配（稀疏，不真写盘）

        done = [0] * len(ranges)
        lock = threading.Lock()
        abort = threading.Event()
        errs = []
        win = {"t0": time.time(), "b0": 0}

        def report():
            # 注意：**持 lock 调 _account** —— 否则两路可能的"先算后写"顺序
            # 会颠倒（A 算 100、B 算 200、B 先提交、A 再提交），进度会来回跳。
            with lock:
                total = sum(done)
                self._account(job, it, total)
                now = time.time()
                if now - win["t0"] >= 0.5:
                    with job.lock:
                        job.speed = (total - win["b0"]) / (now - win["t0"])
                    win["t0"], win["b0"] = now, total

        def lane(idx, start, end):
            h = {}
            if self.remote.token:
                h["X-Token"] = self.remote.token
            h["Range"] = "bytes=%d-%d" % (start, end)
            url = self.remote.url("/api/download", {"path": it["src"]})
            try:
                resp = self.remote._open(
                    urllib.request.Request(url, headers=h), 60)
            except urllib.error.HTTPError as e:
                raise RuntimeError("HTTP %s" % e.code)
            try:
                if getattr(resp, "status", 200) != 206:
                    raise _NoRange()
                off = start
                with open(partial, "r+b") as f:
                    while off <= end and not abort.is_set() \
                            and not job.stop.is_set():
                        b = resp.read(min(CHUNK, end - off + 1))
                        if not b:
                            break
                        f.seek(off)
                        f.write(b)
                        off += len(b)
                        with lock:
                            done[idx] = off - start
                        report()
                if off <= end and not abort.is_set() and not job.stop.is_set():
                    raise RuntimeError("分段未取满 %d-%d" % (start, end))
            finally:
                try:
                    resp.close()
                except Exception:
                    pass

        def run(idx, start, end):
            try:
                lane(idx, start, end)
            except BaseException as e:      # noqa: 统一转成 abort + 记录
                errs.append(e)
                abort.set()

        ths = [threading.Thread(target=run, args=(i, s, e), daemon=True)
               for i, (s, e) in enumerate(ranges)]
        for t in ths:
            t.start()
        for t in ths:
            t.join()

        def valid_prefix():
            """仍然有效的最长连续前缀（用于截断，保住断点续传）。"""
            with lock:
                snap = list(done)
            p = 0
            for i, (s, e) in enumerate(ranges):
                if snap[i] >= (e - s + 1):
                    p = e + 1
                else:
                    p = s + snap[i]
                    break
            return max(0, min(p, size))

        hit_stop = job.stop.is_set()
        if errs or hit_stop:
            pre = valid_prefix()
            try:
                with open(partial, "r+b") as f:
                    f.truncate(pre)
            except OSError:
                pass
            self._account(job, it, pre)
            if hit_stop and not errs:
                return                 # 用户点了停止：保留可续传的前缀
            raise errs[0] if errs else RuntimeError("下载中断")
        with lock:
            total = sum(done)
        if total != size:
            raise RuntimeError("分段不完整 %d/%d" % (total, size))
        self._account(job, it, size)

    def _fetch(self, job, it, partial, offset, size):
        """把远端文件写进 partial。offset>0 时走 Range 续传。

        v3.8.0：大文件（≥ STRIPE_MIN）在 offset==0 时先尝试**多连接并行
        分段**（_fetch_lanes）；不支持 Range 或分段失败时**自动退回**下面
        这条单流路径，行为与旧版完全一致（断点续传、错误文案都不变）。
        """
        lanes = self._lanes_for(job, it, offset, size)
        if not offset:
            # 从头下：先落一份"这次源文件是谁"的元数据，供下次续传核对。
            write_part_meta(partial, size, it.get("mtime"))
        if lanes > 1:
            try:
                self._fetch_lanes(job, it, partial, size, lanes)
                return
            except _NoRange:
                # 对端不认 Range（旧版发送端）→ 记下来，后续文件别再试。
                try:
                    self.remote.no_range = True
                except Exception:
                    pass
                # 分段已经动过 partial（被预分配到整长），必须清干净重来
                try:
                    os.remove(partial)
                except OSError:
                    pass
                self._rollback(job, it)
                self.log("发送端不支持分段下载，已切回单流：%s"
                         % it.get("rel", ""))
            except _Busy:
                # v3.8.1：分段名额被别的文件占满 —— 安静退单流，不打扰用户。
                pass
            except Exception:
                raise                  # 真错误（链路断开等）照旧抛给上层

        h = {}
        if self.remote.token:
            h["X-Token"] = self.remote.token
        if offset:
            h["Range"] = "bytes=%d-" % offset
        url = self.remote.url("/api/download", {"path": it["src"]})
        resp = None
        while True:
            try:
                resp = self.remote._open(urllib.request.Request(url, headers=h), 60)
            except urllib.error.HTTPError as e:
                if e.code == 416 and offset:
                    return                    # 服务端认为已经取完
                raise RuntimeError("HTTP %s" % e.code)
            if offset and getattr(resp, "status", 200) != 206:
                # 发送端没按 Range 返回 → 不支持续传，删掉残留从头下
                try:
                    resp.close()
                except Exception:
                    pass
                offset = 0
                h.pop("Range", None)
                self._account(job, it, 0)
                try:
                    os.remove(partial)
                except OSError:
                    pass
                continue
            break

        downloaded = offset
        self._account(job, it, downloaded)
        t0, b0 = time.time(), downloaded
        try:
            with open(partial, "ab" if offset else "wb") as out:
                while True:
                    if job.stop.is_set():
                        return
                    b = resp.read(CHUNK)
                    if not b:
                        break
                    out.write(b)
                    downloaded += len(b)
                    self._account(job, it, downloaded)
                    now = time.time()
                    if now - t0 >= 0.5:
                        with job.lock:
                            job.speed = (downloaded - b0) / (now - t0)
                        t0, b0 = now, downloaded
        finally:
            try:
                resp.close()
            except Exception:
                pass
        if size and downloaded != size:
            raise RuntimeError("大小不一致 %d/%d" % (downloaded, size))

    # ---------- 上传 ----------
    def _up(self, job, it, verify):
        src = it["src"]
        try:
            size = os.path.getsize(src)
        except OSError as e:
            raise RuntimeError("读不到源文件: %s" % e)
        # v3.8.2：传之前先体检。被独占占用的文件在这里就报出**人能看懂**的原因，
        # 而不是让它跑到一半和对面互等（见 UPLOAD_IDLE_TIMEOUT 的说明）。
        why = file_busy_reason(src)
        if why:
            raise RuntimeError(why)
        try:
            st0 = os.stat(src)
        except OSError:
            st0 = None
        name = it["name"]
        # 冲突策略（v3.8.1：走目录缓存，不再每个文件问一次 /api/list）
        # 为什么这层缓存这么关键：旧实现每个文件一次 /api/list —— 1 万个小
        # 文件就是 1 万次往返，经隧道 ≈ 400 秒纯等待；而下载侧判冲突用的是
        # 本地 os.path.exists、一次往返都不用。这就是"上传比下载慢一个数量级"
        # 的根因。缓存 20 秒，并且自己刚写进去的名字就地登记。
        if job.policy != "overwrite":
            exist = self._dir_entries(it["dir"])
            e = exist.get(name)
            if e:
                if job.policy == "skip":
                    with job.lock:
                        it["status"] = "skipped"
                        job.skipped += 1
                        job.skipped_bytes += size
                    return
                if job.policy == "rename":
                    base, ext = os.path.splitext(name)
                    i = 1
                    while ("%s (%d)%s" % (base, i, ext)) in exist:
                        i += 1
                    name = "%s (%d)%s" % (base, i, ext)
                    it["name"] = name
                    it["target"] = os.path.join(it["dir"], name)
                    it["rel"] = name
        self._send(job, it, src, size, name)
        self._dir_note(it["dir"], name)
        # v3.8.2：传完再核一次源文件有没有在传输途中被改写。
        # 为什么必须核：写进去的是"一半旧 + 一半新"的混合体 —— 长度可能对得
        # 上、内容却是坏的，属于**静默数据损坏**；而对象拿到的是 200 OK，
        # 双方都以为成功了。宁可明确报失败，也不要留一个不可信的副本。
        if st0 is not None:
            try:
                st1 = os.stat(src)
                if (int(st1.st_size) != int(st0.st_size)
                        or abs(st1.st_mtime - st0.st_mtime) > 0.001):
                    self._rollback(job, it)
                    with job.lock:
                        it["status"] = "failed"
                        it["err"] = ("源文件在传输过程中被修改"
                                     "（大小或修改时间变了）")
                        job.failed += 1
                    self.log("失败 %s：源文件在传输过程中被改写 —— "
                             "对方那份可能不完整，请重新上传。"
                             % it.get("rel"))
                    return
            except OSError:
                pass
        if verify:
            r = self.remote.call("/api/hash", {"path": it["target"]}, timeout=7200)
            if r.get("md5") != md5_file(src):
                self._rollback(job, it)
                with job.lock:
                    it["status"] = "failed"
                    it["err"] = "MD5 不一致"
                    job.failed += 1
                return
        with job.lock:
            it["status"] = "done"
            job.done_files += 1
        self._account(job, it, size)

    def _send(self, job, it, src, size, name):
        """上传一个文件（v3.8.1：**支持断点续传**）。

        旧实现每次上传都从第 0 字节开始，中断一次就得整份重传 —— 几百 MB
        的文件在窄链路上断一次就是几十分钟白费。
        现在先问一次 `/api/upload_stat`：远端那份临时残件有多大、是不是
        **同一个源**（比 size + mtime 元数据）。对得上就从那个偏移接着发。
        对端是旧版本时该接口 404 → 自动退回从头传，行为与之前完全一致。
        """
        try:
            src_mtime = os.path.getmtime(src)
        except OSError:
            src_mtime = 0.0
        offset = 0
        try:
            st = self.remote.upload_stat(it["dir"], name)
            part = int(st.get("part") or 0)
            if 0 < part <= size:
                same = (int(st.get("part_size") or -1) == int(size))
                if same and src_mtime:
                    try:
                        same = abs(float(st.get("part_mtime") or 0)
                                   - src_mtime) <= 1.0
                    except (TypeError, ValueError):
                        same = False
                if same:
                    offset = part
                    self.log("续传上传: %s（已完成 %s / %s）"
                             % (name, human(offset), human(size)))
        except Exception:
            offset = 0                   # 对端旧版 / 探测失败 → 老实从头传
        try:
            self._send_once(job, it, src, size, name, offset)
            return
        except Exception:
            if not offset:
                raise
            # 残件可能已经被对端清掉了（对方重启/换了目录）→ 去掉偏移重来一次。
            self.log("续传失败，改为从头上传: %s" % name)
            self._rollback(job, it)
            self._send_once(job, it, src, size, name, 0)

    def _send_once(self, job, it, src, size, name, offset=0):
        h = {"Content-Type": "application/octet-stream",
             "Content-Length": str(max(0, size - offset))}
        # v3.8.1 续传三件套：完整长度 / 本次起点 / 源文件的修改时间。
        # 老发送端不认识这三个头 → 忽略之，Content-Length 就是它要收的全部，
        # 行为与旧版一致（向下兼容）。
        h["X-File-Size"] = str(size)
        h["X-Offset"] = str(offset)
        h["X-File-Mtime"] = "%.0f" % (it.get("mtime") or 0)
        if self.remote.token:
            h["X-Token"] = self.remote.token

        engine = self

        class _Progress(object):
            """伪装成文件对象，让发送端边读边上报进度。

            v3.8.2 的关键改动：**严格按声明的长度交付**。

            旧实现只是把 `f.read(n)` 原样交出去。于是当源文件在上传途中被
            改写 / 截断（被别的程序写入、日志轮转、自己拷自己）时，实际发出去的
            字节**少于** Content-Length —— 服务端会一直等剩下的字节（它的
            `rfile.read` 是阻塞且无超时的），客户端则在等响应：两边互等，
            这个任务就**永远完不成**（要熬到 7200 秒的整体超时才报错）。
            用户原话：「显示一直上传 且无法完成任务 需要优化…避免永远无法完成」。

            现在三条约束：
              · 最多只交付 `remain` 个字节 —— 文件在传的过程中**变大**也不会
                多发（多发会让服务端把多余的字节当成下一个请求，污染 keep-alive）；
              · 还没凑够就 EOF（文件被截断）→ **立刻抛 `_Aborted`**，请求体
                半途断开，服务端当场就能判定"不完整"并回 500，不再互等；
              · 每读一块检查一次 `job.stop` → 按停止键能在一个块内真正停下
                （旧实现只是不再记账，socket 上的字节还在继续发）。
            """

            def __init__(self, f, job, it, base, total):
                self.f, self.job, self.it = f, job, it
                self.sent = base
                self.remain = max(0, int(total) - int(base))
                self.t0, self.b0 = time.time(), base
                engine._account(job, it, base)

            def read(self, n=-1):
                if self.job.stop.is_set():
                    raise _Aborted("已按停止")
                if self.remain <= 0:
                    return b""
                if n is None or n < 0 or n > self.remain:
                    n = self.remain
                b = self.f.read(n)
                if not b:
                    # 只可能发生在源文件被截断/被替换：声明要发 N 个字节，
                    # 实际读到 EOF。必须当场断链，绝不能"就这样发完"。
                    raise _Aborted(
                        "文件在传输过程中被修改或截断（已发出 %s），已中止。\n"
                        "请关闭正在写入它的程序后再重试。"
                        % human(self.sent))
                self.remain -= len(b)
                self.sent += len(b)
                engine._account(self.job, self.it, self.sent)
                now = time.time()
                if now - self.t0 >= 0.5:
                    with self.job.lock:
                        self.job.speed = (self.sent - self.b0) / (now - self.t0)
                    self.t0, self.b0 = now, self.sent
                return b

            def __len__(self):
                return max(0, size - offset)

        url = self.remote.url("/api/upload", {"path": it["dir"], "name": name})
        with open(src, "rb") as f:
            if offset:
                f.seek(offset)
            pf = _Progress(f, job, it, offset, size)
            req = urllib.request.Request(url, data=pf, headers=h)
            # v3.8.2：超时从 7200 收到 UPLOAD_SOCK_TIMEOUT。7200 秒意味着
            # 一旦互等，用户要熬两个小时才等到报错 —— 那不是"超时"，那是"卡死"。
            try:
                with self.remote._open(req, UPLOAD_SOCK_TIMEOUT) as r:
                    json.loads(r.read().decode("utf-8"))
            except urllib.error.HTTPError as e:
                try:
                    msg = json.loads(e.read().decode("utf-8")).get("message", "")
                except Exception:
                    msg = ""
                raise RuntimeError("上传失败 HTTP %s %s" % (e.code, msg))

    # ---------- 冲突 ----------
    def _conflict(self, job, it, target, remote_mtime):
        with job.lock:
            it["status"] = "running"
        if not os.path.exists(target):
            return True
        if job.policy == "skip":
            with job.lock:
                it["status"] = "skipped"
                job.skipped += 1
                job.skipped_bytes += int(it.get("size") or 0)
            return False
        if job.policy == "newer" and remote_mtime:
            try:
                if os.path.getmtime(target) >= remote_mtime:
                    with job.lock:
                        it["status"] = "skipped"
                        job.skipped += 1
                        job.skipped_bytes += int(it.get("size") or 0)
                    return False
            except OSError:
                pass
        if job.policy == "rename":
            base, ext = os.path.splitext(target)
            i = 1
            while os.path.exists(target):
                target = "%s (%d)%s" % (base, i, ext)
                i += 1
            it["target"] = target
        return True


