class AboutWindow(object):
    """【关于】页：图标 / 版本 / 作者 / 联系方式 / 软件简介 / 简明使用说明。

    做成独立的小窗口（而不是把主界面整页换掉），这样关掉它就回到原来的操作，
    不会打断正在进行的传输。
    """

    def __init__(self, owner=None):
        self.owner = owner
        master = getattr(owner, "root", None)
        self.top = tk.Toplevel(master) if master is not None else tk.Toplevel()
        detect_ui_scale(self.top)
        setup_style(self.top)
        t = self.top
        t.title("关于 %s" % APP_NAME)
        # 1000 宽是为了让两栏各自放得下内容：右栏要摆两张 218px 的收款码
        # （含间距约 500px），左栏要摆 192px 大图标 + 几行文字
        # （两栏各半，1000/2=500 再减 padding 刚好够，故取 1000）。
        # 高 950：正文（软件简介→适用场景→运行环境→使用说明→常见问题→免责声明）
        # 实测自然排下来约 1060px（含顶部区 313px），所以要滚动才看得全 ——
        # 这是有意保留的：正文加了「适用场景」一节后，一屏已经装不下，
        # 而正文区本来就有 Scrollbar，滚动是兜底，不必硬撑到一屏。
        # ⚠ 窗口**比屏幕高**会被 Windows 回夹、rooty 变负（截图错位）——
        #   所以这个值要保持在常见屏幕可用高度（约 1040@1080p，减任务栏）以内。
        #   950 是实测上限附近，再往上 1080p 屏幕上就会顶格。
        t.geometry("%dx%d" % (px(1000), px(950)))
        t.minsize(px(820), px(520))
        t.configure(bg=C_BG)
        apply_window_icon(t)
        self._build()
        try:
            t.transient(master)
        except Exception:
            pass
        t.bind("<Escape>", lambda e: self.close())

    # ---------- 布局 ----------
    def _build(self):
        t = self.top

        # ---- 顶栏：标题 + 右侧【返回】 ----
        head = tk.Frame(t, bg=C_CARD)
        head.pack(fill=tk.X)
        bar = tk.Frame(head, bg=C_CARD)
        bar.pack(fill=tk.X, padx=16, pady=(10, 8))
        tk.Frame(bar, width=3, height=26, bg=C_ACC).pack(side=tk.LEFT, padx=(0, 9))
        tk.Label(bar, text="关于", font=("Microsoft YaHei UI", 12, "bold"),
                 bg=C_CARD, fg=C_TXT).pack(side=tk.LEFT)
        # 返回按钮放在最右侧
        self.back_btn = ttk.Button(bar, text="返回", width=8, style="Accent.TButton",
                                   command=self.close)
        self.back_btn.pack(side=tk.RIGHT)
        tk.Frame(t, height=3, bg=C_ACC).pack(fill=tk.X)

        # ---- 正文（内容比一屏长，套一个滚动区） ----
        wrap = tk.Frame(t, bg=C_BG)
        wrap.pack(fill=tk.BOTH, expand=True)
        canvas = tk.Canvas(wrap, bg=C_BG, highlightthickness=0, bd=0)
        vs = ttk.Scrollbar(wrap, orient="vertical", command=canvas.yview,
                           style="W11.Vertical.TScrollbar")
        canvas.configure(yscrollcommand=vs.set)
        canvas.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
        vs.pack(side=tk.RIGHT, fill=tk.Y)
        self.canvas = canvas

        inner = tk.Frame(canvas, bg=C_BG)
        win = canvas.create_window((0, 0), window=inner, anchor="nw")

        # ⚠ inner 的宽度用**独立的 after 节流**去设，不能放在 _fit 里直接改：
        #    _fit 本身绑在 inner 的 <Configure> 上，改 inner 宽度会再次触发
        #    <Configure> → 无限自激（实测直接把 GUI 挂死）。
        _fit_win = [0]
        _inner_fixed = [False]

        def _fit(_e=None):
            try:
                canvas.configure(scrollregion=canvas.bbox("all"))
                canvas.itemconfigure(win, width=canvas.winfo_width())
            except Exception:
                pass
            if _fit_win[0]:
                try:
                    t.after_cancel(_fit_win[0])
                except Exception:
                    pass
            _fit_win[0] = t.after(1, _apply_inner_w)

        def _apply_inner_w():
            _fit_win[0] = 0
            try:
                # ⚠⚠ 关键：canvas 的 create_window 窗口项**不参与几何传播**，
                # 所以 inner 永远不会"被告知"canvas 有多宽，它只能自己长到内容
                # 需要的宽度。于是 `card.pack(fill=tk.X)` 也没得可填 —— 卡片宽
                # 就等于内容自然宽度，两栏永远分不到"各占一半"。
                # 这里**直接给 inner 设宽度**，inner 有了确定宽度后 card 的
                # fill=tk.X 才真正生效，两栏的 minsize=HALF_W 也才有意义。
                wpx = canvas.winfo_width()
                if wpx > 1 and not _inner_fixed[0]:
                    # ⚠ `pack_propagate(False)` 关掉后 inner 的宽**和**高都由
                    #   configure 说了算。宽要钉成 canvas 宽；高必须显式补上
                    #   "内容需要的高度"，否则 inner 会塌成 1px（实测卡片整块
                    #   消失）。这里用 winfo_reqheight()，它反映的是子控件
                    #   （card）自然需要的高度。
                    inner.pack_propagate(False)
                    _inner_fixed[0] = True
                    inner.configure(width=wpx)
                if _inner_fixed[0]:
                    # ⚠ 关掉 inner 的传播后，inner.winfo_reqheight() 恒为 1
                    #   （子控件的尺寸不再往上聚合），所以要**直接读卡片的
                    #   reqheight**，再加上 card 自身的 pack 上下外边距。
                    need = 0
                    for ch in inner.winfo_children():
                        try:
                            need = max(need, ch.winfo_reqheight()
                                       + 2 * px(14))
                        except Exception:
                            pass
                    if need > 1 and abs(inner.winfo_height() - need) > 1:
                        inner.configure(height=need)
            except Exception:
                pass
            except Exception:
                pass

        inner.bind("<Configure>", _fit)
        canvas.bind("<Configure>", _fit)

        def _wheel(e):
            try:
                canvas.yview_scroll(int(-e.delta / 120), "units")
            except Exception:
                pass

        # 绑在顶层窗口上：Tk 的事件会从指针下的控件沿 bindtags 冒泡上来，
        # 所以正文里任何一个子控件上滚轮都能滚。
        t.bind("<MouseWheel>", _wheel)

        # ⚠ 卡片必须**固定宽度贴左**，不能 `pack(fill=tk.BOTH, expand=True)`。
        # 这是 v3.8.4 修掉的一个真实显示 bug：canvas 的 create_window 不参与
        # 几何传播，所以 canvas 永远不会把宽度"告诉"内层 Frame —— 内层只能
        # 自己长到内容需要的宽度（横向分栏时就是"左栏 + 右栏"的自然宽度）。
        # 实测内层会长到 ~1170px，比 canvas(~1247px 减去滚动条) 还宽出约 46px，
        # 于是 `expand=True` 把这块多出来的宽度居中：**整页内容整体左移，右侧
        # 收款码被窗口右边缘裁掉一截**。改成固定宽度贴左之后：
        #   · pack_propagate(False) 保住高度由 packer 自适应
        #   · _fit 里把卡片宽度钉成 canvas 宽 - 2×边距，两栏因此拿到确定的画布宽度
        # ⚠ 卡片用 `fill=tk.X, side=tk.TOP`（**不加 expand**）而不是
        # `fill=tk.BOTH, expand=True`。这是 v3.8.4 修掉的一个真实显示 bug：
        # canvas 的 create_window 不参与几何传播，内层 Frame 只能自己长到
        # 内容需要的宽度。实测内层会长到 ~1170px，比可视区（1247 - 滚动条）
        # 还宽约 46px，于是 `expand=True` 就把多出来的宽度居中 —— **整页内容
        # 整体左移、右栏收款码被窗口右边缘裁掉一截**。
        # 去掉 expand 后卡片固定贴左，宽度由内容（两栏）决定，右栏永远完整；
        # `fill=tk.X` 仍让卡片在"内容比可视区窄"时铺满，不会缩成一小块。
        card = tk.Frame(inner, bg=C_CARD, highlightthickness=1,
                        highlightbackground=C_LINE)
        card.pack(fill=tk.X, side=tk.TOP, padx=px(16), pady=px(10))

        # ---- 顶部信息区：左右分栏（各占一半） ----
        # 左栏（自上而下，**全部水平居中**）：大图标 / 软件名 / 版本号 / 版权 /
        #   联系作者。版式与 v3.8.2 一致（用户提供截图比对确认）。
        # 右栏（自上而下，全部居中）：【赞助支持】标题 / 描述文案 /
        #   两个二维码 / 每码下方分别标【微信】【支付宝】并按平台 logo 配色。
        #
        # v3.8.6 相对 v3.8.5 的修正（用户原话："信息太乱 且重复 logo太小"）：
        #   ① 左栏**居中**（v3.8.5 误改成左对齐）。
        #   ② 删掉"作者信息"这一层 —— 版权行 `@2026 Thomajesty` 已经是作者名，
        #      再单列一遍属于重复。用户点名"重复"就是指它。
        #   ③ 图标放大：v3.8.5 的 96px 用户嫌小 ⇒ 原图直出 192px。
        #   ④ 右栏**加回**标题 + 描述 + 码下标注（v3.8.5 把文字全删了，也错）。
        #   ⑤ 两栏等高 —— 不再让右栏"垂直居中"（那样左右视觉重心一高一低），
        #      而是把右栏撑到与左栏同高，标题顶对齐、码区垂直居中。
        #
        # ⚠ 两栏**各占一半**：`uniform` 在只给 weight 时是按**自然宽度**取最大值
        #   平分的，左栏是文字（自然宽 ~208px）右栏是图（~520px），实测得到
        #   28.6% / 71.4% —— 不是各半。真正各半必须用 `minsize` 钉死两列宽度。
        #
        # v3.8.8 定稿：两栏之间加一条**竖直分隔线**（用户："这两个模块中间画一个
        #   合理的隔线"）。做法是在 0/1 两列中间插一个**零 weight 的窄列**：
        #     col0=左栏(weight=1, uniform=half) / col1=分隔线(weight=0, 固定宽) /
        #     col2=右栏(weight=1, uniform=half)
        #   ⚠ 不能让分隔线跟两栏挤在同一列里用 padx 画 —— 那样线会随栏宽漂移。
        #   ⚠ minsize 只给 0/2 两列，分隔线列**不给 weight**，否则它会被一起撑开。
        head2 = tk.Frame(card, bg=C_CARD)
        head2.pack(fill=tk.X, pady=(px(12), px(2)))
        head2.columnconfigure(0, weight=1, uniform="half", minsize=px(HALF_W))
        head2.columnconfigure(1, weight=0)          # 分隔线列：宽度由控件定
        head2.columnconfigure(2, weight=1, uniform="half", minsize=px(HALF_W))

        # ---------- 左栏：软件信息（整体居中） ----------
        # ⚠ 两栏"高度统一"的做法：两栏容器都 `sticky="nsew"` + `rowconfigure
        #   (0, weight=1)` ⇒ 两栏**容器**被 grid 拉成同高（= 较高那栏的内容高）。
        #   再各套一层 `expand=True` 的内层 Frame 做**内容垂直居中** ⇒ 左右两
        #   坨内容的上下留白对称，顶底边视觉齐平。
        # ⚠ 早先只给左栏 `sticky="n"` 是错的：那样左栏容器停在自然高度
        #   （385），右栏被拉到行高（411），量出来"差 26px"，肉眼就是左高右低。
        left = tk.Frame(head2, bg=C_CARD)
        left.grid(row=0, column=0, sticky="nsew", padx=(px(8), px(4)))
        leftbox = tk.Frame(left, bg=C_CARD)
        leftbox.pack(expand=True)          # 在等高的左栏里把内容垂直居中

        # 图标：`pack()` 不带 anchor ⇒ 在栏内水平居中。
        # ⚠ 不能再用 LOGO_BLEED 那套左对齐补偿（那是给 anchor="w" 用的），
        #   居中之后图标自带的透明留白左右对称，不需要抵消。
        img = ui_app_icon_big()
        if img is not None:
            lb = tk.Label(leftbox, image=img, bg=C_CARD)
            lb.image = img                     # 保住引用，否则会被 GC 掉变空白
            lb.pack(pady=(px(2), 0))
        # v3.8.8 定稿：用户"左侧文案再缩小行间距"（上一版刚要求"高度大小不变"
        # 还原成 14/8/4/16，这一版又觉得疏 ⇒ 收到 8/3/2/10）。
        #   · 软件名上方 14 → 8
        #   · 版本号上方  8 → 3
        #   · 版权上方    4 → 2
        #   · 联系作者上方 16 → 10（这行是「对齐基准」，间距留太小会贴着版权
        #     显乱；10px 已比原版紧 6px，视觉上明显收拢但不粘连）
        # ⚠ 收完之后复查过：左内容 354 / 右内容 341（差 13px），两栏均衡，
        #   没有因为左栏变矮而出现"左边一柱短、右边一柱长"的失衡。
        tk.Label(leftbox, text=APP_NAME, font=("Microsoft YaHei UI", 19, "bold"),
                 bg=C_CARD, fg=C_TXT).pack(pady=(px(8), 0))
        self.version_lbl = tk.Label(leftbox, text="Version:  %s" % APP_VER,
                                    font=("Microsoft YaHei UI", 11),
                                    bg=C_CARD, fg=C_TXT2)
        self.version_lbl.pack(pady=(px(3), 0))
        self.copyright_lbl = tk.Label(leftbox, text=COPYRIGHT, font=FONT_S,
                                      bg=C_CARD, fg=C_TXT3)
        self.copyright_lbl.pack(pady=(px(2), 0))
        # 联系方式：点一下拉起系统默认邮件客户端
        self.mail_lbl = tk.Label(leftbox, text="联系作者：%s" % AUTHOR_MAIL,
                                 font=FONT_S, bg=C_CARD, fg=C_ACC, cursor="hand2")
        self.mail_lbl.pack(pady=(px(10), 0))
        self.mail_lbl.bind("<Button-1>", self.open_mail)
        self.mail_lbl.bind("<Enter>", lambda e: self.mail_lbl.config(fg=C_ACC_D))
        self.mail_lbl.bind("<Leave>", lambda e: self.mail_lbl.config(fg=C_ACC))

        # ---------- 中缝：竖直分隔线 ----------
        # `sticky="ns"` 让它**上下撑满**两栏高度（两栏被 rowconfigure 拉成同高，
        # 这列也跟着同高）—— 一条只占中间一小段的线看着很别扭。
        # 宽度 1px、颜色 C_LINE（与正文里那条横向分隔线同色，视觉语言统一）。
        # ⚠ 用 `highlightthickness=0` + `bg=C_LINE` 画实心条：Frame 的 bg 在
        #   Tk 里就是纯色填充，比 Canvas 画线省事且不会被 DPI 缩放糊掉。
        tk.Frame(head2, width=1, bg=C_LINE,
                 highlightthickness=0).grid(row=0, column=1, sticky="ns")

        # ---------- 右栏：赞助支持 ----------
        # 与左栏同款：容器 `sticky="nsew"` 被 grid 拉成同高，内部 `rightbox`
        # `expand=True` 让"标题 + 描述 + 两码"整坨在右栏里垂直居中。
        right = tk.Frame(head2, bg=C_CARD)
        right.grid(row=0, column=2, sticky="nsew", padx=(px(4), px(8)))
        head2.rowconfigure(0, weight=1)
        rightbox = tk.Frame(right, bg=C_CARD)
        rightbox.pack(expand=True)

        # v3.8.8：标题 / 描述 / 码区 三层之间的上边距同步收紧（16/8/10 → 4/3/4）。
        # 定稿再收（用户第一次："右侧上面和下面的文字再靠近二维码一点"）：
        #   标题 <-> 描述   3 → 2
        #   描述 <-> 码区   4 → 2
        #   码图 <-> 码下标注 5 → 2
        # 用户第二次仍嫌"微信 支付宝 离二维码太远" ⇒ 再压到极限：
        #   标题 <-> 描述   2 → 1
        #   描述 <-> 码区   2 → 1
        #   码图 <-> 码下标注 2 → 1（= QR_CAP_PADY，见常量处）
        # ⚠ 不能再压到 0：pack 的 pady 为 0 时两行会**紧贴**，11pt bold 的
        #   「微信」上缘会顶到二维码最下沿的黑白模块，视觉上像被切了一刀。
        #   1px 是"贴在一起但不粘连"的最小值。
        tk.Label(rightbox, text="赞助支持", font=("Microsoft YaHei UI", 13, "bold"),
                 bg=C_CARD, fg=C_TXT).pack(pady=(px(4), 0))
        self.support_desc_lbl = tk.Label(
            rightbox,
            text="本软件完全免费，没有任何功能限制，\n觉得好用的话，扫码请作者喝杯咖啡。",
            font=FONT_S, bg=C_CARD, fg=C_TXT2, justify="center")
        self.support_desc_lbl.pack(pady=(px(1), 0))

        # 码区：两码横向并排。**不再用 expand** —— 右栏已经由外层的
        # `rightbox.pack(expand=True)` 整体垂直居中，这里再加 expand 会把
        # 标题与描述往上顶，破坏居中。
        qrwrap = tk.Frame(rightbox, bg=C_CARD)
        qrwrap.pack(pady=(px(1), 0))
        self._qr_holder = qrwrap

        # 两张码各自一个"图 + 彩色标注"的小容器，居中交给 packer ⇒ 任何 DPI
        # 下标注都自动对准各自码的横向中心，不需要手工算坐标。
        # ⚠ 每张码是**独立的内嵌图**（_SUPPORT_WX_B64 / _SUPPORT_ALI_B64）。
        #   并排一张图做不到"分别标注" —— 文字要手工对齐到每码中心，DPI 一变就漂。
        self._qr_tile = None
        _tiles = []
        _caps = []
        for _b64, _txt, _color in ((_SUPPORT_WX_B64, QR_WX_TEXT, QR_WX_COLOR),
                                   (_SUPPORT_ALI_B64, QR_ALI_TEXT, QR_ALI_COLOR)):
            tile = tk.Frame(qrwrap, bg=C_CARD)
            # v3.8.8：码图外层白边由 32px 收到 9px 后，两码之间的视觉间距
            # 也随之变窄。原 6px padx 是建立在"32px 白边"之上的，白边一收
            # 就只剩 18px。这里补到 17px（合计 2*9 + 2*17 = 52px 视觉间距），
            # 让两张码之间有清晰的呼吸感，同时不撑破右栏（右栏宽 580）。
            tile.pack(side=tk.LEFT, padx=px(17))
            im = self._support_image(_b64)
            if im is not None:
                lb2 = tk.Label(tile, image=im, bg=C_CARD)
                lb2.image = im                 # 保住引用
                lb2.pack()
            else:
                # 图没建出来也要留占位 Label，否则视觉体检脚本与"右栏该有的
                # 东西在不在"这类断言都无从下手。
                lb2 = tk.Label(tile, text="", bg=C_CARD)
                lb2.pack()
            # 码下平台标注：字号 8→11 + bold（见 QR_FONT 处的说明）。
            # ⚠ 高度上要"与左侧「联系作者」齐平"：这里只负责**样式与内容**，
            #   真正的对齐交给 `_align_cap_to_mail()`（真机量完两行 rooty 再补
            #   底部留白）—— 硬编码 pady 在不同 DPI / 字体回退下必漂。
            cap = tk.Label(tile, text=_txt, font=QR_FONT, bg=C_CARD, fg=_color)
            cap.pack(pady=(px(QR_CAP_PADY), 0))
            _caps.append(cap)
            _tiles.append((lb2, _txt, _color))
        self._qr_tiles = _tiles
        self._qr_caps = _caps                  # 供对齐/体检脚本读
        if _tiles:
            self._qr_tile = _tiles[0][0]

        # ---- 两栏纵向均衡（"两侧高度统一，不要左高右低"） ----
        # 做法（不需要任何手算补白）：
        #   ① 两栏容器都 `sticky="nsew"`，`head2.rowconfigure(0, weight=1)`
        #      ⇒ grid 把两栏容器拉成**同高**（行高 = 两栏里更高的那个）。
        #   ② 每栏内容各套一层 `expand=True` 的内层 Frame（leftbox/rightbox）
        #      ⇒ 内容块在各自栏里**垂直居中**，上下留白对称。
        # 两者合起来：两栏容器等高、内容各自居中 ⇒ 视觉上顶底齐平，
        # 不会出现"左栏一柱到底、右栏缩在上半截"的不平衡。
        #
        # ⚠ 早先试过"量两栏内容高、给矮的那栏补 pady"（下面的 _equalize），
        #   那个做法只把**内容**居中，栏**容器**本身仍不等高 —— 实测
        #   `sticky="n"` 的左栏停在 385、被拉高的右栏 411，差 26px，
        #   肉眼就是"左高右低"。所以现在改由 grid 拉平容器 + expand 居中内容。
        # ⚠ `_col_content_h` 保留：真机视觉体检脚本要用它量"内容跨度"。
        self._col_content_h = AboutWindow._col_content_h

        tk.Frame(card, height=1, bg=C_LINE).pack(
            fill=tk.X, padx=px(26), pady=(px(8), px(6)))

        # ---- 正文区：软件简介 / 使用说明 ----
        body = tk.Frame(card, bg=C_CARD)
        body.pack(fill=tk.BOTH, expand=True, padx=px(26), pady=(0, px(10)))

        def section(title):
            # v3.8.8：章节标题与上一段的间距 10 → 6、与下文的间距 5 → 3。
            # 用户反馈「段落图片 文字的高度间隙还是大」，正文里有 6 个章节标题，
            # 每个省 6px，合计省下 36px。
            tk.Label(body, text=title, font=FONT_B, bg=C_CARD, fg=C_TXT,
                     anchor="w").pack(fill=tk.X, pady=(px(4), px(2)))

        def para(text, color=C_TXT2, font=FONT):
            # v3.8.8：段落下边距 4 → 2（段落之间还有 section 的 6px 上边距，
            # 两者叠加已足够区分段落，不需要双份留白）。
            lb = tk.Label(body, text=text, font=font, bg=C_CARD, fg=color,
                          anchor="w", justify="left")
            lb.pack(fill=tk.X, pady=(0, px(1)))
            return lb

        section("软件简介")
        self.intro_lbl = para(ABOUT_INTRO)
        section("适用场景")
        self.scene_lbl = para(ABOUT_SCENES, color=C_TXT3, font=FONT_S)
        # ---------- 版本与更新（v3.9.2 新增） ----------
        # 这一节只有一行小字 + 一个按钮，形态和其他"纯文字"小节不同，
        # 所以单独搭，不用 para()。
        # ⚠ Label 与 Button 并排时高度要对齐：实测 About.TButton 的 req 高
        #   是 36px，而 FONT_S 的 Label 只有 25px，直接并排会一高一矮。
        #   用固定 height + 垂直居中的 anchor 把两者拉平（实测中心差 0px）。
        # ⚠ anchor/justify 用**字符串字面量**而不是 tk.W / tk.LEFT ——
        #   无头自检环境的 Tk 是桩，tkinter 模块上根本没有这些常量，
        #   写成 tk.W 会让整个 selftest 在建窗那一步崩掉。
        section("版本与更新")
        # ⚠⚠ 父容器必须是 **body**（正文滚动容器），不是 card。
        #   card 是顶部 logo/二维码那个容器，写成 card 的话这一行会被塞到
        #   顶部区里、body 里只剩一个孤零零的小节标题 —— 表现是
        #   「版本与更新」标题在，下面直接就是「运行环境」，内容凭空消失。
        upbox = tk.Frame(body, bg=C_CARD)
        upbox.pack(fill=tk.X, pady=(0, px(1)))
        self.upd_lbl = tk.Label(
            upbox, text="当前版本 %s　·　可点右侧按钮检查有没有新版本" % APP_VER,
            bg=C_CARD, fg=C_TXT3, font=FONT_S, anchor="w", justify="left")
        # ⚠ 不要写死 height=2：窗口被缩窄时这一行会折成两行，写死行数会把
        #   第二行裁掉。改成自然高度 + fill=tk.Y —— Tk 的 Label 默认
        #   anchor 就是 center（配合 anchor="w" 只影响水平方向），
        #   垂直方向自动居中，于是无论 upbox 多高都与右侧按钮中心齐平。
        self.upd_lbl.pack(side=tk.LEFT, fill=tk.Y, pady=(0, px(1)))
        self.upd_btn = ttk.Button(upbox, text="检查更新",
                                  style="About.TButton",
                                  command=self.check_update_manual)
        self.upd_btn.pack(side=tk.RIGHT, padx=(px(8), 0), pady=(0, px(1)))
        section("运行环境")
        self.sys_lbl = para(ABOUT_SYS)
        # 光写"支持到 Win7"还不够 —— 用户真正想确认的是"我这台到底行不行"，
        # 所以直接把当前机器的判断结果摆在下面，一眼就有答案。
        self.cur_sys_lbl = para(_os_desc(), color=C_TXT3, font=FONT_S)
        section("使用说明")
        self.steps_lbl = para(ABOUT_STEPS)
        section("常见问题")
        self.faq_lbl = para(ABOUT_FAQ)
        # 免责声明放在最后（正文最末尾），并比其它段落浅一档 —— 它是"须知"，
        # 不该抢走操作说明的注意力，但必须出现在用户真会看到的地方。
        section("免责声明")
        self.disc_lbl = para(ABOUT_DISCLAIMER, color=C_TXT3, font=FONT_S)

        # 换行宽度按窗口实际宽度算：Tk 的 wraplength 是像素，写死一个数
        # 在别的 DPI/窗口尺寸下就会折得很难看。
        def _rewrap(_e=None):
            try:
                w = max(px(320), body.winfo_width() - px(4))
                for lb in (self.intro_lbl, self.scene_lbl, self.sys_lbl,
                           self.cur_sys_lbl, self.steps_lbl, self.faq_lbl,
                           self.disc_lbl):
                    lb.configure(wraplength=w)
            except Exception:
                pass

        body.bind("<Configure>", _rewrap)
        self._rewrap = _rewrap
        t.after(60, _rewrap)

        # ---- 码下标注高度对齐「联系作者」（用户要求）----
        # 目标：右栏每张码下面的平台标注，与左栏最后的「联系作者：…」在
        # **同一条水平线上**（两行高低齐平）。
        #
        # 为什么不在 _build 里写死 pady：标注是 11pt bold、mail_lbl 是 8pt 常规，
        # 两者自然高差几个像素，且随 DPI / 字体回退而变。写死一个数在这里能
        # 对齐、到用户机器上就漂了。
        #
        # 做法：延后到窗口真正映射之后量一次（几何此时才有效），把右栏底部
        # 留白补/减掉两行 rooty 的差值，再挂 <Configure> 复算（窗口缩放后
        # 行高不变，但保险起见重算一次；节流防自激）。
        self._cap_align_win = t.after(120, self._align_cap_to_mail)
        t.bind("<Configure>", lambda e, _t=t: self._cap_align_debounce(_t), add="+")

    # ---------- 行为 ----------
    def _cap_align_debounce(self, t):
        """窗口 <Configure> 触发的对齐复算（节流 200ms，防自激）。"""
        try:
            if getattr(self, "_cap_align_win", 0):
                t.after_cancel(self._cap_align_win)
        except Exception:
            pass
        try:
            self._cap_align_win = t.after(200, self._align_cap_to_mail)
        except Exception:
            self._cap_align_win = 0

    def _align_cap_to_mail(self):
        """让右栏「码下平台标注」与左栏「联系作者」两行的垂直位置齐平。

        原理：两栏容器已经被 grid 拉成等高；两栏内容块各 `expand=True` 在栏内
        垂直居中。两栏内容块自然高不同 ⇒ 各自最后一行的屏幕 y 对不上。用两行
        Label 的 `winfo_rooty()`（屏幕绝对坐标）之差，**双向**调整两侧内容块的
        顶部留白，把两行拉到同一水平线上。

        ⚠⚠ 为什么必须**双向**（v3.8.8 修正）：
          v3.8.7 只往"下推右栏"一个方向调（`off = max(0, ...)`）。当时左栏
          内容比右栏高，标注确实偏上，单向够用。但 v3.8.8 把 logo 从 256 缩到
          128 之后，**左栏反而变矮了**（内容 293 vs 右栏 399），标注跑到
          「联系作者」**下方** 50px —— 单向逻辑差值算成负数、被钳到 0，
          对齐彻底失效（实测差 50px）。
          现在改成：谁在上面就把谁往下推，两边都补顶部留白，天然支持任意高低。

        ⚠⚠ 为什么用**迭代**而不是一次算准：
          `expand=True` 会让 Tk 把"栏高 − 内容高"的剩余空间**平分**到内容块
          上下。补 `off` 顶部留白后，内容块**下移的不是 off，而是 off 的一半**。
          一次算准要先知道这个比例，而比例随内容高变化 —— 与其推导，不如迭代：
          每轮各补 `当前差值`（净位移约为差值），通常 2 轮命中 ≤1px。上限 6 轮防死循环。

        ⚠ 必须在窗口**真正映射到屏幕**之后量：`withdraw()` 状态下 `winfo_rooty`
        和 `winfo_height` 都不可信（宽恒 1、映射标志恒 0）。
        """
        try:
            mail = getattr(self, "mail_lbl", None)
            caps = getattr(self, "_qr_caps", None)
            if not caps or mail is None:
                return
            # ⚠⚠ 标注到 rightbox 是**三层**：cap → tile → qrwrap → rightbox。
            #   v3.8.8 曾只走两层，拿到的是 qrwrap（高 305）而非
            #   rightbox（高 399）—— pack_configure 调的是错位的控件，
            #   对齐静默失效。
            rightbox = caps[0].master.master.master   # tile → qrwrap → rightbox
            leftbox = mail.master                  # 联系作者所在的内容块
            if not mail.winfo_ismapped():
                return
            # ⚠ 刷几何要用**窗口**的 update_idletasks，AboutWindow 自身没有这个
            #   方法（踩过一次 AttributeError，导致整个对齐静默失效）。
            self.top.update_idletasks()
            off_r = getattr(self, "_cap_align_off", 0)      # 右栏内容块顶部留白
            off_l = getattr(self, "_mail_align_off", 0)     # 左栏内容块顶部留白
            for _ in range(8):
                cap_y = max(c.winfo_rooty() for c in caps)
                mail_y = mail.winfo_rooty()
                diff = cap_y - mail_y              # >0 ⇒ 标注偏下，要把左栏（mail）往下推
                if abs(diff) <= 1:
                    break
                # `expand=True` 会把"栏高 − 内容高"的剩余空间**平分**到内容块
                # 上下 ⇒ 补 `d` 顶部留白，内容块**净下移只有 d/2**。
                # 所以想要净位移 diff，得补 **2*diff**。
                # 策略：**谁在上面就把谁往下推**。因为只有"内容比栏短"
                # 的那一栏才真的有 expand 空间可分配；另一栏已经顶满，
                # 给它加顶部留白只会把内容顶出去（无效或反效）。
                if diff > 0:
                    off_l = min(px(300), off_l + diff * 2)   # 标注偏下 ⇒ 左栏往下
                else:
                    off_r = min(px(300), off_r - diff * 2)   # 标注偏上 ⇒ 右栏往下
                leftbox.pack_configure(pady=(off_l, 0))
                rightbox.pack_configure(pady=(off_r, 0))
                self.top.update_idletasks()
            self._cap_align_off = off_r
            self._mail_align_off = off_l
        except Exception as e:  # noqa
            try:
                _safe_err("码下标注对齐失败: %r\n" % (e,))
            except Exception:
                pass
        except Exception as e:  # noqa
            try:
                _safe_err("码下标注对齐失败: %r\n" % (e,))
            except Exception:
                pass

    @staticmethod
    def _col_content_h(col):
        """一栏里"子控件纵向跨度"（不是栏容器高度）—— 用来做两栏等高。

        ⚠ 不能直接用 `col.winfo_height()`：grid 把同一行的两栏拉成等高，
        栏容器高度**永远相等**，量它等于没量。真正要看的是内容本身占了多高。
        """
        ys = []
        for ch in col.winfo_children():
            try:
                ch.update_idletasks()
                ys.append(ch.winfo_y())
                ys.append(ch.winfo_y() + ch.winfo_height())
            except Exception:
                pass
        if not ys:
            return 0
        return max(ys) - min(ys)

    def _support_image(self, b64=None):
        """关于页右栏的收款码图（内嵌 base64，不读外部文件）。

        为什么内嵌而不是读 dist/support-qrcodes.png：onefile 打包后磁盘上
        并没有那个文件，任何"运行时读图"的写法在用户机器上都会失败。
        PhotoImage 直接吃 data= 的 base64，单文件也能用。

        v3.8.6 起**两张码各自一张图**：`b64` 传 `_SUPPORT_WX_B64` / `_SUPPORT_ALI_B64`
        其一（不传则默认微信码，兼容旧调用）。拆两张是为了在每张码下面分别
        标注平台名并按平台 logo 配色（并排一张图做不到"分别"）。

        内嵌资源是 @3x（654×654）：`subsample(3,3)` 得 **218×218 @1x**，
        其中码净边长 200px、四周各 9px 白边（v3.8.8 前是 32px 白边，
        已收窄 —— 那圈白边会让"码下标注"看着离码很远）。
        ⚠ 这里**故意不缩得更小**：二维码被缩放采样后模块边界会引入灰度，
        200px 是实测的稳妥值（zxing 在 160px 仍能解码，但留足余量防真机扫码失败）；
        再小虽然图片看着"更精致"，但用户真拿手机扫可能失败 —— 那是致命问题。
        ⚠ Tk 只支持整数倍缩放，所以倍数是写死的 3，改资源尺寸必须同步改这里。
        """
        if tk is None:
            return None
        _sync_icon_root()

        if b64 is None:
            b64 = _SUPPORT_WX_B64
        key = "support/%d" % (id(b64) if isinstance(b64, str) else hash(b64[:64]))
        base = _ICON_CACHE.get(key)
        if base is None or not _icon_alive(base):
            try:
                base = _new_image(b64)
                _ICON_CACHE[key] = base
            except Exception as e:  # noqa
                _safe_err("收款码图加载失败: %r\n" % (e,))
                _ICON_CACHE[key] = None
                return None
        if base is None:
            return None

        kkey = key + "/3@%d" % id(base)
        hit2 = _ICON_CACHE.get(kkey)
        if hit2 is not None and _icon_alive(hit2):
            return hit2
        try:
            small = base.subsample(3, 3)
        except Exception:
            small = base
        _ICON_CACHE[kkey] = small
        return small

    def open_mail(self, _ev=None):
        """点邮箱 → 拉起默认邮件客户端。"""
        url = "mailto:%s" % AUTHOR_MAIL
        try:
            os.startfile(url)                    # Windows
            return
        except Exception:
            pass
        try:
            import webbrowser
            webbrowser.open(url)
        except Exception as e:  # noqa
            _safe_err("打开邮件客户端失败: %r\n" % (e,))

    def close(self):
        try:
            self.top.destroy()
        except Exception:
            pass

    # ---------- 在线更新（v3.9.2） ----------
    def check_update_manual(self, _ev=None):
        """【关于】页那个「检查更新」按钮。

        与启动时的静默检查只有一处不同：**结果一定给用户看**
        （有更新 / 已是最新 / 查不到），因为是他主动点的。
        """
        self.upd_btn.configure(state=tk.DISABLED, text="正在检查…")
        self.top.update_idletasks()
        # 主线程同步查：点按钮本来就是个会等一下的动作，8 秒超时在
        # 按钮的禁用态里看得见，比"点了没反应"好。**不放后台线程**，
        # 因为 AboutWindow 没有 post()，回调回主线程还得再绕一圈。
        res = _update_state(manual=True)
        try:
            self.upd_btn.configure(state=tk.NORMAL, text="检查更新")
        except Exception:
            pass
        if res is None:
            return                                # 关窗了
        if res.get("state") == "unknown":
            self._say_update(
                "暂时查不到",
                "连不上 GitHub 的更新服务器。\n\n"
                "可能这台机器所在的网络访问不了 GitHub（公司内网、或没开代理）。\n"
                "这不影响本机任何功能，局域网内传文件照常用。\n\n"
                "过一会儿再点一次，或者直接到项目页手动下载：\n%s"
                % _update_page_url())
            return
        self._show_update(res["info"])

    def _say_update(self, title, body):
        """纯文字提示（无新版本、查不到失败时用）。"""
        try:
            if tk is None:
                return
            self.top.bell()
            messagebox.showinfo(title, body, parent=self.top)
        except Exception:
            pass

    def _show_update(self, info):
        """有新版本：把「版本号 + 本次改了什么 + 去哪下」摆出来。"""
        ver = info.get("ver", "")
        size = info.get("size") or 0
        mb = "%.1f MB" % (size / 1048576.0) if size else ""
        head = "发现新版本  %s  （当前 %s）" % (ver, APP_VER)
        if mb:
            head += "\n安装包 %s" % mb
        notes = info.get("notes") or ""
        body = head
        if notes:
            body += "\n\n本版更新\n" + notes
        body += "\n\n点【是】打开项目页面，在浏览器里下载安装包；点【否】以后再说。"
        try:
            if tk is None:
                return
            self.top.bell()
            # ⚠ askyesno 用的是 Tk 固定的「是 / 否」两个按钮，**不支持自定义文字**
            #（传 yesno=... 会被静默忽略），所以按钮含义写进正文里。
            ok = messagebox.askyesno("发现新版本", body, parent=self.top,
                                     default="yes")
        except Exception:
            ok = False
        if ok:
            self._open_url(info.get("url") or _update_page_url())
        # 无论点了是/否，都记下"这个版本我知道了"——
        # 点了【是】已经去下载了，再弹一次纯烦人。
        try:
            mark_update_seen(ver)
        except Exception:
            pass

    def _open_url(self, url):
        if not url:
            return
        try:
            os.startfile(url)                       # Windows
            return
        except Exception:
            pass
        try:
            import webbrowser
            webbrowser.open(url)
        except Exception as e:  # noqa
            _safe_err("打开浏览器失败: %r\n" % (e,))


def open_about(owner=None):
    """打开【关于】页；已经开着就把它提到最前面，不重复弹窗。"""
    if tk is None:
        return None
    old = getattr(owner, "_about", None) if owner is not None else None
    try:
        alive = old is not None and old.top.winfo_exists()
    except Exception:
        alive = False
    if alive:
        try:
            old.top.deiconify()
            old.top.lift()
            old.top.focus_set()
        except Exception:
            pass
        return old
    win = AboutWindow(owner)
    if owner is not None:
        try:
            owner._about = win
        except Exception:
            pass
    return win


_ACTIVE_WIN = [None]          # 当前主窗口实例（SenderWindow / ReceiverWindow）
_SWITCH_ARGS = [None]         # 启动参数，切换角色时要复用


def _fit_conn_text(text, avail, font):
    """把"● 已连接 <主机名> · HTTPS"截到 avail 像素以内。

    思路：保留"● 已连接 "前缀和" · HTTPS"后缀（它们是状态与协议，不能丢），
    只缩中间的主机名 —— 从长到短试，第一个放得下的就用。
    一个字符都放不下时退回前缀本身，至少还能看出"已连接"。

    为什么不用写死的字数：列宽会随窗口尺寸、DPI 缩放、字体的实际度量变化，
    写死 10 个字符在 1120px 窗口下够用，加了【⇄ 切换】按钮后就溢出了。
    这里现场量，任何环境下都自洽。
    """
    try:
        if not avail or avail <= 0:
            return text
        if font.measure(text) <= avail:
            return text
        head, tail = "● 已连接 ", ""
        body = text
        if text.startswith(head):
            body = text[len(head):]
        if " · " in body:
            i = body.rfind(" · ")
            tail = body[i:]
            body = body[:i]
        for n in range(len(body), 0, -1):
            cand = head + (body[:n - 1] + "…" if n < len(body) else body) + tail
            if font.measure(cand) <= avail:
                return cand
        return head + tail
    except Exception:
        return text


def _grab_geometry(root):
    """记下窗口当前的左上角坐标与尺寸，供换端后还原。

    只取位置不取尺寸是不够的：发送端 820×660、接收端 1200×780，两个尺寸差得远，
    光还原位置的话窗口会以左上角为锚点往右下"长"出去，用户看着还是跳。
    所以把尺寸也一并记下；实际摆放时以**左上角为锚**（见 _show_first_time），
    尺寸变化只体现在右边和下边，视觉上最稳。

    返回 (x, y, w, h)；拿不到（窗口未映射）时返回 None，调用方退回默认行为。
    """
    try:
        root.update_idletasks()
        x = root.winfo_x()
        y = root.winfo_y()
        w = root.winfo_width()
        h = root.winfo_height()
        # 窗口还没映射时 winfo_x/y 会返回 0 或负数占位值，这种"记下来"没有意义
        if w <= 1 or h <= 1:
            return None
        return (x, y, w, h)
    except Exception:
        return None


def switch_role(win, new_role):
    """在运行中把当前窗口换成另一端（发送端 ⇄ 接收端），不需要重开程序。

    用户要的是"界面顶部点一下就能换端"，所以这里不重启进程，做法是：
      1. 先记下**旧窗口的屏幕位置与尺寸**（换端后要还原）；
      2. 让旧窗口做收尾（发送端要停掉 HTTPS 服务与 mDNS 发布、
         接收端要断开远端连接），否则端口/组播还占着，新角色会起不来；
      3. 销毁旧 Tk 根窗口；
      4. 新建 Tk 根窗口，按新角色装配界面（**全程不可见**）；
      5. 按第 1 步记下的位置算好坐标，再一次性显形（这一步同时解决
         "切换后页面弹跳"与"切换时窗口闪两下"，见 _show_first_time）；
      6. 重新跑一次样式（新解释器对象，ttk 样式不会继承 —— 见 setup_style 注释）。

    关于"位置对齐"：
      两个端的默认尺寸不一样（发送端 820×660、接收端 1200×780），换端时尺寸
      必然变，这一点无法避免。但**位置不该跟着乱跳**：`geometry("WxH")` 不带
      坐标时，窗口管理器会把新窗口摆到它自己选的位置（常见是按"层叠"规则
      往右下错开），所以用户看到的是"点一下切换，窗口整个跑到别处去了"。
      这里的做法是换端后显式给出坐标，让新窗口的**左上角与原来重合**
      （超出屏幕时再夹回可视区内），这样切换前后窗口的锚点是稳定的。

    关于"闪两下"（用户反馈"切换的时候闪一下/两下"）：
      根因不是位置算错了，而是**显形的时机错了**。旧写法是：
          建 root（默认可见，窗口管理器先随便摆一次 → 闪 1）
          → 装配界面 → geometry 挪到对齐位置（→ 闪 2）
          → mainloop
      新写法把"显形"推迟到最后，并且装配期间绝不刷新界面，
      让窗口自始至终只出现过一次、且就在最终位置。

    任何一步出错都只写日志、不弹异常，避免"想切个角色结果程序崩了"。
    """
    try:
        old_role = getattr(win, "role", None)
        if new_role == old_role:
            return
        # ---- 1. 记下旧窗口的几何（位置 + 尺寸） ----
        try:
            root_old = win.root
        except Exception:
            root_old = None
        old_geo = _grab_geometry(root_old) if root_old is not None else None
        # ---- 2. 旧窗口收尾 ----
        try:
            if hasattr(win, "shutdown"):
                win.shutdown()
        except Exception as e:
            note("切换角色：旧端收尾时出错（已忽略）: %r" % (e,))
        try:
            if root_old is not None:
                root_old.destroy()
        except Exception:
            pass
        # ---- 3. 新窗口（装配期间不可见，避免中途露出半成品界面） ----
        args = _SWITCH_ARGS[0] or getattr(win, "args", None)
        # 关键：PhotoImage 绑在旧解释器上，旧 root 一销毁它们就作废。
        # 不清缓存的话新窗口建界面时会抛 `image "pyimageN" doesn't exist`，
        # 表现就是"点了切换，新窗口一片空白"。
        reset_icon_cache()
        root = tk.Tk()
        # 先藏起来。注意这只是"当下不可见"，Tk 在渲染时会重新映射，
        # 真正保证不闪的是 _show_first_time 的时序（见其注释）。
        try:
            root.withdraw()
        except Exception:
            pass
        if new_role == "sender":
            new_win = SenderWindow(root, args)
        else:
            new_win = ReceiverWindow(root, args)
        _ACTIVE_WIN[0] = new_win
        # ---- 4. 算好位置再一次性显形（这一步替代原来的"先显示再挪位"） ----
        _show_first_time(root, old_geo)
        root.mainloop()
    except Exception as e:
        try:
            note("切换角色失败: %r" % (e,))
        except Exception:
            pass


def _center_window(root):
    """把窗口摆到屏幕正中（找不到屏幕尺寸时原地不动）。

    只在"第一次显示窗口、又没有旧窗口位置可参考"时用。
    """
    try:
        w = root.winfo_reqwidth()
        h = root.winfo_reqheight()
        if w <= 1 or h <= 1:
            return
        sw = root.winfo_screenwidth()
        sh = root.winfo_screenheight()
        # 桌面工作区高度要扣掉任务栏：winfo_screenheight() 返回的是物理高度，
        # 不扣的话窗口底边会压在任务栏下面，看着偏下。
        work_h = sh
        try:
            parts = str(root.tk.call("wm", "maxsize", root._w)).split()
            if len(parts) == 2:
                work_h = int(float(parts[1]))
        except Exception:
            pass
        if work_h <= 1 or work_h >= sh:
            work_h = max(1, sh - px(48))
        x = max(0, (sw - w) // 2)
        y = max(0, (work_h - h) // 2)
        root.geometry("+%d+%d" % (x, y))
    except Exception:
        pass


def _show_first_time(root, target_geo=None):
    """新窗口第一次上屏：**只在最终位置显示**，中途一次都不露面。

    要解决的观感问题：用户反馈"点一下切换，窗口闪两下"。

    闪两下的两个来源：
      1. 新 Tk 根窗口建出来就处于可见状态，窗口管理器先按默认位置（层叠）
         摆一次 → 第一下闪；
      2. 我们随后再 geometry("+x+y") 挪到对齐位置 → 第二下闪。

    做法是把"显示"这一步**推迟到位置算好之后**，顺序变成：
        建窗口（先 withdraw，装配全程不可见）
        → 算好目标坐标 → 一次 geometry("+x+y") 定位置
        → 一次 update_idletasks() 让布局与位置全部生效
        → deiconify() 一次显形

    ⚠️ 关键约束：**中间任何一步都不能调用 update_idletasks() / update()**。
    Tk 有个行为——对处于"待定位置"状态的窗口调用 update，会顺带把它映射上屏。
    一旦在装配过程中 update 了，窗口就会带着未完成的布局闪一下，
    后面的 deiconify 顶多是"再闪一次"，等于白改。
    所以本函数第一件事就是自己调用一次 update_idletasks，把"显形"和
    "刷新布局"这两件事一次性收在这里做，别人不用管。

    target_geo 为 None（换端时没拿到旧窗口坐标）→ 居中摆放。
    """
    try:
        if target_geo is None:
            # 没有旧坐标可参考 → 居中，比让窗口管理器随便丢个层叠位置好得多。
            _center_window(root)
        else:
            root.update_idletasks()          # 让布局先生效，尺寸才是准的
            w = root.winfo_width()
            h = root.winfo_height()
            if w <= 1:
                w = root.winfo_reqwidth()
            if h <= 1:
                h = root.winfo_reqheight()
            sw = root.winfo_screenwidth()
            sh = root.winfo_screenheight()
            ox, oy = target_geo[0], target_geo[1]
            # 左上角与切换前对齐；超屏则夹回可视区（接收端宽 1200，
            # 贴着屏幕右边时不夹就会有一大截跑到屏幕外，用户以为"窗口不见了"）
            x = max(0, min(ox, max(0, sw - w)))
            y = max(0, min(oy, max(0, sh - h)))
            root.geometry("+%d+%d" % (x, y))
            root.update_idletasks()          # 位置 + 布局一起生效，之后才允许显形
        root.deiconify()
    except Exception as e:
        # 显形这一步绝不能失败，否则窗口就"切没了"。兜底直接 deiconify。
        try:
            root.deiconify()
        except Exception:
            pass
        try:
            note("切换角色：窗口定位失败（已忽略）: %r" % (e,))
        except Exception:
            pass


def _make_switch_btn(parent, win, new_role):
    """生成界面上的【⇄ 切换】按钮。

    文案为"⇄ 切换"（用户要求："切换是切换的按钮，做一个平行对向的双箭头
    在切换文字前面"）：

        ⇄  切换

    箭头用 U+21C4（RIGHTWARDS ARROW OVER LEFTWARDS ARROW，"⇄"），
    这正是"平行对向的双箭头"—— 上面一个向右、下面一个向左，两条平行线。

    样式是**无底色**，并且**箭头与文字各自着色**（用户明确要求："无底色，
    双箭头和文字各自颜色（发送端后面就变成绿色，接收端后面就变成蓝色）"）：

        在发送端窗口里：   ⇄ 绿色    切换 深灰
        在接收端窗口里：   ⇄ 蓝色    切换 深灰

    "同一行里两种颜色"是 ttk.Button 做不到的（它只有单一 foreground），
    ttk 的 Style.map 也换不出这个效果，所以这里用 **tk.Canvas 自绘**：
    Canvas 上放两段文字（箭头 / "切换"），各给各的 fill，互不影响。
    自绘按钮要自己补的三件事都做了：
      · 点击与悬停：Canvas 绑 Button-1 / Enter / Leave，悬停换底色 + 手型光标；
      · 可点区域：Canvas 的宽高按两段文字实测宽度算好（不是写死），
        水平用 text 的 anchor 定死，缩放（UI_K）下也不会错位；
      · 对外接口：仍然暴露 cget("text")，返回完整"⇄  切换"，
        这样自检脚本、以及任何按控件对象取文案的地方都不用改。

    注意与旧文案的区别：旧版是"切换为发送端 / 切换为接收端"，把目的端写进按钮。
    现在按钮只写"⇄ 切换"，**目的端由同一行的端名文字承担** —— 按钮紧跟在该端名
    后面（如"发送端 · ⇄ 切换"），所以"当前是哪端"和"点这个能切走"在同一处
    同时可读，不需要再在按钮上重复一遍目标端。
    """
    # 箭头颜色 = **目标端**的主色（用户原话："在发送端的切换应该是蓝色
    # 切换到接收端的颜色，接收端的切换应该是绿色 切换到发送端的颜色"）：
    #
    #     发送端窗口里（按钮用来"切到接收端"）→ 箭头蓝（接收端主色）
    #     接收端窗口里（按钮用来"切到发送端"）→ 箭头绿（发送端主色）
    #
    # 这个配色是"预告要去哪一端"：箭头的颜色就是点完之后你所在那个界面的主色，
    # 点之前就知道目的地长什么样，不会误操作。
    # （曾经写成"跟着当前端走"，那是反的 —— 用户要的是跟着目标端。）
    to_sender = (new_role == "sender")         # new_role 就是"要切到哪端"
    arrow_fg = C_GREEN if to_sender else C_ACC
    arrow_hover = "#0d6a0d" if to_sender else C_ACC_D
    hover_bg = "#eaf4ea" if to_sender else "#e8f1fb"
    # "切换"两个字也用主色（用户要求："双箭头和文字也都要着色"）。
    # 之前文字用次要灰 C_TXT2，箭头的颜色优势不明显；现在两段都上色，
    # 整块就是一个有颜色的可点文字，和普通灰字一眼能分开。
    # 文字比箭头略微收深一点（同色系），保持"箭头是重点、文字跟读"的层次。
    word_fg = "#0d6a0d" if to_sender else C_ACC_D
    word_hover = C_GREEN if to_sender else C_ACC

    ARROW = "\u21c4"
    WORD = "切换"
    SWITCH_TEXT = "%s  %s" % (ARROW, WORD)

    b = tk.Canvas(parent, bg=C_CARD, highlightthickness=0, bd=0, cursor="hand2")
    # 先画文字、再按它们的实测宽度定 Canvas 尺寸 —— 顺序反过来的话，
    # 字号还没生效就量宽度，会按默认字体算出一个偏小/偏大的框。
    a_id = b.create_text(0, 0, text=ARROW, font=FONT, fill=arrow_fg,
                         anchor="w", tags=("arrow",))
    w_id = b.create_text(0, 0, text=WORD, font=FONT, fill=word_fg,
                         anchor="w", tags=("word",))
    b.update_idletasks()
    a_box = b.bbox(a_id) or (0, 0, 0, 0)
    w_box = b.bbox(w_id) or (0, 0, 0, 0)
    a_w = a_box[2] - a_box[0]
    w_w = w_box[2] - w_box[0]
    gap = px(4)
    pad_x, pad_y = px(6), px(4)
    text_h = max(a_box[3] - a_box[1], w_box[3] - w_box[1])
    cw = pad_x * 2 + a_w + gap + w_w
    ch = pad_y * 2 + text_h
    # 把两段文字重新摆到"左内边距 → 箭头 → 间隙 → 文字"，垂直居中
    b.coords(a_id, pad_x, ch / 2.0)
    b.coords(w_id, pad_x + a_w + gap, ch / 2.0)
    b.configure(width=cw, height=ch)

    # 按钮的可用状态：传输进行中必须禁止换端（见下方 set_enabled 注释）。
    _state = {"enabled": True}

    def _paint(fg_a, fg_w, bg):
        try:
            b.configure(bg=bg)
            b.itemconfigure(a_id, fill=fg_a)
            b.itemconfigure(w_id, fill=fg_w)
        except Exception:
            pass

    def _click(_e=None):
        if not _state["enabled"]:
            return
        switch_role(win, new_role)

    def _enter(_e=None):
        # 悬停才浮出浅色底：平时完全融进标题区，指上去才像"这是个按钮"
        if not _state["enabled"]:
            return
        _paint(arrow_hover, word_hover, hover_bg)

    def _leave(_e=None):
        if not _state["enabled"]:
            return
        _paint(arrow_fg, word_fg, C_CARD)

    b.bind("<Button-1>", _click)
    b.bind("<Enter>", _enter)
    b.bind("<Leave>", _leave)

    # ---- 传输中禁止换端 ----
    # 用户要求："传输过程中不能切换，切换按钮不可点击"。
    # 原因很实在：switch_role 会先 shutdown 旧端（停 HTTPS 服务、断远端连接）
    # 再销毁窗口 —— 传输正跑着的时候这么干，等于中途把连接抽掉，
    # 轻则这单传输出错，重则残留半截临时文件。
    # 所以传输一旦开始，就把这个按钮置灰 + 解绑点击。
    #
    # 置灰用的是 C_TXT3（浅灰，和"禁用态"的其它控件一致），
    # 同时把 cursor 从 hand2 换回箭头，让"点不了"这件事有视觉与指针双重反馈。
    def set_enabled(on):
        on = bool(on)
        if _state["enabled"] == on:
            return
        _state["enabled"] = on
        try:
            if on:
                b.configure(cursor="hand2")
                _paint(arrow_fg, word_fg, C_CARD)
            else:
                b.configure(cursor="")
                _paint(C_TXT3, C_TXT3, C_CARD)
        except Exception:
            pass

    b.set_enabled = set_enabled        # 供传输开始时调用
    b.is_enabled = lambda: _state["enabled"]

    # 自绘控件没有 cget("text")，但自检和调试都靠它认按钮，所以补一个。
    # 注意：**不能无脑返回 None**。原先这里对未知 opt 直接 return None，
    # 把 Canvas 自己的 cget（读 bg、cursor 等）也一起盖掉了 —— 自检里
    # "按钮无底色"这条一读 cget("bg") 就拿到 None，看着像"没设底色"，
    # 其实是接口被劫持了。正确做法：只截下 text/style 两个特殊项，
    # 其余全部交回给 Canvas 原本的实现。
    _raw_cget = b.cget          # 先存下 Canvas 原生的 cget

    def _cget(opt=None):
        if opt == "text":
            return SWITCH_TEXT
        if opt == "style":
            return ""           # 自绘按钮没有 ttk 样式名；给空串而不是 None，
                                # 免得调用方 str() 之后变成 "None" 误判
        if opt is None:
            return _raw_cget()
        return _raw_cget(opt)

    b.cget = _cget
    b.switch_arrow_fg = arrow_fg      # 留档：自检要核对"箭头颜色对不对"
    b.switch_word_fg = word_fg
    b.is_switch_btn = True
    return b



def choose_role(root):
    detect_ui_scale(root)
    # 窗口标题栏（任务栏上显示的就是它）用英文产品名 —— 短、不易被截断，
    # 且与 exe 文件名一致，用户对得上号。页面内的标题也是英文（见下）。
    root.title(APP_NAME)
    root.geometry("%dx%d" % (px(560), px(410)))
    root.configure(bg=C_BG)
    setup_style(root)

    wrap = tk.Frame(root, bg=C_CARD, highlightthickness=1, highlightbackground=C_LINE)
    wrap.pack(fill=tk.BOTH, expand=True, padx=16, pady=16)
    apply_window_icon(root)

    head = tk.Frame(wrap, bg=C_CARD)
    head.pack(fill=tk.X, padx=22, pady=(22, 4))
    app_img = ui_app_icon_small(px(40))
    if app_img is not None:
        tk.Label(head, image=app_img, bg=C_CARD).pack(side=tk.LEFT, padx=(0, 12))
    # v3.9.0 改名的界面约定（与发送端/接收端/关于页一致）：
    #   **标题一律英文 APP_NAME**（窗口标题栏 + 页面顶部大字），
    #   **正文一律中文**（说明、按钮、副标题里不出现英文产品名）。
    # 之前做成"中文大字 + 英文小字"的双行，是把两个产品名并列了，
    # 看着像两个名字；标题只留一个英文，下面正文全中文。
    tk.Label(head, text=APP_NAME, font=("Microsoft YaHei UI", 16, "bold"),
             bg=C_CARD, fg=C_TXT).pack(side=tk.LEFT)
    tk.Label(wrap, text="两台电脑分别打开本软件，一台选发送端，一台选接收端",
             font=FONT, bg=C_CARD, fg=C_TXT3).pack(anchor="w", padx=22, pady=(0, 16))

    choice = {"v": None}

    def pick(v):
        choice["v"] = v
        root.destroy()

    def role_card(parent, key, title, sub, icon):
        # 两张卡各用各的主色底：发送端淡绿、接收端淡蓝。
        # 这是"主界面就先把两端颜色区分开"的那一步 —— 点进去之后的窗口、
        # 面板色块、按钮都沿用同一个颜色，一路不会串。
        is_send = (key == "sender")
        tint = C_GREEN_L if is_send else C_ACC_L
        main = C_GREEN if is_send else C_ACC
        f = tk.Frame(parent, bg=tint, highlightthickness=1, highlightbackground=C_LINE,
                     cursor="hand2")
        f.pack(fill=tk.X, padx=22, pady=6)
        inner = tk.Frame(f, bg=tint, cursor="hand2")
        inner.pack(fill=tk.X, padx=16, pady=14)
        # 左侧主色竖条，和两端窗口标题栏的竖条同款
        tk.Frame(inner, width=3, height=36, bg=main).pack(side=tk.LEFT, padx=(0, 12))
        up_img, down_img = ui_arrow_icons()
        pic = down_img if not is_send else up_img
        if pic is not None:
            tk.Label(inner, image=pic, bg=tint).pack(side=tk.LEFT, padx=(0, 14))
        else:
            tk.Label(inner, text=icon, font=FONT_B, bg=tint,
                     fg=main).pack(side=tk.LEFT, padx=(0, 14))
        col = tk.Frame(inner, bg=tint, cursor="hand2")
        col.pack(side=tk.LEFT)
        tk.Label(col, text=title, font=FONT_B, bg=tint, fg=main,
                 cursor="hand2").pack(anchor="w")
        tk.Label(col, text=sub, font=FONT_S, bg=tint, fg=C_TXT2,
                 cursor="hand2").pack(anchor="w")
        for w in [f, inner, col] + list(inner.winfo_children()) + list(col.winfo_children()):
            try:
                w.bind("<Button-1>", lambda e, k=key: pick(k))
            except Exception:
                pass
        return f

    role_card(wrap, "sender", "发送端", "这台电脑把文件传出去（原电脑）", "\U0001F4E4")
    role_card(wrap, "receiver", "接收端", "这台电脑把文件收进来（新电脑）", "\U0001F4E5")

    foot = tk.Frame(wrap, bg=C_CARD)
    foot.pack(fill=tk.X, padx=22, pady=(14, 18))
    tk.Label(foot, text="提示：接收端点【扫描】可自动找到同网段的发送端，不用手抄 IP。",
             font=FONT_S, bg=C_CARD, fg=C_TXT3).pack(side=tk.LEFT)
    # 主页最右端的【关于】（与两端窗口右上角那颗是同一个页面）
    ttk.Button(foot, text="ⓘ 关于", style="About.TButton",
               command=lambda: open_about(None)).pack(side=tk.RIGHT)

    root.mainloop()
    return choice["v"]


def _selftest(popup=False):
    """打包后的冒烟测试：确认 tkinter / tcl-tk 运行库真的被带进 exe 了。"""
    out = []
    ok = True
    out.append("exe 自检  version=%s  frozen=%s" % (VERSION, FROZEN))
    out.append("产品版本   : %s  (%s)" % (APP_VER, APP_CN))
    out.append("运行环境   : %s（最低要求 %s）" % (_os_desc().replace("当前系统：", ""), SYS_MIN))
    out.append("executable : %s" % sys.executable)
    out.append("base dir   : %s" % _base_dir())
    out.append("conf path  : %s" % CONF)
    try:
        import tkinter as _tk
        out.append("tkinter    : OK  TkVersion=%s  TclVersion=%s" % (_tk.TkVersion, _tk.TclVersion))
    except Exception as e:
        ok = False
        out.append("tkinter    : 缺失 -> %r" % (e,))
        _tk = None
    if _tk is not None:
        try:
            r = _tk.Tk()
            r.withdraw()
            r.update()
            out.append("Tk 窗口    : OK  (%dx%d)" % (r.winfo_screenwidth(), r.winfo_screenheight()))
            # 自定义图标：内嵌 base64 -> PhotoImage（顺手验一下真能解出来）
            try:
                _img = _tk.PhotoImage(data=_ICON_ABOUT_B64)
                out.append("图标资源   : OK  (%d×%d)" % (_img.width(), _img.height()))
            except Exception as e:
                out.append("图标资源   : 失败（不影响传输）-> %r" % (e,))
            r.destroy()
        except Exception as e:
            ok = False
            out.append("Tk 窗口    : 创建失败 -> %r" % (e,))
    try:
        srv = build_sender_server(0, roots=[_base_dir()], token="", allow_write=False)
        port = srv.server_address[1]
        # 注意：这里不能调 srv.shutdown()。socketserver 的 shutdown() 会等
        # serve_forever() 退出的事件，而自检并没有启动该线程 —— 会永久阻塞。
        srv.server_close()
        out.append("内置服务   : OK  (随机端口 %d 绑定成功)" % port)
    except Exception as e:
        ok = False
        out.append("内置服务   : 失败 -> %r" % (e,))

    # 自签证书 + 真实 HTTPS 往返（生成 -> 加载 -> 握手 -> 调接口）
    try:
        cert = os.path.join(_data_dir(), "server.crt")
        key = os.path.join(_data_dir(), "server.key")
        t0 = time.time()
        ensure_cert(cert, key)
        gen = time.time() - t0
        srv2 = build_sender_server(0, roots=[_base_dir()], token="selftest", tls=True,
                                   certfile=cert, keyfile=key, bind="127.0.0.1")
        p2 = srv2.server_address[1]
        threading.Thread(target=srv2.serve_forever, daemon=True).start()
        try:
            inf = Remote("127.0.0.1", p2, "selftest").connect()
            tls_ok = inf.get("app") == APP and inf.get("tls") is True
        finally:
            srv2.shutdown()
            srv2.server_close()
        out.append("自签证书   : OK  (生成 %.2fs, %d 字节)  指纹 %s"
                   % (gen, os.path.getsize(cert), cert_fingerprint(cert)))
        out.append("HTTPS 往返 : %s  (TLS 握手 + 调用 /api/info)" % ("OK" if tls_ok else "失败"))
        ok = ok and tls_ok
    except Exception as e:
        ok = False
        out.append("HTTPS 往返 : 失败 -> %r" % (e,))

    # mDNS 发布（端口被别的进程占住也只提示，不算失败）
    try:
        md = MdnsResponder(9, log=lambda m: None)
        started = md.start()
        md.stop()
        out.append("mDNS 发布  : %s" % ("OK" if started else
                                     "失败（端口占用？不影响手动填 IP）-> %s" % (md.error or "")))
    except Exception as e:
        out.append("mDNS 发布  : 失败 -> %r" % (e,))

    tk6 = new_token(6)
    out.append("令牌生成   : %s" % ("OK  (6 位纯数字, 本次示例 %s)" % tk6
                                     if (len(tk6) == 6 and tk6.isdigit()) else "异常"))
    out.append("结果       : %s" % ("全部通过" if ok else "存在问题"))
    txt = "\n".join(out)
    note(txt)
    try:                              # 结果始终落盘，方便自动化核对
        with open(os.path.join(_data_dir(), "selftest_result.txt"), "w",
                  encoding="utf-8") as f:
            f.write(txt + "\n")
    except OSError:
        pass
    if popup:                         # 只有显式要求才弹窗（避免自动化卡住）
        try:
            import tkinter as _t2
            from tkinter import messagebox as _mb
            r = _t2.Tk()
            r.withdraw()
            _mb.showinfo("自检结果", txt)
            r.destroy()
        except Exception:
            pass
    return 0 if ok else 1


def main(argv=None):
    # --windowed exe 没有控制台，未捕获异常默认被 PyInstaller 静默吞掉，
    # 现场只能看到"窗口画不出来/一闪就没"，诊断无从下手。挂全局钩子把
    # 异常写进 lanshare_error.log（note() 自己挑路径），才有据可查。
    def _exc_hook(tp, v, tb):
        try:
            import traceback as _tb
            note("未捕获异常:", "".join(_tb.format_exception(tp, v, tb)))
        except Exception:
            pass
    sys.excepthook = _exc_hook
    ap = argparse.ArgumentParser(description="局域网双机文件互传（桌面版）")
    ap.add_argument("--role", choices=["sender", "receiver"], default=None)
    ap.add_argument("--port", type=int, default=DEFAULT_PORT)
    ap.add_argument("--token", default="")
    ap.add_argument("--roots", default="", help=r"限定共享目录, 多個用 ; 分隔, 如 C:\;D:\资料")
    ap.add_argument("--allow-write", action="store_true", help="发送端允许接收端上传文件")
    ap.add_argument("--no-tls", dest="notls", action="store_true",
                    help="关闭 HTTPS，改用明文 HTTP（仅排障用）")
    ap.add_argument("--cert", default="", help="自定义证书 PEM（与 --key 配套）")
    ap.add_argument("--key", default="", help="自定义私钥 PEM（与 --cert 配套）")
    ap.add_argument("--selftest", action="store_true", help="自检后退出（打包验证用）")
    ap.add_argument("--popup", action="store_true", help="自检结果用弹窗显示")
    ap.add_argument("--about", action="store_true",
                    help="只打开【关于】页（核对版本号 / 截图用）")
    ap.add_argument("--auto-start", dest="auto_start", action="store_true",
                    help="发送端打开窗口后立刻启动服务（命令行下发时省一次点击）")
    a = ap.parse_args(argv)
    a.roots = [x.strip() for x in a.roots.split(";") if x.strip()]

    if a.selftest:
        return _selftest(popup=a.popup)

    if a.about:
        # 只打开【关于】页：核对版本号/截图用，主界面背后留一个隐藏的 Tk 当宿主
        host = tk.Tk()
        host.withdraw()
        apply_window_icon(host)
        open_about(None)
        host.mainloop()
        return 0

    if tk is None:
        note("=" * 66)
        note(" 这个 Python 没有 tkinter，无法显示窗口。")
        note("=" * 66)
        note(" 原因：tkinter 是 Python 自带的图形界面库，但精简版/嵌入式版")
        note("       以及某些软件内置的 Python 会把它裁掉。")
        note("")
        note(" 解决办法（任选其一）：")
        note("   1) 到 python.org 下载 Windows 官方安装包，安装时保持默认勾选")
        note("      （其中包含 tcl/tk and IDLE），装完重新双击本程序。")
        note("   2) 若已装官方 Python，用它的完整路径启动，例如：")
        note('      "C:\\Python313\\python.exe" lanshare_gui.py')
        note("")
        note(" 或者改用浏览器版（同样能双机互传，不依赖 tkinter）：")
        note("   发送端： python lan_transfer.py serve --root \"D:\\资料\" --token 1234")
        note("   接收端： python lan_transfer.py pull")
        note("=" * 66)
        if NOCONSOLE:
            try:
                import tkinter as _t3              # 走到这里通常也没有，纯兜底
                _t3.Tk().withdraw()
            except Exception:
                pass
            from tkinter import messagebox as _mb2
            _mb2.showerror("缺少 tkinter", "本程序需要 tkinter，详见同目录 lanshare_error.log")
        return 1

    root = tk.Tk()
    role = a.role
    if not role:
        role = choose_role(root)
        if not role:
            return 0
        root = tk.Tk()          # 选择窗口已销毁，重开一个当主窗口
    # 记下启动参数：标题栏的【切换】按钮换端时要复用同一套参数
    # （端口、令牌、共享目录等），不然切过去就丢了。
    _SWITCH_ARGS[0] = a
    # 首次启动也走"装配期间不可见 → 算好位置再一次性显形"的路径，
    # 免得用户在启动瞬间看到窗口先在左上角/层叠位置露一下再跳。
    try:
        root.withdraw()
    except Exception:
        pass
    if role == "sender":
        win = SenderWindow(root, a)
        if getattr(a, "auto_start", False):
            # 给窗口留出构建时间再启动，避免"界面还没画完就在写日志"
            root.after(400, win.start)
    else:
        win = ReceiverWindow(root, a)
    _ACTIVE_WIN[0] = win
    _show_first_time(root, None)          # 首次启动没有旧坐标 → 居中显示
    root.mainloop()
    return 0


if __name__ == "__main__":
    sys.exit(main())
